const AppContent: React.FC = () => {
  const { t, language, setLanguage, dir } = useLanguage();
  const [user, setUser] = useState<User | null>(null);
  const [view, setView] = useState<ViewState>('LANDING');

  const [username, setUsername] = useState('');
