        >
            <Languages className="w-5 h-5"/>
            <span className="font-bold uppercase">{language}</span>
        </button>

        {/* INSTALL WIZARD - MANDATORY IF NO ADMIN */}
        {view === 'INSTALL' && (
            <InstallationWizard onInstalled={() => { setIsInstalled(true); setView('LANDING'); }} />
