  // 1. Check Installation Status & Handle Special URLs
  useEffect(() => {
      const init = async () => {
          setIsLoading(true);

          // Check installation (local or API)
          const installed = await ApiService.checkInstallStatus();
          setIsInstalled(installed);

          // Check URL Params for "Unique Link" behavior or Auto-Quiz
          const params = new URLSearchParams(window.location.search);
          const mode = params.get('mode'); // ?mode=staff
          const qId = params.get('quizId'); // ?quizId=123
          const setup = params.get('setup'); // ?setup=true

          // Determine initial view
          if (!installed || setup === 'true') {
              setView('INSTALL');
          } else if (mode === 'staff') {
              setView('LOGIN_STAFF');
          } else if (qId) {
              setAutoLaunchQuizId(qId);
              setView('LOGIN_STUDENT');
          } else {
              // Default to Student Landing
              setView('LANDING');
          }

          // Auto-Restore Session if available
          const sessionUser = StorageService.getSession();
          if (sessionUser) {
              setUser(sessionUser);
              setView('DASHBOARD');
          }

          setIsLoading(false);
      };

      init();
