                            <button
                                type="submit"
                                className={`w-full py-3 px-4 text-white font-bold rounded-lg transition transform hover:scale-[1.02] shadow-lg ${currentPath === '/login/student' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-gray-800 hover:bg-gray-900'}`}
                            >
                                {t('login')}
                            </button>
                        </form>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

