                                {hasUnread && <span className="w-2 h-2 bg-green-500 rounded-full"></span>}
                            </button>
                        );
                     })}
                </div>
             </div>
             <div className="w-2/3 flex flex-col bg-white">
                  {selectedStudentId ? (
                       <>
