    useEffect(() => {
        setUsers(StorageService.getUsers());
    }, []);

    const cleanInput = (str: string) => str.trim().toLowerCase().replace(/[^a-z0-9]/g, '');

    const handleCreateUser = () => {
        if(!newName.trim()) return;
        const cleanName = cleanInput(newName);
        const randomSuffix = Math.floor(Math.random() * 9000) + 1000;
        const username = `mod_${cleanName.substring(0, 10)}_${randomSuffix}`;
        const password = Math.floor(100000 + Math.random() * 900000).toString();

        const newUser: User = {
            id: `usr-${Date.now()}`,
            name: newName.trim(),
            username,
            password,
            role: UserRole.MODERATOR,
            accountType: 'INDIVIDUAL'
        };

        StorageService.saveUser(newUser);
        setIsCreating(false);
        setNewName('');
        alert(`${t('moderator')} ${t('completed')}!\nID: ${username}\nPass: ${password}`);
        setUsers(StorageService.getUsers());
    };

    const handleDeleteUser = (id: string) => {
        if (confirm(t('delete') + '?')) {
            StorageService.deleteUser(id);
