        const users = StorageService.getUsers();
        const admin = users.find(u => u.role === UserRole.ADMIN);
        if (admin) setAdminUsername(admin.username);
    }, []);

    const handleUpdateAdminProfile = () => {
        if (!adminUsername.trim()) return;
        if (adminNewPass && adminNewPass !== adminConfirmPass) {
            alert(t('passwordMismatch'));
            return;
        }

        const users = StorageService.getUsers();
        const adminUser = users.find(u => u.role === UserRole.ADMIN);
        if (adminUser) {
            const updated: User = { 
                ...adminUser, 
                username: adminUsername,
                ...(adminNewPass ? { password: adminNewPass } : {})
            };
            StorageService.saveUser(updated);
            alert(t('adminUpdateSuccess'));
            setAdminNewPass('');
            setAdminConfirmPass('');
        }
    };

    const handleBackupDB = () => {
        const json = StorageService.exportFullDB();
        const blob = new Blob([json], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `tinmel_backup_${new Date().toISOString().slice(0,10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        alert(t('backupSuccess'));
    };

    return (
        <div className="max-w-2xl mx-auto bg-white p-8 rounded-xl shadow-sm border space-y-8 animate-fade-in">
            {/* Profile Section */}
            <div className="space-y-6">
                <h2 className="text-xl font-bold mb-6 flex items-center gap-2 text-gray-700">
                    <Settings className="w-6 h-6"/> {t('adminProfile')}
                </h2>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t('username')}</label>
                    <input className="w-full border rounded p-3 bg-gray-50" value={adminUsername} onChange={e => setAdminUsername(e.target.value)} />
                </div>
                <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-md text-sm text-yellow-800 mb-4">
                    <Lock className="w-4 h-4 inline mr-2"/> {t('changePassword')}
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t('newPassword')}</label>
                    <input type="password" className="w-full border rounded p-3" value={adminNewPass} onChange={e => setAdminNewPass(e.target.value)} placeholder="••••••" />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">{t('confirmPassword')}</label>
                    <input type="password" className="w-full border rounded p-3" value={adminConfirmPass} onChange={e => setAdminConfirmPass(e.target.value)} placeholder="••••••" />
                </div>
                <button onClick={handleUpdateAdminProfile} className="w-full bg-blue-600 text-white py-3 rounded hover:bg-blue-700 flex items-center justify-center gap-2 font-medium">
                    <Check className="w-4 h-4 rtl:flip"/> {t('save')}
                </button>
            </div>

            {/* Backup Section */}
            <div className="pt-8 border-t space-y-4">
                <h2 className="text-xl font-bold flex items-center gap-2 text-indigo-700">
                    <Database className="w-6 h-6"/> {t('backupDB')}
                </h2>
                <p className="text-sm text-gray-600">{t('backupDesc')}</p>
                <div className="bg-blue-50 p-4 rounded-lg border border-blue-200 text-sm space-y-2">
                    <h3 className="font-bold text-blue-800 flex items-center gap-2"><Info className="w-4 h-4"/> {t('dataSyncInfo')}</h3>
                    <p className="text-blue-900">{t('dataSyncDesc')}</p>
                    <ul className="list-disc list-inside text-blue-800 space-y-1 ml-2">
                        <li>{t('dataSyncStep1')}</li>
                        <li>{t('dataSyncStep2')}</li>
                        <li>{t('dataSyncStep3')}</li>
                    </ul>
                    <p className="text-blue-800 font-bold mt-2 pt-2 border-t border-blue-200">{t('browserWarning')}</p>
                </div>
                <button onClick={handleBackupDB} className="w-full bg-indigo-50 text-indigo-700 border border-indigo-200 py-3 rounded hover:bg-indigo-100 flex items-center justify-center gap-2 font-medium transition">
                    <FileDown className="w-5 h-5"/> {t('backupDB')}
                </button>
            </div>
        </div>
    );
};

