// Helper to safely get env vars without crashing browser simulator
const getEnv = (key: string, fallback: string) => {
  try {
    // @ts-ignore
    if (typeof process !== 'undefined' && process.env) {
      // @ts-ignore
      return process.env[key] || fallback;
    }
  } catch (e) {
    // Ignore error in browser environment
  }
  return fallback;
};

export const QUESTION_TYPE_LABELS: Record<string, string> = {
  MCQ: 'Choix Multiples (Texte)',
  IMAGE_MCQ: 'Choix Multiples (Image)',
  BOOLEAN: 'Vrai ou Faux',
  ESSAY: 'Question Ouverte / Essai',
  MATCHING: 'Appariement',
  SHORT_ANSWER: 'Réponse Courte',
  FILL_IN_THE_BLANK: 'Texte à trous',
};

import { GoogleGenAI, Type } from "@google/genai";
import { Question, QuestionType, Language } from "../types";

const initAI = () => {
    let apiKey = '';
    try {
        // @ts-ignore
        if (typeof process !== 'undefined' && process.env) {
            // @ts-ignore
            apiKey = process.env.API_KEY || process.env.REACT_APP_GEMINI_API_KEY || '';
        }
    } catch (e) {
        console.warn("Environment variables not available in this context. AI features may not work if API Key is not injected.");
    }

    // Fallback for AI Studio simulation if key is injected globally
    // @ts-ignore
    if (!apiKey && typeof window !== 'undefined' && window.GEMINI_API_KEY) {
        // @ts-ignore
        apiKey = window.GEMINI_API_KEY;
    }

    return new GoogleGenAI({ apiKey });
};

export const GeminiService = {
  async generateQuizQuestions(topic: string, count: number = 5, language: Language = 'fr'): Promise<Question[]> {
    const ai = initAI();

    const schema = {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
                text: { type: Type.STRING },
                type: { 
                    type: Type.STRING, 
                    enum: [
                        QuestionType.MCQ, 
                        QuestionType.BOOLEAN, 
                        QuestionType.SHORT_ANSWER,
                        QuestionType.MATCHING,
                        QuestionType.ESSAY,
                        QuestionType.FILL_IN_THE_BLANK
                    ] 
                },
                points: { type: Type.NUMBER },
                options: { type: Type.ARRAY, items: { type: Type.STRING } },
                correctAnswer: { type: Type.STRING },
                matchingPairs: { 
                    type: Type.ARRAY, 
                    items: { 
                        type: Type.OBJECT, 
                        properties: {
                            left: { type: Type.STRING },
                            right: { type: Type.STRING }
                        }
                    } 
                },
                explanation: { type: Type.STRING }
            },
            required: ["text", "type", "points"]
        }
    };

    const langName = language === 'ar' ? 'Arabe' : 'Français';
    const booleanInstructions = language === 'ar' ? 'Pour BOOLEAN, la réponse doit être "Vrai" ou "Faux" (je traduirai coté client).' : 'Pour BOOLEAN, la réponse doit être "Vrai" ou "Faux".';

    const prompt = `
      Génère un quiz de ${count} questions sur le sujet : "${topic}".
      Le quiz doit être OBLIGATOIREMENT en ${langName}.

      Mélange les types de questions suivants : 
      1. Choix Multiples (MCQ) : Fournis 4 options dans 'options'.
      2. Vrai/Faux (BOOLEAN) : ${booleanInstructions}
      3. Réponse Courte (SHORT_ANSWER) : Fournis la réponse attendue dans 'correctAnswer'.
      4. Appariement (MATCHING) : Fournis 4 paires d'éléments liés dans 'matchingPairs'.
      5. Question Ouverte (ESSAY) : Une question de réflexion qui demande une rédaction. Laisser 'correctAnswer' vide ou fournir des mots-clés.
      6. Texte à trous (FILL_IN_THE_BLANK) : Une phrase où les mots à deviner sont entre crochets [ ]. Exemple: "La capitale de la [France] est [Paris]".

      IMPORTANT POUR LE TYPE 'MATCHING':
      - Ne remplis PAS 'options'.
      - Ne remplis PAS 'correctAnswer'.
      - Remplis UNIQUEMENT le tableau 'matchingPairs' avec 4 objets {left: string, right: string}.

      IMPORTANT POUR LE TYPE 'FILL_IN_THE_BLANK':
      - Mets les réponses directement dans le texte entre [crochets].

      Répartis les types de manière équilibrée.
      Assure-toi que le JSON est valide et respecte le schéma.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
            responseMimeType: "application/json",
            responseSchema: schema
        }
      });

      const rawData = JSON.parse(response.text || '[]');

      return rawData.map((q: any, idx: number) => ({
        id: `gen-${Date.now()}-${idx}`,
        type: q.type,
        text: q.text,
        points: q.points || 1,
        options: q.options || [],
        correctAnswer: q.type === 'BOOLEAN' ? (String(q.correctAnswer).toLowerCase() === 'vrai' || String(q.correctAnswer).toLowerCase() === 'true') : q.correctAnswer,
        matchingPairs: q.matchingPairs || []
      }));
    } catch (error) {
      console.error("Gemini generation error", error);
      throw new Error("Impossible de générer le quiz. Vérifiez votre clé API.");
    }
  },

  async gradeEssay(questionText: string, studentAnswer: string, correctAnswerContext?: string): Promise<{ score: number; feedback: string }> {
      const ai = initAI();

      const prompt = `
        Agis comme un professeur expert. Évalue la réponse d'un étudiant à la question suivante.
        Question: "${questionText}"
        Réponse de l'étudiant: "${studentAnswer}"
        Contexte/Réponse attendue (optionnel): "${correctAnswerContext || 'N/A'}"

        Note sur 10 (où 10 est parfait).
        Retourne un objet JSON avec:
        - score: nombre entier de 0 à 10.
        - feedback: un commentaire constructif (max 30 mots) dans la même langue que la question.
      `;

      try {
          const response = await ai.models.generateContent({
              model: 'gemini-2.5-flash',
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          score: { type: Type.NUMBER },
                          feedback: { type: Type.STRING }
                      }
                  }
              }
          });

          return JSON.parse(response.text || '{"score": 0, "feedback": "Erreur d\'analyse"}');
      } catch (e) {
          console.error(e);
          return { score: 0, feedback: "Erreur lors de la correction automatique." };
      }
  }
};

import React, { useState } from 'react';
import { Quiz, Question, QuestionType, MatchingPair } from '../../types';
import { Plus, Trash2, Save, Wand2, RefreshCcw, Lock, Clock, Calendar, Image as ImageIcon, CheckSquare, Type, Split, AlignLeft, List, MousePointerClick, MessageSquare, PenTool } from 'lucide-react';
import { GeminiService } from '../../services/geminiService';
import { useLanguage } from '../../contexts/LanguageContext';

interface QuizBuilderProps {
  profId: string;
  onSave: (quiz: Quiz) => void;
  onCancel: () => void;
  availableClasses: string[];
}

const QuizBuilder: React.FC<QuizBuilderProps> = ({ profId, onSave, onCancel, availableClasses }) => {
  const { t, language, dir } = useLanguage();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [assignedClasses, setAssignedClasses] = useState<string[]>([]);
  const [accessCode, setAccessCode] = useState('');
  const [timeLimit, setTimeLimit] = useState<string>('');
  const [startDate, setStartDate] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [isPublished, setIsPublished] = useState(true);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [genTopic, setGenTopic] = useState('');

  const addQuestion = (type: QuestionType) => {
    const newQ: Question = {
      id: `q-${Date.now()}`,
      type,
      text: '',
      points: 1,
      options: (type === QuestionType.MCQ || type === QuestionType.IMAGE_MCQ) ? ['', ''] : undefined,
      correctAnswer: type === QuestionType.BOOLEAN ? true : '',
      matchingPairs: type === QuestionType.MATCHING ? [{ left: '', right: '' }, { left: '', right: '' }] : undefined
    };
    setQuestions([...questions, newQ]);
    // Scroll to bottom after adding
    setTimeout(() => {
        window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    }, 100);
  };

  const updateQuestion = (id: string, updates: Partial<Question>) => {
    setQuestions(questions.map(q => q.id === id ? { ...q, ...updates } : q));
  };

  const removeQuestion = (id: string) => {
    setQuestions(questions.filter(q => q.id !== id));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, qId: string) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updateQuestion(qId, { imageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerateAI = async () => {
    if (!genTopic) return;
    setIsGenerating(true);
    try {
      const generatedQuestions = await GeminiService.generateQuizQuestions(genTopic, 5, language);
      setQuestions([...questions, ...generatedQuestions]);
    } catch (e) {
      alert("Erreur lors de la génération. Vérifiez la clé API.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSave = () => {
    if (!title) return alert("Le titre est obligatoire");
    if (questions.length === 0) return alert("Ajoutez au moins une question.");

    const quiz: Quiz = {
      id: `quiz-${Date.now()}`,
      title,
      description,
      professorId: profId,
      questions,
      createdAt: new Date().toISOString(),
      assignedClasses: assignedClasses,
      status: isPublished ? 'PUBLISHED' : 'DRAFT',
      accessCode: accessCode.trim() || undefined,
      timeLimit: timeLimit ? parseInt(timeLimit) : undefined,
      startDate: startDate || undefined,
      dueDate: dueDate || undefined,
    };
    onSave(quiz);
  };

  const toggleClass = (cls: string) => {
      setAssignedClasses(prev => 
        prev.includes(cls) ? prev.filter(c => c !== cls) : [...prev, cls]
      );
  };

  const getTypeIcon = (type: QuestionType) => {
      switch(type) {
          case QuestionType.MCQ: return <List className="w-5 h-5"/>;
          case QuestionType.IMAGE_MCQ: return <ImageIcon className="w-5 h-5"/>;
          case QuestionType.BOOLEAN: return <CheckSquare className="w-5 h-5"/>;
          case QuestionType.SHORT_ANSWER: return <Type className="w-5 h-5"/>;
          case QuestionType.ESSAY: return <AlignLeft className="w-5 h-5"/>;
          case QuestionType.MATCHING: return <Split className="w-5 h-5"/>;
          case QuestionType.FILL_IN_THE_BLANK: return <PenTool className="w-5 h-5"/>;
          default: return <Plus className="w-5 h-5"/>;
      }
  };

  const questionTypes = [
    { type: QuestionType.MCQ, label: "QCM Texte", desc: "Questions à choix multiples classiques", icon: List, color: "bg-blue-50 text-blue-600 border-blue-200" },
    { type: QuestionType.IMAGE_MCQ, label: "QCM Image", desc: "Questions basées sur un visuel", icon: ImageIcon, color: "bg-purple-50 text-purple-600 border-purple-200" },
    { type: QuestionType.BOOLEAN, label: "Vrai / Faux", desc: "Réponse binaire simple", icon: CheckSquare, color: "bg-green-50 text-green-600 border-green-200" },
    { type: QuestionType.SHORT_ANSWER, label: "Réponse Courte", desc: "Un mot ou une phrase exacte", icon: Type, color: "bg-orange-50 text-orange-600 border-orange-200" },
    { type: QuestionType.MATCHING, label: "Appariement", desc: "Relier des éléments entre eux", icon: Split, color: "bg-pink-50 text-pink-600 border-pink-200" },
    { type: QuestionType.FILL_IN_THE_BLANK, label: "Texte à trous", desc: "Compléter les phrases", icon: PenTool, color: "bg-teal-50 text-teal-600 border-teal-200" },
    { type: QuestionType.ESSAY, label: "Rédaction (IA)", desc: "Analyse sémantique par IA", icon: MessageSquare, color: "bg-indigo-50 text-indigo-600 border-indigo-200" }
  ];

  return (
    <div className="bg-white rounded-lg shadow-lg p-6 max-w-4xl mx-auto" dir={dir}>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">{t('newQuiz')}</h2>
        <div className="text-sm text-gray-500">{questions.length} questions</div>
      </div>

      {/* Basic Info */}
      <div className="grid gap-4 mb-8 border-b pb-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700">{t('quizTitle')}</label>
              <input 
                className="mt-1 block w-full rounded-md border border-gray-300 p-2 focus:ring-blue-500 focus:border-blue-500"
                value={title} 
                onChange={(e) => setTitle(e.target.value)} 
                placeholder="Ex: Évaluation Mathématiques Chap 1"
              />
            </div>
            <div>
                <label className="block text-sm font-medium text-gray-700">{t('assignedClasses')}</label>
                <div className="mt-1 p-2 border rounded-md max-h-32 overflow-y-auto grid grid-cols-2 gap-2 bg-white">
                    {availableClasses.length === 0 && <span className="text-xs text-gray-400">{t('noClassesFound')}</span>}
                    {availableClasses.map(cls => (
                        <label 
                            key={cls} 
                            className={`flex items-center gap-2 text-sm cursor-pointer p-1.5 rounded transition-colors ${assignedClasses.includes(cls) ? 'bg-blue-50 text-blue-700 font-medium' : 'hover:bg-gray-50 text-gray-700'}`}
                        >
                            <input 
                                type="checkbox" 
                                checked={assignedClasses.includes(cls)}
                                onChange={() => toggleClass(cls)}
                                className="rounded text-blue-600 focus:ring-blue-500 h-4 w-4"
                            />
                            {cls}
                        </label>
                    ))}
                </div>
            </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700">{t('quizDesc')}</label>
          <textarea 
            className="mt-1 block w-full rounded-md border border-gray-300 p-2 focus:ring-blue-500 focus:border-blue-500"
            value={description} 
            onChange={(e) => setDescription(e.target.value)}
            placeholder="Instructions pour les élèves..."
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="bg-gray-50 p-3 rounded-md">
                <label className="block text-sm font-medium text-gray-700 flex items-center gap-1">
                    <Lock className="w-3 h-3"/> {t('accessCode')}
                </label>
                <input 
                    className="mt-1 block w-full rounded-md border border-gray-300 p-2 text-sm"
                    value={accessCode}
                    onChange={(e) => setAccessCode(e.target.value)}
                    placeholder={t('accessCodePlaceholder')}
                />
            </div>
            <div className="bg-gray-50 p-3 rounded-md">
                <label className="block text-sm font-medium text-gray-700 flex items-center gap-1">
                    <Clock className="w-3 h-3"/> {t('timer')}
                </label>
                <input 
                    type="number"
                    min="1"
                    className="mt-1 block w-full rounded-md border border-gray-300 p-2 text-sm"
                    value={timeLimit}
                    onChange={(e) => setTimeLimit(e.target.value)}
                />
            </div>
            <div className="bg-gray-50 p-3 rounded-md">
                 <label className="block text-sm font-medium text-gray-700 flex items-center gap-1">
                    <Calendar className="w-3 h-3"/> {t('startDate')}
                 </label>
                 <input 
                    type="datetime-local"
                    className="mt-1 block w-full rounded-md border border-gray-300 p-1 text-xs"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                 />
            </div>
             <div className="bg-gray-50 p-3 rounded-md">
                 <label className="block text-sm font-medium text-gray-700 flex items-center gap-1">
                    <Calendar className="w-3 h-3"/> {t('dueDate')}
                 </label>
                 <input 
                    type="datetime-local"
                    className="mt-1 block w-full rounded-md border border-gray-300 p-1 text-xs"
                    value={dueDate}
                    onChange={(e) => setDueDate(e.target.value)}
                 />
            </div>
        </div>

        <div className="flex items-center gap-2 mt-2">
            <label className="relative inline-flex items-center cursor-pointer">
                <input type="checkbox" checked={isPublished} onChange={(e) => setIsPublished(e.target.checked)} className="sr-only peer" />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                <span className="ml-3 text-sm font-medium text-gray-700">{t('publishNow')}</span>
            </label>
        </div>
      </div>

      {/* AI Generator */}
      <div className="bg-gradient-to-r from-indigo-50 to-blue-50 p-4 rounded-xl mb-8 border border-indigo-100 flex gap-4 items-center">
         <div className="p-3 bg-white rounded-full shadow-sm">
             <Wand2 className="h-6 w-6 text-indigo-600 rtl:flip"/>
         </div>
         <div className="flex-1">
             <h3 className="text-sm font-bold text-indigo-900 mb-1">{t('aiGen')}</h3>
             <input 
                className="block w-full rounded-md border border-indigo-200 p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                placeholder={t('aiPlaceholder')}
                value={genTopic}
                onChange={(e) => setGenTopic(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleGenerateAI()}
             />
         </div>
         <button 
            onClick={handleGenerateAI}
            disabled={isGenerating || !genTopic}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2 font-medium shadow-sm transition-transform active:scale-95"
         >
             {isGenerating ? <RefreshCcw className="animate-spin h-4 w-4"/> : <span className="text-lg">✨</span>}
             {t('generate')}
         </button>
      </div>

      {/* Questions List */}
      <div className="space-y-6 mb-8">
        {questions.length === 0 && (
            <div className="text-center py-12 border-2 border-dashed border-gray-300 rounded-lg bg-gray-50 flex flex-col items-center justify-center">
                <div className="bg-gray-100 p-4 rounded-full mb-3"><Plus className="w-6 h-6 text-gray-400"/></div>
                <div className="text-gray-500 font-medium mb-1">Le quiz est vide</div>
                <div className="text-sm text-gray-400">Sélectionnez un type de question ci-dessous pour commencer.</div>
