                    <Trash2 className="h-5 w-5" />
                </button>
            </div>

            <div className="flex items-center gap-3 mb-4 pr-24">
                <span className="flex items-center justify-center w-8 h-8 rounded-full bg-blue-100 text-blue-700 font-bold text-sm shrink-0">
                    {idx + 1}
                </span>
                <input 
                    className="w-full p-2 border-b border-gray-300 focus:border-blue-500 outline-none font-medium text-lg bg-transparent placeholder-gray-400"
                    value={q.text}
                    onChange={(e) => updateQuestion(q.id, { text: e.target.value })}
                    placeholder={t('questionLabel')}
                />
                <div className="flex flex-col items-center shrink-0">
                    <input 
                        type="number"
                        min="1"
                        value={q.points}
                        onChange={(e) => updateQuestion(q.id, { points: parseInt(e.target.value) })}
                        className="w-12 text-center text-sm border rounded p-1 font-bold"
                    />
                    <span className="text-[10px] text-gray-500 uppercase">{t('points')}</span>
                </div>
            </div>

             {/* Image Upload for Image MCQ */}
             {q.type === QuestionType.IMAGE_MCQ && (
              <div className="mb-4 ms-11">
                <div className="flex items-center gap-4">
                  {q.imageUrl ? (
                    <div className="relative group/image">
                      <img src={q.imageUrl} alt="Question" className="h-40 w-auto object-cover rounded-lg border shadow-sm" />
                      <button 
                        type="button"
                        onClick={() => updateQuestion(q.id, { imageUrl: undefined })}
                        className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1.5 shadow-md hover:bg-red-600 transition-transform hover:scale-110"
                        title={t('delete')}
                      >
                        <Trash2 className="w-3 h-3"/>
                      </button>
                    </div>
                  ) : (
                    <label className="flex flex-col items-center justify-center w-full max-w-sm h-32 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:bg-gray-50 hover:border-blue-400 transition-colors">
                        <ImageIcon className="text-gray-400 w-8 h-8 mb-2"/>
                        <span className="text-sm text-gray-500 font-medium">{t('upload')}</span>
                        <input 
                            type="file" 
                            accept="image/*" 
                            className="hidden" 
                            onChange={(e) => handleImageUpload(e, q.id)} 
                            onClick={(e) => (e.currentTarget.value = '')} // Allow re-uploading same file
                        />
                    </label>
                  )}
                </div>
              </div>
            )}

            {/* MCQ & Image MCQ Options */}
            {(q.type === QuestionType.MCQ || q.type === QuestionType.IMAGE_MCQ) && (
                <div className="space-y-2 ms-11">
                    {q.options?.map((opt, oIdx) => (
                        <div key={oIdx} className="flex items-center gap-3 group/option">
                            <input 
                                type="radio" 
                                name={`correct-${q.id}`} 
                                checked={q.correctAnswer === opt && opt !== ''} 
                                onChange={() => updateQuestion(q.id, { correctAnswer: opt })}
                                className="w-4 h-4 text-blue-600 cursor-pointer"
                                title="Marquer comme réponse correcte"
                            />
                            <div className="flex-1 relative">
                                <input 
                                    className={`w-full p-2 border rounded text-sm transition-colors ${q.correctAnswer === opt && opt !== '' ? 'border-green-500 bg-green-50' : 'focus:border-blue-400'}`}
                                    value={opt}
                                    onChange={(e) => {
                                        const newOpts = [...(q.options || [])];
                                        newOpts[oIdx] = e.target.value;
                                        // Update correct answer if changed
                                        const updates: Partial<Question> = { options: newOpts };
                                        if (q.correctAnswer === opt) updates.correctAnswer = e.target.value;
                                        updateQuestion(q.id, updates);
                                    }}
                                    placeholder={`${t('option')} ${oIdx + 1}`}
                                />
                                {q.options && q.options.length > 2 && (
                                    <button 
                                        onClick={() => {
                                            const newOpts = q.options?.filter((_, i) => i !== oIdx);
                                            updateQuestion(q.id, { options: newOpts });
                                        }}
                                        className="absolute right-2 top-2 text-gray-300 hover:text-red-500 opacity-0 group-hover/option:opacity-100 transition-opacity"
                                    >
                                        <Trash2 className="w-4 h-4"/>
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}
                    <button 
                        className="text-sm text-blue-600 hover:text-blue-800 font-medium flex items-center gap-1 mt-2"
                        onClick={() => updateQuestion(q.id, { options: [...(q.options || []), ''] })}
                    >
                        <Plus className="w-4 h-4"/> {t('addOption')}
                    </button>
                </div>
            )}

            {/* Boolean */}
            {q.type === QuestionType.BOOLEAN && (
                 <div className="flex gap-4 ms-11 mt-4">
                    <button 
                        onClick={() => updateQuestion(q.id, { correctAnswer: true })}
                        className={`flex-1 py-3 px-4 rounded-lg border-2 font-bold transition-all ${q.correctAnswer === true ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-200 hover:border-gray-300'}`}
                    >
                        {t('true')}
                    </button>
                    <button 
                        onClick={() => updateQuestion(q.id, { correctAnswer: false })}
                        className={`flex-1 py-3 px-4 rounded-lg border-2 font-bold transition-all ${q.correctAnswer === false ? 'border-red-500 bg-red-50 text-red-700' : 'border-gray-200 hover:border-gray-300'}`}
                    >
                        {t('false')}
                    </button>
                 </div>
            )}

            {/* Short Answer */}
            {(q.type === QuestionType.SHORT_ANSWER) && (
                <div className="ms-11 mt-2">
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">{t('expectedAnswer')} :</label>
                    <input 
                        className="w-full border-2 border-green-100 rounded-lg p-3 text-green-800 focus:border-green-300 focus:outline-none bg-green-50/50"
                        value={q.correctAnswer as string || ''}
                        onChange={(e) => updateQuestion(q.id, { correctAnswer: e.target.value })}
                        placeholder="Réponse exacte attendue..."
                    />
                </div>
            )}

            {q.type === QuestionType.ESSAY && (
                <div className="ms-11 mt-2 p-4 bg-yellow-50 rounded-lg border border-yellow-100 text-sm text-yellow-800 flex items-start gap-2">
                    <Wand2 className="w-5 h-5 shrink-0"/>
                    <div>
                        <p className="font-bold mb-1">Correction IA activée</p>
                        {t('aiEssayWarning')}
                    </div>
                </div>
            )}

            {/* Fill in the blank */}
            {q.type === QuestionType.FILL_IN_THE_BLANK && (
                <div className="ms-11 mt-2 p-4 bg-teal-50 rounded-lg border border-teal-100 text-sm text-teal-800 flex items-start gap-2">
                     <div className="flex-1">
                         <p className="font-bold mb-1 flex items-center gap-2"><PenTool className="w-4 h-4"/> Mode d'emploi</p>
                         <p>Écrivez votre phrase et mettez les réponses entre crochets.</p>
                         <p className="mt-1 font-mono bg-white p-1 rounded border border-teal-200 inline-block">La capitale de la [France] est [Paris].</p>
                     </div>
                </div>
            )}

            {/* Matching */}
            {q.type === QuestionType.MATCHING && (
                <div className="ms-11 mt-2 space-y-3">
                    {q.matchingPairs?.map((pair, pIdx) => (
                        <div key={pIdx} className="flex gap-3 items-center group/pair">
                            <div className="flex-1 flex items-center gap-2">
                                <span className="text-gray-400 font-mono text-xs">A</span>
                                <input 
                                    placeholder={t('matchingA')}
                                    className="w-full border rounded p-2 text-sm focus:ring-1 focus:ring-blue-500"
                                    value={pair.left}
                                    onChange={(e) => {
                                        const newPairs = [...(q.matchingPairs || [])];
                                        newPairs[pIdx] = { ...pair, left: e.target.value };
                                        updateQuestion(q.id, { matchingPairs: newPairs });
                                    }}
                                />
                            </div>
                            <Split className="text-gray-300 w-4 h-4 shrink-0"/>
                            <div className="flex-1 flex items-center gap-2">
                                <span className="text-gray-400 font-mono text-xs">B</span>
                                <input 
                                    placeholder={t('matchingB')}
                                    className="w-full border rounded p-2 text-sm focus:ring-1 focus:ring-blue-500"
                                    value={pair.right}
                                    onChange={(e) => {
                                        const newPairs = [...(q.matchingPairs || [])];
                                        newPairs[pIdx] = { ...pair, right: e.target.value };
                                        updateQuestion(q.id, { matchingPairs: newPairs });
                                    }}
                                />
                            </div>
                            <button 
                                onClick={() => {
                                    const newPairs = q.matchingPairs?.filter((_, i) => i !== pIdx);
                                    updateQuestion(q.id, { matchingPairs: newPairs });
                                }}
                                className="text-gray-300 hover:text-red-500 opacity-0 group-hover/pair:opacity-100 transition-opacity"
                            >
                                <Trash2 className="w-4 h-4"/>
                            </button>
                        </div>
                    ))}
                     <button 
                        className="text-sm text-blue-600 hover:text-blue-800 font-medium flex items-center gap-1 mt-2"
                        onClick={() => updateQuestion(q.id, { matchingPairs: [...(q.matchingPairs || []), {left: '', right: ''}] })}
                    >
                        <Plus className="w-4 h-4"/> {t('addPair')}
                    </button>
                </div>
            )}

          </div>
        ))}
      </div>

      {/* New Question Type Selector (Grid Layout) */}
      <div className="bg-gray-50 border border-gray-200 rounded-xl p-6">
          <h3 className="text-sm font-bold text-gray-700 mb-4 uppercase tracking-wider flex items-center gap-2">
              <Plus className="w-4 h-4"/> Ajouter une question
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {questionTypes.map((item) => (
                  <button 
                      key={item.type}
                      onClick={() => addQuestion(item.type)}
                      className={`flex flex-col items-start p-3 rounded-lg border hover:shadow-md transition-all text-left group ${item.color} bg-white hover:bg-gray-50`}
                  >
                      <div className={`p-2 rounded-md mb-2 group-hover:scale-110 transition-transform ${item.color.replace('bg-white', '')}`}>
                          <item.icon className="w-5 h-5"/>
                      </div>
                      <span className="font-bold text-gray-800 text-sm">{item.label}</span>
                      <span className="text-xs text-gray-500 mt-1">{item.desc}</span>
                  </button>
              ))}
          </div>
      </div>

      <div className="flex justify-end gap-3 pt-6 border-t mt-8">
        <button onClick={onCancel} className="px-6 py-2.5 text-gray-600 hover:bg-gray-100 rounded-lg font-medium transition-colors">
            {t('cancel')}
        </button>
        <button onClick={handleSave} className="px-8 py-2.5 bg-green-600 text-white rounded-lg shadow-lg hover:bg-green-700 hover:shadow-xl transition-all flex items-center gap-2 font-bold transform active:scale-95">
            <Save className="h-5 w-5 rtl:flip" /> {t('save')}
        </button>
      </div>
    </div>
  );
};

export default QuizBuilder;

import React, { useState, useEffect, useRef } from 'react';
import { Quiz, Question, QuestionType, QuizResult } from '../../types';
import { GeminiService } from '../../services/geminiService';
import { StorageService } from '../../services/storageService';
import { CheckCircle, Clock, Timer, ArrowRight, ArrowLeft, Mic, MicOff } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';

interface QuizTakerProps {
  quiz: Quiz;
  studentId: string;
  studentName: string;
  onComplete: () => void;
}

const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, studentId, studentName, onComplete }) => {
  const { t, dir } = useLanguage();
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [timeLeft, setTimeLeft] = useState<number | null>(quiz.timeLimit ? quiz.timeLimit * 60 : null);

  // Voice Input State
  const [isListening, setIsListening] = useState(false);

  const startTimeRef = useRef<number>(Date.now());

  useEffect(() => {
    if (timeLeft === null) return;
    if (timeLeft <= 0) {
        handleSubmit(); 
        return;
    }

    const intervalId = setInterval(() => {
        setTimeLeft((prev) => (prev !== null ? prev - 1 : null));
    }, 1000);

    return () => clearInterval(intervalId);
  }, [timeLeft]);

  const handleAnswer = (qId: string, val: any) => {
    setAnswers(prev => ({ ...prev, [qId]: val }));
  };

  // Voice Recognition Logic
  const toggleVoiceInput = (qId: string) => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
        alert("Votre navigateur ne supporte pas la reconnaissance vocale.");
        return;
    }

    if (isListening) {
        setIsListening(false);
        // Stop is handled by the object itself if we kept a ref, but here we rely on simple toggle for UI
        // In a real implementation we would need a ref to the recognition instance to call .stop()
        return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = dir === 'rtl' ? 'ar-SA' : 'fr-FR';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        const currentText = answers[qId] || '';
        handleAnswer(qId, currentText + (currentText ? ' ' : '') + transcript);
    };

    recognition.start();
  };

  const handleSubmit = async () => {
    if (isSubmitting) return; 
    setIsSubmitting(true);
    let calculatedScore = 0;
    let maxScore = 0;

    for (const q of quiz.questions) {
      maxScore += q.points;
      const userAns = answers[q.id];

      if (q.type === QuestionType.MCQ || q.type === QuestionType.IMAGE_MCQ || q.type === QuestionType.BOOLEAN) {
        if (userAns === q.correctAnswer) {
          calculatedScore += q.points;
        }
      } else if (q.type === QuestionType.SHORT_ANSWER) {
         if (typeof userAns === 'string' && typeof q.correctAnswer === 'string' && userAns.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) {
             calculatedScore += q.points;
         }
      } else if (q.type === QuestionType.MATCHING) {
         if (Array.isArray(userAns)) {
            let allCorrect = true;
            const correctPairs = q.matchingPairs || [];
            if (userAns.length !== correctPairs.length) allCorrect = false;
            else {
                userAns.forEach((ua: any) => {
                    const match = correctPairs.find(cp => cp.left === ua.left);
                    if (!match || match.right !== ua.right) allCorrect = false;
                });
            }
            if (allCorrect) calculatedScore += q.points;
         }
      } else if (q.type === QuestionType.FILL_IN_THE_BLANK) {
          const matches = q.text.match(/\[(.*?)\]/g) || [];
          const correctValues = matches.map(m => m.replace(/[\[\]]/g, '').trim().toLowerCase());
          const userValues = (Array.isArray(userAns) ? userAns : []).map((v: string) => v.trim().toLowerCase());

          let correctCount = 0;
          correctValues.forEach((val, idx) => {
              if (userValues[idx] === val) correctCount++;
          });

          if (correctValues.length > 0) {
              calculatedScore += (correctCount / correctValues.length) * q.points;
          }
      } else if (q.type === QuestionType.ESSAY) {
          try {
              const grading = await GeminiService.gradeEssay(q.text, userAns || '');
              const normalizedScore = (grading.score / 10) * q.points;
              calculatedScore += normalizedScore;
          } catch (e) {
              console.warn("AI grading failed, score 0 for this question");
          }
      }
    }

    const endTime = Date.now();
    const timeSpentSeconds = Math.floor((endTime - startTimeRef.current) / 1000);

    const result: QuizResult = {
        id: `res-${Date.now()}`,
        quizId: quiz.id,
        studentId,
        studentName,
        answers,
        score: Math.round(calculatedScore * 10) / 10,
        maxScore,
        submittedAt: new Date().toISOString(),
        startedAt: new Date(startTimeRef.current).toISOString(),
        timeSpent: timeSpentSeconds
    };

    StorageService.saveResult(result);
    setIsSubmitting(false);
    onComplete();
  };

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const q = quiz.questions[currentStep];
  const isLast = currentStep === quiz.questions.length - 1;

  // RTL aware icons
  const NextIcon = dir === 'rtl' ? ArrowLeft : ArrowRight;
  const PrevIcon = dir === 'rtl' ? ArrowRight : ArrowLeft;

  return (
    <div className="max-w-3xl mx-auto bg-white p-8 rounded-lg shadow-lg relative" dir={dir}>
      {timeLeft !== null && (
          <div className={`fixed top-4 start-4 z-50 px-4 py-2 rounded-full font-mono font-bold shadow-md flex items-center gap-2 ${timeLeft < 60 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-blue-100 text-blue-800'}`}>
              <Timer className="w-5 h-5"/>
              {formatTime(timeLeft)}
          </div>
      )}

      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <h1 className="text-xl font-bold">{quiz.title}</h1>
        <div className="flex items-center gap-2 text-gray-500">
            <Clock className="w-4 h-4"/>
            <span>{t('questionsCount')} {currentStep + 1} / {quiz.questions.length}</span>
        </div>
      </div>

      <div className="mb-8">
        {q.type !== QuestionType.FILL_IN_THE_BLANK && <h3 className="text-lg font-medium mb-4">{q.text}</h3>}

        {q.type === QuestionType.IMAGE_MCQ && q.imageUrl && (
            <div className="mb-6">
                <img src={q.imageUrl} alt="Question Reference" className="max-h-64 rounded shadow-md object-contain border" />
            </div>
        )}

        {(q.type === QuestionType.MCQ || q.type === QuestionType.IMAGE_MCQ) && (
            <div className="space-y-3">
                {q.options?.map(opt => (
                    <label key={opt} className="flex items-center p-3 border rounded hover:bg-gray-50 cursor-pointer">
                        <input 
                            type="radio" 
                            name={q.id} 
                            className="me-3 h-4 w-4 text-blue-600"
                            checked={answers[q.id] === opt}
                            onChange={() => handleAnswer(q.id, opt)}
                        />
                        {opt}
                    </label>
                ))}
            </div>
        )}

        {q.type === QuestionType.BOOLEAN && (
            <div className="flex gap-4">
                 <button 
                    onClick={() => handleAnswer(q.id, true)}
                    className={`px-6 py-3 rounded border ${answers[q.id] === true ? 'bg-blue-100 border-blue-500' : 'hover:bg-gray-50'}`}
                 > {t('true')} </button>
                 <button 
                    onClick={() => handleAnswer(q.id, false)}
                    className={`px-6 py-3 rounded border ${answers[q.id] === false ? 'bg-blue-100 border-blue-500' : 'hover:bg-gray-50'}`}
                 > {t('false')} </button>
            </div>
        )}

        {q.type === QuestionType.SHORT_ANSWER && (
            <input 
                className="w-full border rounded p-3"
                placeholder={t('questionLabel')}
                value={answers[q.id] || ''}
                onChange={(e) => handleAnswer(q.id, e.target.value)}
            />
        )}

        {q.type === QuestionType.FILL_IN_THE_BLANK && (
            <div className="leading-loose text-lg font-medium">
                {(() => {
                    let blankIndex = 0;
                    return q.text.split(/(\[.*?\])/).map((part, idx) => {
                        if (part.startsWith('[') && part.endsWith(']')) {
                            const currentBlankIndex = blankIndex++;
                            const val = (answers[q.id] as string[])?.[currentBlankIndex] || '';
                            return (
                                <input
                                    key={idx}
                                    className="border-b-2 border-blue-500 mx-1 px-1 text-center w-32 focus:outline-none bg-blue-50 text-blue-800"
                                    value={val}
                                    onChange={(e) => {
                                        const newAns = [...(answers[q.id] || [])];
                                        newAns[currentBlankIndex] = e.target.value;
                                        handleAnswer(q.id, newAns);
                                    }}
                                    placeholder="..."
                                    autoComplete="off"
                                />
                            );
                        }
                        return <span key={idx}>{part}</span>;
                    });
                })()}
            </div>
        )}

        {q.type === QuestionType.ESSAY && (
             <div className="relative">
                 <textarea 
                    className="w-full border rounded p-3 h-32"
                    placeholder={t('questionLabel')}
                    value={answers[q.id] || ''}
                    onChange={(e) => handleAnswer(q.id, e.target.value)}
                />
                <button 
                    onClick={() => toggleVoiceInput(q.id)}
                    className={`absolute bottom-3 right-3 p-2 rounded-full transition-colors ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                    title={isListening ? t('stopRecording') : t('startRecording')}
                >
                    {isListening ? <MicOff className="w-5 h-5"/> : <Mic className="w-5 h-5"/>}
                </button>
            </div>
        )}

        {q.type === QuestionType.MATCHING && (
            <div className="space-y-4">
                {q.matchingPairs?.map(pair => (
                    <div key={pair.left} className="flex items-center gap-4">
                        <div className="w-1/2 p-2 bg-gray-100 rounded">{pair.left}</div>
                        <select 
                            className="w-1/2 p-2 border rounded"
                            onChange={(e) => {
                                const currentPairs = answers[q.id] || [];
                                const filtered = currentPairs.filter((p: any) => p.left !== pair.left);
                                handleAnswer(q.id, [...filtered, { left: pair.left, right: e.target.value }]);
                            }}
                        >
                            <option value="">...</option>
                            {q.matchingPairs?.map(p => (
                                <option key={p.right} value={p.right}>{p.right}</option>
                            ))}
                        </select>
                    </div>
                ))}
            </div>
        )}
      </div>

      <div className="flex justify-between">
          <button 
            disabled={currentStep === 0}
            onClick={() => setCurrentStep(curr => curr - 1)}
            className="px-4 py-2 text-gray-600 disabled:opacity-50 flex items-center gap-2"
          >
              <PrevIcon className="w-4 h-4" /> {t('previous')}
          </button>

          {!isLast ? (
              <button 
                onClick={() => setCurrentStep(curr => curr + 1)}
                className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 flex items-center gap-2"
              >
                  {t('next')} <NextIcon className="w-4 h-4" />
              </button>
          ) : (
              <button 
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="px-6 py-2 bg-green-600 text-white rounded hover:bg-green-700 flex items-center gap-2"
              >
                  {isSubmitting ? t('submitting') : <>{t('finish')} <CheckCircle className="w-4 h-4"/></>}
              </button>
          )}
      </div>
    </div>
  );
};

export default QuizTaker;

export enum UserRole {
  ADMIN = 'ADMIN',
  PROFESSOR = 'PROFESSOR',
  STUDENT = 'STUDENT',
  MODERATOR = 'MODERATOR',
  COORDINATOR = 'COORDINATOR', // New Role
}

