          if (d.type === 'GPS_TRACKER') {
              d.data.lat = d.data.lat! + (Math.random() * 0.001 - 0.0005);
              d.data.lng = d.data.lng! + (Math.random() * 0.001 - 0.0005);
          }
          d.lastUpdate = new Date().toISOString();
          return d;
      });
  }
