const AdminPortal: React.FC<{ onLoginSuccess: (user: User) => void }> = ({ onLoginSuccess }) => {
    const [isInstalled, setIsInstalled] = useState<boolean | null>(null);
    const [loading, setLoading] = useState(true);
    const { dir } = useLanguage();
    const navigate = useNavigate();
    const location = useLocation();
    const user = StorageService.getSession();

    useEffect(() => {
        const check = async () => {
            const installed = await ApiService.checkInstallStatus();
            setIsInstalled(installed);
            setLoading(false);
        };
        check();
    }, []);

    const handleHardReset = () => {
        if (!confirm("⚠️ ZONE DE DANGER ⚠️\n\nVous êtes sur le point d'effacer TOUTES les données.\n\nContinuer ?")) return;
        const inputKey = prompt("🔒 CONFIRMATION REQUISE\n\nEntrez 'RESET' pour confirmer l'effacement total.");

        if (inputKey === 'RESET') {
            localStorage.clear();
            sessionStorage.clear();
            window.location.href = '/tinmelad?setup=true';
        } else {
            alert("Annulé.");
        }
    };

    if (loading) return <div className="min-h-screen bg-slate-900 flex items-center justify-center text-white"><Loader2 className="animate-spin w-8 h-8"/></div>;

    const showSetup = !isInstalled || location.search.includes('setup=true');

    return (
        <div className="min-h-screen bg-slate-900 flex items-center justify-center relative overflow-hidden font-sans" dir={dir}>
             <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>

             {showSetup ? (
                 <InstallationWizard onInstalled={() => { setIsInstalled(true); navigate('/tinmelad/login'); }} />
             ) : (
                <Routes>
                    <Route path="login" element={
                        user && user.role === UserRole.ADMIN ? (
                             <Navigate to="/admin" replace />
                        ) : (
                            <>
                                <LoginPage role="ADMIN" onLoginSuccess={onLoginSuccess} />
                                {/* Factory Reset button hidden on login page for emergencies */}
                                <div className="absolute bottom-4 left-4 z-20">
                                    <button onClick={handleHardReset} className="text-xs text-red-500/50 hover:text-red-500 flex items-center gap-1 transition">
                                        <Trash2 className="w-3 h-3"/> Reset
                                    </button>
                                </div>
                            </>
                        )
                    } />
                    <Route path="*" element={<Navigate to="login" replace />} />
                </Routes>
             )}
        </div>
    );
};

// --- MAIN APP COMPONENT ---

const AppContent: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [autoLaunchQuizId, setAutoLaunchQuizId] = useState<string | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
      // Init logic
      const init = async () => {
          setLoading(true);
          const session = StorageService.getSession();
          if (session) {
              setUser(session);
          }

          const params = new URLSearchParams(window.location.search);
          const qId = params.get('quizId');
          if (qId) setAutoLaunchQuizId(qId);

          setLoading(false);
      };
      init();
  }, []);

  const getDashboardPath = (role: UserRole) => {
      switch(role) {
          case UserRole.ADMIN: return '/admin';
          case UserRole.PROFESSOR: return '/professor';
          case UserRole.STUDENT: return '/student';
          case UserRole.COORDINATOR: return '/coordinator';
          case UserRole.MODERATOR: return '/moderator';
          default: return '/';
      }
  };

  const handleLoginSuccess = (loggedInUser: User) => {
      StorageService.saveSession(loggedInUser);
      setUser(loggedInUser);
      navigate(getDashboardPath(loggedInUser.role));
  };

  const handleLogout = () => {
      StorageService.clearSession();
      setUser(null);
      navigate('/');
  };

  if (loading) {
      return (
          <div className="min-h-screen bg-blue-900 flex items-center justify-center">
              <div className="flex flex-col items-center gap-4">
                  <Loader2 className="w-12 h-12 text-white animate-spin" />
                  <p className="text-blue-200 text-sm font-medium">Initialisation du système...</p>
              </div>
          </div>
      );
  }

  return (
    <Routes>
        {/* Public Routes */}
        <Route path="/" element={!user ? <LandingPage /> : <Navigate to={getDashboardPath(user.role)} replace />} />

        <Route path="/login/student" element={
            !user ? <LoginPage role="STUDENT" onLoginSuccess={handleLoginSuccess} /> : <Navigate to={getDashboardPath(user.role)} replace />
        } />

        <Route path="/login/staff" element={
            !user ? <LoginPage role="STAFF" onLoginSuccess={handleLoginSuccess} /> : <Navigate to={getDashboardPath(user.role)} replace />
        } />

        {/* Admin Portal Routes */}
        <Route path="/tinmelad/*" element={
            <AdminPortal onLoginSuccess={handleLoginSuccess} />
        } />

        {/* Protected Routes - Role Based Separation via AuthGuard */}

        <Route path="/admin/*" element={
            <AuthGuard user={user} requiredRole={UserRole.ADMIN}>
                <AdminDashboard onLogout={handleLogout} />
            </AuthGuard>
        } />

        <Route path="/professor/*" element={
            <AuthGuard user={user} requiredRole={UserRole.PROFESSOR}>
                <ProfessorDashboard user={user!} onLogout={handleLogout} />
            </AuthGuard>
        } />

        <Route path="/student/*" element={
            <AuthGuard user={user} requiredRole={UserRole.STUDENT}>
                <StudentDashboard user={user!} onLogout={handleLogout} autoLaunchQuizId={autoLaunchQuizId} />
            </AuthGuard>
        } />

        <Route path="/coordinator/*" element={
            <AuthGuard user={user} requiredRole={UserRole.COORDINATOR}>
                <CoordinatorDashboard user={user!} onLogout={handleLogout} />
            </AuthGuard>
        } />

        <Route path="/moderator/*" element={
            <AuthGuard user={user} requiredRole={UserRole.MODERATOR}>
                <ModeratorDashboard user={user!} onLogout={handleLogout} />
            </AuthGuard>
        } />

        {/* Catch all */}
        <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

const App: React.FC = () => {
  return (
    <LanguageProvider>
        <BrowserRouter>
            <AppContent />
        </BrowserRouter>
    </LanguageProvider>
  );
};

export default App;

payload.text:
`AuthGuard` is a pattern used in web applications to **protect specific routes (pages)** from unauthorized access.

Think of it as a **Security Checkpoint** or a **Bouncer** at a club. Before a user is allowed to see a specific page (like the Admin Dashboard), the `AuthGuard` stops them and checks two things:

1.  **Are you logged in?** (Authentication)
2.  **Do you have the right permission?** (Authorization)

If the answer to either is "No", the `AuthGuard` kicks the user out (redirects them) to the login page or the home page.

### How it works in your code

You can find the logic in `components/Auth/AuthGuard.tsx`. Here is the breakdown of exactly what it does:

```tsx
const AuthGuard: React.FC<AuthGuardProps> = ({ user, requiredRole, children }) => {
    // Check 1: Is the user logged in?
    if (!user) {
        // If not, send them to the landing page immediately.
        return <Navigate to="/" replace />;
    }

    // Check 2: Does the user have the specific role required for this page?
    if (user.role !== requiredRole) {
        // If a Student tries to access an Admin page, send them back to home.
        return <Navigate to="/" replace />;
    }

    // Success: The user is logged in AND has the right role.
    // Render the "children" (the actual page they wanted to see).
    return <>{children}</>;
};
```

### How it is used in `App.tsx`

In your `App.tsx`, you wrap your dashboards inside this `AuthGuard`.

**Example:**

```tsx
<Route path="/admin/*" element={
    // The Bouncer (AuthGuard) stands here
    <AuthGuard user={user} requiredRole={UserRole.ADMIN}>
        {/* This component (Child) is only rendered if the Bouncer says yes */}
        <AdminDashboard onLogout={handleLogout} />
    </AuthGuard>
} />
```

### The "Club Analogy"

1.  **The App:** The Club.
2.  **The Route (`/admin`)**: The VIP Area.
3.  **The `AuthGuard`**: The Bouncer standing at the velvet rope.
4.  **`user` prop**: Your ID Card.
5.  **`requiredRole`**: The requirement (e.g., "Must be a VIP member").
6.  **`children`**: The party inside the VIP area.

If you walk up to the Bouncer:
*   **Scenario A:** You have no ID (Not logged in). -> Bouncer sends you to the exit.
*   **Scenario B:** You have an ID, but it says "Regular Guest" (Student), and you are trying to enter the VIP (Admin) area. -> Bouncer sends you to the main floor.
*   **Scenario C:** You have an ID that says "VIP" (Admin). -> Bouncer opens the rope and lets you in (`return <>{children}</>`).

### Why use it?

1.  **Security (UX):** It prevents users from manually typing `http://localhost:3000/admin` and seeing sensitive interfaces if they aren't admins.
2.  **Clean Code:** Instead of writing `if (!user) return redirect...` inside *every single dashboard*, you write it once in `AuthGuard` and reuse it everywhere.
3.  **User Experience:** It automatically handles redirects so users don't see a broken page or unauthorized data.

### Important Note on Real Security

`AuthGuard` provides **Client-Side Security**. It hides the *interface* (UI).

However, a hacker can technically modify the JavaScript in their browser to bypass this. That is why, in a real production app, your **Backend (API)** must also check the token/role for every request.

*   **AuthGuard:** Hides the door so honest users don't walk into the wrong room.
*   **Backend Validation:** Locks the safe inside the room so even if someone breaks down the door, they can't steal the data.

