const PORT = 3001;
// Utilise une variable d'environnement ou une clé par défaut (pour le dev uniquement)
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_opensource_secret_key_change_me_in_prod';

// Middleware
app.use(cors());
app.use(express.json({ limit: '50mb' }));

// Base de données SQLite
// Le fichier database.sqlite sera créé automatiquement à la racine
const db = new sqlite3.Database('./database.sqlite', (err) => {
    if (err) console.error('Erreur ouverture base de données', err);
    else console.log('Connecté à la base de données SQLite');
});

// Initialisation des Tables
db.serialize(() => {
    // Table Utilisateurs
    db.run(`CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        username TEXT UNIQUE,
        password TEXT,
        name TEXT,
        role TEXT,
        school TEXT,
        city TEXT,
        data TEXT -- Stockage JSON pour les champs flexibles (XP, Classes, etc.)
    )`);

    // Table Quiz
    db.run(`CREATE TABLE IF NOT EXISTS quizzes (
        id TEXT PRIMARY KEY,
        professorId TEXT,
        title TEXT,
        status TEXT,
        data TEXT -- Contenu complet du quiz en JSON
    )`);

    // Table Résultats
    db.run(`CREATE TABLE IF NOT EXISTS results (
        id TEXT PRIMARY KEY,
        quizId TEXT,
        studentId TEXT,
        score REAL,
        data TEXT
    )`);
});

// --- API ROUTES ---

// INSTALLATION WIZARD CHECK
app.get('/api/setup/status', (req, res) => {
    db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'", [], (err, row) => {
        if (err) return res.status(500).json({ error: err.message });
        // @ts-ignore
        res.json({ installed: row.count > 0 });
    });
});

// INSTALLATION (CREATE FIRST ADMIN)
app.post('/api/setup/install', (req, res) => {
    const { username, password, name, schoolName } = req.body;

    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    // Check if already installed
    db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'", [], (err, row) => {
        // @ts-ignore
        if (row && row.count > 0) {
            return res.status(403).json({ error: "L'application est déjà installée." });
        }

        const id = `admin-${Date.now()}`;
        const hash = bcrypt.hashSync(password, 10);
        const data = JSON.stringify({ schoolName }); // Store school name in meta data

        db.run(`INSERT INTO users (id, username, password, name, role, data) VALUES (?, ?, ?, ?, ?, ?)`, 
            [id, username.trim().toLowerCase(), hash, name || 'Administrateur', 'ADMIN', data],
            (err) => {
                if (err) return res.status(500).json({ error: err.message });
                res.json({ success: true });
            }
        );
    });
});

// Login
app.post('/api/auth/login', (req, res) => {
    const { username, password } = req.body;

    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    db.get("SELECT * FROM users WHERE username = ?", [username.trim().toLowerCase()], (err, user) => {
        if (err) return res.status(500).json({ error: err.message });
        if (!user) return res.status(404).json({ error: "Utilisateur introuvable" });

        // @ts-ignore
        const isValid = bcrypt.compareSync(password, user.password);
        if (!isValid) return res.status(401).json({ error: "Mot de passe incorrect" });

        // @ts-ignore
        const token = jwt.sign({ id: user.id, role: user.role }, JWT_SECRET, { expiresIn: '24h' });

        // Fusionner les données JSON avec les colonnes SQL
        // @ts-ignore
        const extraData = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extraData, token };
        delete userObj.password;
        delete userObj.data;

        res.json(userObj);
    });
});

// Création Utilisateur (Admin/Coordinateur)
app.post('/api/users', (req, res) => {
    const { id, username, password, name, role, school, city, ...extraData } = req.body;

    // Hachage du mot de passe pour la sécurité
    const hash = bcrypt.hashSync(password, 10);
    const jsonData = JSON.stringify(extraData);

    db.run(`INSERT INTO users (id, username, password, name, role, school, city, data) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [id, username.trim().toLowerCase(), hash, name, role, school, city, jsonData],
        function(err) {
            if (err) {
                if (err.message.includes('UNIQUE constraint failed')) {
                    return res.status(400).json({ error: "Cet identifiant existe déjà." });
                }
                return res.status(400).json({ error: err.message });
            }
            res.json({ success: true, id });
        }
    );
});

// Récupérer les utilisateurs (avec filtres simples)
app.get('/api/users', (req, res) => {
    const { school, city, role } = req.query;
    let query = "SELECT * FROM users WHERE 1=1";
    let params = [];

    if (school) { query += " AND school = ?"; params.push(school); }
    if (city) { query += " AND city = ?"; params.push(city); }
    if (role) { query += " AND role = ?"; params.push(role); }

    db.all(query, params, (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        const users = rows.map(r => {
            // @ts-ignore
            const extra = JSON.parse(r.data || '{}');
            const u = { ...r, ...extra };
            // @ts-ignore
            delete u.password;
            // @ts-ignore
            delete u.data;
            return u;
        });
        res.json(users);
    });
});

// --- QUIZ SUBMISSION ENDPOINT (Server-Side Validation) ---
app.post('/api/quiz/submit', (req, res) => {
    const { quizId, studentId, studentName, answers, timeSpent, essayScores } = req.body;

    db.get("SELECT data FROM quizzes WHERE id = ?", [quizId], (err, row) => {
        if (err) return res.status(500).json({ error: err.message });
        // @ts-ignore
        if (!row) return res.status(404).json({ error: "Quiz not found" });

        // @ts-ignore
        const quiz = JSON.parse(row.data);
        let score = 0;
        let maxScore = 0;

        quiz.questions.forEach((q) => {
            maxScore += q.points;
            const userAns = answers[q.id];

            // 1. Text & Image MCQ & Boolean
            if (q.type === 'MCQ' || q.type === 'IMAGE_MCQ' || q.type === 'BOOLEAN') {
                if (String(userAns) === String(q.correctAnswer)) score += q.points;
            }
            // 2. Short Answer
            else if (q.type === 'SHORT_ANSWER') {
                if (typeof userAns === 'string' && typeof q.correctAnswer === 'string' && userAns.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) {
                    score += q.points;
                }
            }
            // 3. Matching
            else if (q.type === 'MATCHING') {
                if (Array.isArray(userAns)) {
                    let allCorrect = true;
                    const correctPairs = q.matchingPairs || [];
                    if (userAns.length !== correctPairs.length) allCorrect = false;
                    else {
                        userAns.forEach((ua) => {
                            const match = correctPairs.find(cp => cp.left === ua.left);
                            if (!match || match.right !== ua.right) allCorrect = false;
                        });
                    }
                    if (allCorrect) score += q.points;
                }
            }
            // 4. Fill in the Blank
            else if (q.type === 'FILL_IN_THE_BLANK') {
                const matches = q.text.match(/\[(.*?)\]/g) || [];
                const correctValues = matches.map(m => m.replace(/[\[\]]/g, '').trim().toLowerCase());
                const userValues = (Array.isArray(userAns) ? userAns : []).map(v => v.trim().toLowerCase());

                let correctCount = 0;
                correctValues.forEach((val, idx) => {
                    if (userValues[idx] === val) correctCount++;
                });

                if (correctValues.length > 0) {
                    score += (correctCount / correctValues.length) * q.points;
                }
            }
            // 5. Essay (Accept client-provided AI score for now, pending deeper backend integration)
            else if (q.type === 'ESSAY') {
                if (essayScores && essayScores[q.id]) {
                    score += essayScores[q.id];
                }
            }
        });

        const result = {
            id: `res-${Date.now()}`,
            quizId,
            studentId,
            studentName,
            answers, // We save their answers history
            score: Math.round(score * 10) / 10,
            maxScore,
            submittedAt: new Date().toISOString(),
            timeSpent
        };

        // Save Result
        db.run(`INSERT INTO results (id, quizId, studentId, score, data) VALUES (?, ?, ?, ?, ?)`,
            [result.id, quizId, studentId, result.score, JSON.stringify(result)],
            (err) => {
                if (err) return res.status(500).json({ error: err.message });
                res.json(result);
            }
        );
    });
});

app.listen(PORT, () => {
    console.log(`🚀 Serveur Backend Tinmel démarré sur http://localhost:${PORT}`);
    console.log(`🌐 Frontend accessible sur http://localhost:3000`);
});

import { User, QuizResult } from '../types';
import { StorageService } from './storageService';

// Ce service sert de pont vers le Backend Node.js
// Il est destiné à remplacer progressivement le storageService (localStorage)
export const ApiService = {
    // Vérifier si l'application est installée (Admin existe)
    checkInstallStatus: async (): Promise<boolean> => {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 1000); // 1 seconde max pour éviter l'écran blanc

        try {
            const res = await fetch('/api/setup/status', { signal: controller.signal });
            clearTimeout(timeoutId);

            if (!res.ok) throw new Error("API Unreachable");
            const data = await res.json();
            return data.installed;
        } catch (e) {
            // Si backend non joignable ou timeout, on vérifie si un admin existe localement
            return StorageService.hasAdmin(); 
        }
    },

    // Installer l'application (Créer premier admin)
    installApp: async (adminData: any): Promise<boolean> => {
        try {
            const res = await fetch('/api/setup/install', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(adminData)
            });
            if (!res.ok) throw new Error("API Error");
            return res.ok;
        } catch (e) {
            console.warn("Backend non joignable, installation locale...");
            return StorageService.createAdmin(adminData);
        }
    },

    // Connexion via API
    login: async (username: string, password?: string): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password })
            });

            if (!res.ok) throw new Error('Login failed');

            const user = await res.json();
            // Stocker le token JWT pour les futures requêtes authentifiées
            localStorage.setItem('tinmel_token', user.token);
            return user;
        } catch (e) {
            console.error("Erreur Connexion API", e);
            return null;
        }
    },

    // Récupérer les utilisateurs depuis la BDD SQL
    getUsers: async (school?: string, city?: string): Promise<User[]> => {
        try {
            let url = '/api/users?';
            if (school) url += `school=${encodeURIComponent(school)}&`;
            if (city) url += `city=${encodeURIComponent(city)}`;

            const res = await fetch(url);
            return await res.json();
        } catch (e) {
            console.error("Erreur API Users", e);
            return [];
        }
    },

    // Créer un utilisateur dans la BDD SQL
    createUser: async (user: User): Promise<boolean> => {
        try {
            const res = await fetch('/api/users', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(user)
            });
            return res.ok;
        } catch (e) {
            console.error("Erreur création utilisateur", e);
            return false;
        }
    },

    // Submit Quiz to Backend (Secure Validation)
    submitQuiz: async (payload: { quizId: string, studentId: string, studentName: string, answers: any, timeSpent: number, essayScores: any }): Promise<QuizResult | null> => {
        try {
            const res = await fetch('/api/quiz/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error("Submission Failed");
            return await res.json();
        } catch (e) {
            console.warn("Backend submit failed, using fallback:", e);
            return null;
        }
    }
};

import React, { useState, useEffect, useRef } from 'react';
import { Quiz, Question, QuestionType, QuizResult } from '../../types';
import { GeminiService } from '../../services/geminiService';
import { StorageService } from '../../services/storageService';
import { ApiService } from '../../services/apiService';
import { CheckCircle, Clock, Timer, ArrowRight, ArrowLeft, Mic, MicOff } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';

interface QuizTakerProps {
  quiz: Quiz;
  studentId: string;
  studentName: string;
  onComplete: () => void;
}

const QuizTaker: React.FC<QuizTakerProps> = ({ quiz, studentId, studentName, onComplete }) => {
  const { t, dir } = useLanguage();
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [timeLeft, setTimeLeft] = useState<number | null>(quiz.timeLimit ? quiz.timeLimit * 60 : null);

  // Voice Input State
  const [isListening, setIsListening] = useState(false);

  const startTimeRef = useRef<number>(Date.now());

  useEffect(() => {
    if (timeLeft === null) return;
    if (timeLeft <= 0) {
        handleSubmit(); 
        return;
    }

    const intervalId = setInterval(() => {
        setTimeLeft((prev) => (prev !== null ? prev - 1 : null));
    }, 1000);

    return () => clearInterval(intervalId);
  }, [timeLeft]);

  const handleAnswer = (qId: string, val: any) => {
    setAnswers(prev => ({ ...prev, [qId]: val }));
  };

  // Voice Recognition Logic
  const toggleVoiceInput = (qId: string) => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
        alert("Votre navigateur ne supporte pas la reconnaissance vocale.");
        return;
    }

    if (isListening) {
        setIsListening(false);
        return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = dir === 'rtl' ? 'ar-SA' : 'fr-FR';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);

    recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        const currentText = answers[qId] || '';
        handleAnswer(qId, currentText + (currentText ? ' ' : '') + transcript);
    };

    recognition.start();
  };

  const handleSubmit = async () => {
    if (isSubmitting) return; 
    setIsSubmitting(true);

    let calculatedScore = 0;
    let maxScore = 0;
    const essayScores: Record<string, number> = {};

    // First Pass: Calculate Essay Scores locally using Gemini AI (since backend integration for AI is future work)
    // and also calculate fallback scores for Offline mode
    for (const q of quiz.questions) {
      maxScore += q.points;
      const userAns = answers[q.id];

      // --- Local Calculation (Fallback) ---
      if (q.type === QuestionType.MCQ || q.type === QuestionType.IMAGE_MCQ || q.type === QuestionType.BOOLEAN) {
        if (userAns === q.correctAnswer) calculatedScore += q.points;
      } else if (q.type === QuestionType.SHORT_ANSWER) {
         if (typeof userAns === 'string' && typeof q.correctAnswer === 'string' && userAns.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase()) {
             calculatedScore += q.points;
         }
      } else if (q.type === QuestionType.MATCHING) {
         if (Array.isArray(userAns)) {
            let allCorrect = true;
            const correctPairs = q.matchingPairs || [];
            if (userAns.length !== correctPairs.length) allCorrect = false;
            else {
                userAns.forEach((ua: any) => {
                    const match = correctPairs.find(cp => cp.left === ua.left);
                    if (!match || match.right !== ua.right) allCorrect = false;
                });
            }
            if (allCorrect) calculatedScore += q.points;
         }
      } else if (q.type === QuestionType.FILL_IN_THE_BLANK) {
          const matches = q.text.match(/\[(.*?)\]/g) || [];
          const correctValues = matches.map(m => m.replace(/[\[\]]/g, '').trim().toLowerCase());
          const userValues = (Array.isArray(userAns) ? userAns : []).map((v: string) => v.trim().toLowerCase());

          let correctCount = 0;
          correctValues.forEach((val, idx) => {
              if (userValues[idx] === val) correctCount++;
          });

          if (correctValues.length > 0) {
              calculatedScore += (correctCount / correctValues.length) * q.points;
          }
      } else if (q.type === QuestionType.ESSAY) {
          try {
              const grading = await GeminiService.gradeEssay(q.text, userAns || '');
              const normalizedScore = (grading.score / 10) * q.points;
              calculatedScore += normalizedScore;
              essayScores[q.id] = normalizedScore; // Store for backend
          } catch (e) {
              console.warn("AI grading failed, score 0 for this question");
          }
      }
    }

    const endTime = Date.now();
    const timeSpentSeconds = Math.floor((endTime - startTimeRef.current) / 1000);

    // Try Backend Submission First
    const backendResult = await ApiService.submitQuiz({
        quizId: quiz.id,
        studentId,
        studentName,
        answers,
        timeSpent: timeSpentSeconds,
        essayScores
    });

    if (backendResult) {
        // Use Backend Result if available
        StorageService.saveResult(backendResult); // Cache local copy for UI
    } else {
        // Fallback to Local Calculation
        const result: QuizResult = {
            id: `res-${Date.now()}`,
            quizId: quiz.id,
            studentId,
            studentName,
            answers,
            score: Math.round(calculatedScore * 10) / 10,
            maxScore,
            submittedAt: new Date().toISOString(),
            startedAt: new Date(startTimeRef.current).toISOString(),
            timeSpent: timeSpentSeconds
        };
        StorageService.saveResult(result);
    }

    setIsSubmitting(false);
    onComplete();
  };

  const formatTime = (seconds: number) => {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const q = quiz.questions[currentStep];
  const isLast = currentStep === quiz.questions.length - 1;

  // RTL aware icons
  const NextIcon = dir === 'rtl' ? ArrowLeft : ArrowRight;
  const PrevIcon = dir === 'rtl' ? ArrowRight : ArrowLeft;

  return (
    <div className="max-w-3xl mx-auto bg-white p-8 rounded-lg shadow-lg relative" dir={dir}>
      {timeLeft !== null && (
          <div className={`fixed top-4 start-4 z-50 px-4 py-2 rounded-full font-mono font-bold shadow-md flex items-center gap-2 ${timeLeft < 60 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-blue-100 text-blue-800'}`}>
              <Timer className="w-5 h-5"/>
              {formatTime(timeLeft)}
          </div>
      )}

      <div className="flex justify-between items-center mb-6 border-b pb-4">
        <h1 className="text-xl font-bold">{quiz.title}</h1>
        <div className="flex items-center gap-2 text-gray-500">
            <Clock className="w-4 h-4"/>
            <span>{t('questionsCount')} {currentStep + 1} / {quiz.questions.length}</span>
        </div>
      </div>

      <div className="mb-8">
        {q.type !== QuestionType.FILL_IN_THE_BLANK && <h3 className="text-lg font-medium mb-4">{q.text}</h3>}

        {q.type === QuestionType.IMAGE_MCQ && q.imageUrl && (
            <div className="mb-6">
                <img src={q.imageUrl} alt="Question Reference" className="max-h-64 rounded shadow-md object-contain border" />
            </div>
        )}

        {(q.type === QuestionType.MCQ || q.type === QuestionType.IMAGE_MCQ) && (
            <div className="space-y-3">
                {q.options?.map(opt => (
                    <label key={opt} className="flex items-center p-3 border rounded hover:bg-gray-50 cursor-pointer">
                        <input 
                            type="radio" 
                            name={q.id} 
                            className="me-3 h-4 w-4 text-blue-600"
                            checked={answers[q.id] === opt}
                            onChange={() => handleAnswer(q.id, opt)}
                        />
                        {opt}
                    </label>
                ))}
            </div>
        )}

        {q.type === QuestionType.BOOLEAN && (
            <div className="flex gap-4">
                 <button 
                    onClick={() => handleAnswer(q.id, true)}
                    className={`px-6 py-3 rounded border ${answers[q.id] === true ? 'bg-blue-100 border-blue-500' : 'hover:bg-gray-50'}`}
                 > {t('true')} </button>
                 <button 
                    onClick={() => handleAnswer(q.id, false)}
                    className={`px-6 py-3 rounded border ${answers[q.id] === false ? 'bg-blue-100 border-blue-500' : 'hover:bg-gray-50'}`}
                 > {t('false')} </button>
            </div>
        )}

        {q.type === QuestionType.SHORT_ANSWER && (
            <input 
                className="w-full border rounded p-3"
                placeholder={t('questionLabel')}
                value={answers[q.id] || ''}
                onChange={(e) => handleAnswer(q.id, e.target.value)}
            />
        )}

        {q.type === QuestionType.FILL_IN_THE_BLANK && (
            <div className="leading-loose text-lg font-medium">
                {(() => {
                    let blankIndex = 0;
                    return q.text.split(/(\[.*?\])/).map((part, idx) => {
                        if (part.startsWith('[') && part.endsWith(']')) {
                            const currentBlankIndex = blankIndex++;
                            const val = (answers[q.id] as string[])?.[currentBlankIndex] || '';
                            return (
                                <input
                                    key={idx}
                                    className="border-b-2 border-blue-500 mx-1 px-1 text-center w-32 focus:outline-none bg-blue-50 text-blue-800"
                                    value={val}
                                    onChange={(e) => {
                                        const newAns = [...(answers[q.id] || [])];
                                        newAns[currentBlankIndex] = e.target.value;
                                        handleAnswer(q.id, newAns);
                                    }}
                                    placeholder="..."
                                    autoComplete="off"
                                />
                            );
                        }
                        return <span key={idx}>{part}</span>;
                    });
                })()}
            </div>
        )}

        {q.type === QuestionType.ESSAY && (
             <div className="relative">
                 <textarea 
                    className="w-full border rounded p-3 h-32"
                    placeholder={t('questionLabel')}
                    value={answers[q.id] || ''}
                    onChange={(e) => handleAnswer(q.id, e.target.value)}
                />
                <button 
                    onClick={() => toggleVoiceInput(q.id)}
                    className={`absolute bottom-3 right-3 p-2 rounded-full transition-colors ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                    title={isListening ? t('stopRecording') : t('startRecording')}
                >
                    {isListening ? <MicOff className="w-5 h-5"/> : <Mic className="w-5 h-5"/>}
                </button>
            </div>
        )}

        {q.type === QuestionType.MATCHING && (
            <div className="space-y-4">
                {q.matchingPairs?.map(pair => (
                    <div key={pair.left} className="flex items-center gap-4">
                        <div className="w-1/2 p-2 bg-gray-100 rounded">{pair.left}</div>
                        <select 
                            className="w-1/2 p-2 border rounded"
                            onChange={(e) => {
                                const currentPairs = answers[q.id] || [];
                                const filtered = currentPairs.filter((p: any) => p.left !== pair.left);
                                handleAnswer(q.id, [...filtered, { left: pair.left, right: e.target.value }]);
                            }}
                        >
                            <option value="">...</option>
                            {q.matchingPairs?.map(p => (
                                <option key={p.right} value={p.right}>{p.right}</option>
                            ))}
                        </select>
                    </div>
                ))}
            </div>
        )}
      </div>

      <div className="flex justify-between">
          <button 
            disabled={currentStep === 0}
            onClick={() => setCurrentStep(curr => curr - 1)}
            className="px-4 py-2 text-gray-600 disabled:opacity-50 flex items-center gap-2"
          >
