// App.tsx
import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, useNavigate } from "react-router-dom";
import apiService from "./apiService";
import StorageService from "./storageService";
import { User, Login } from "./types";
import QuizTaker from "./quizTaker";
import LoginView from "./loginView";

function App() {
  const [user, setUser] = useState<User | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
    const initializeSession = async () => {
      try {
        const apiUser = await apiService.checkSession();
        if (apiUser) {
          setUser(apiUser);
        } else {
          // fallback
          const session = StorageService.getSession();
          if (session) setUser(session);
        }
      } catch (error) {
        console.error("Session initialization failed:", error);
      }
    };

    initializeSession();
  }, [navigate]);

  const handleLogin = async (loginData: Login) => {
    try {
      const user = await apiService.login(loginData.username, loginData.password);
      setUser(user);
      navigate("/quiz");
    } catch (error) {
      console.error("Login failed:", error);
    }
  };

  const handleLogout = async () => {
    try {
      await apiService.logout();
      StorageService.clearSession();
      setUser(null);
      navigate("/");
    } catch (error) {
      console.error("Logout failed:", error);
    }
  };

  return (
    <Router>
      <div>
        {user && <div>Hello, {user.username}!</div>}
        {user && <button onClick={handleLogout}>Logout</button>}
        <Routes>
          <Route path="/" element={<LoginView onLogin={handleLogin} />} />

