            const res = await fetch('/api/auth/me', {
                method: 'GET',
                credentials: 'include'
            });
            if (res.ok) {
                return await res.json();
            }
            return null;
        } catch (e) {
            return null;
        }
    },

    // Déconnexion
    logout: async () => {
        try {
            await fetch('/api/auth/logout', { method: 'POST', credentials: 'include' });
        } catch (e) {
            console.error("Erreur Logout API", e);
        }
    },

    // Récupérer les utilisateurs depuis la BDD SQL
    getUsers: async (school?: string, city?: string): Promise<User[]> => {
        try {
            let url = '/api/users?';
            if (school) url += `school=${encodeURIComponent(school)}&`;
            if (city) url += `city=${encodeURIComponent(city)}`;

            const res = await fetch(url);
            return await res.json();
        } catch (e) {
            console.error("Erreur API Users", e);
            return [];
        }
    },

    // Créer un utilisateur dans la BDD SQL
    createUser: async (user: User): Promise<boolean> => {
        try {
            const res = await fetch('/api/users', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(user)
            });
            return res.ok;
        } catch (e) {
            console.error("Erreur création utilisateur", e);
            return false;
        }
    },

    // Submit Quiz to Backend (Secure Validation)
    submitQuiz: async (payload: { quizId: string, studentId: string, studentName: string, answers: any, timeSpent: number, essayScores: any }): Promise<QuizResult | null> => {
        try {
            const res = await fetch('/api/quiz/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error("Submission Failed");
            return await res.json();
        } catch (e) {
            console.warn("Backend submit failed, using fallback:", e);
            return null;
        }
    }
};

