import express from 'express';
import cors from 'cors';
import sqlite3 from 'sqlite3';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join, extname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = 3001;
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_opensource_secret_key_change_me_in_prod';

// --- CONFIGURATION MULTER (UPLOAD) ---
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, uploadDir)
    },
    filename: function (req, file, cb) {
        // Générer un nom de fichier unique sécurisé
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, file.fieldname + '-' + uniqueSuffix + extname(file.originalname));
    }
});

const upload = multer({ 
    storage: storage,
    limits: { fileSize: 5 * 1024 * 1024 } // Limite 5MB
});

// Middleware
app.use(cors({
    origin: 'http://localhost:3000',
    credentials: true 
}));
app.use(express.json({ limit: '50mb' })); // Keep high limit for large JSON payloads if needed
app.use(cookieParser());

// Servir les fichiers uploadés statiquement
app.use('/uploads', express.static(uploadDir));

// Base de données SQLite
const db = new sqlite3.Database('./database.sqlite', (err) => {
    if (err) console.error('Erreur ouverture base de données', err);
    else console.log('Connecté à la base de données SQLite');
});

// Initialisation des Tables
db.serialize(() => {
    // Table Utilisateurs
    db.run(`CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        username TEXT UNIQUE,
        password TEXT,
        name TEXT,
        role TEXT,
        school TEXT,
        city TEXT,
        data TEXT
    )`);

    // Table Quiz
    db.run(`CREATE TABLE IF NOT EXISTS quizzes (
        id TEXT PRIMARY KEY,
        professorId TEXT,
        title TEXT,
        status TEXT,
        data TEXT
    )`);

    // Table Résultats
    db.run(`CREATE TABLE IF NOT EXISTS results (
        id TEXT PRIMARY KEY,
        quizId TEXT,
        studentId TEXT,
        score REAL,
        data TEXT
    )`);
});

// --- API ROUTES ---

// UPLOAD ENDPOINT
app.post('/api/upload', upload.single('file'), (req, res) => {
    if (!req.file) {
        return res.status(400).json({ error: 'Aucun fichier uploadé.' });
    }
    // Retourner l'URL relative accessible par le frontend
    const fileUrl = `/uploads/${req.file.filename}`;
    res.json({ url: fileUrl, filename: req.file.filename });
});

// INSTALLATION WIZARD CHECK
app.get('/api/setup/status', (req, res) => {
    db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'", [], (err, row) => {
        if (err) return res.status(500).json({ error: err.message });
        // @ts-ignore
        res.json({ installed: row.count > 0 });
    });
});

// INSTALLATION (CREATE FIRST ADMIN)
app.post('/api/setup/install', (req, res) => {
    const { username, password, name, schoolName } = req.body;

    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'", [], (err, row) => {
        // @ts-ignore
        if (row && row.count > 0) {
            return res.status(403).json({ error: "L'application est déjà installée." });
        }

        const id = `admin-${Date.now()}`;
        const hash = bcrypt.hashSync(password, 10);
        const data = JSON.stringify({ schoolName });

        db.run(`INSERT INTO users (id, username, password, name, role, data) VALUES (?, ?, ?, ?, ?, ?)`, 
            [id, username.trim().toLowerCase(), hash, name || 'Administrateur', 'ADMIN', data],
            (err) => {
                if (err) return res.status(500).json({ error: err.message });
                res.json({ success: true });
            }
        );
    });
});

// Login (HttpOnly Cookie)
app.post('/api/auth/login', (req, res) => {
    const { username, password } = req.body;

    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    db.get("SELECT * FROM users WHERE username = ?", [username.trim().toLowerCase()], (err, user) => {
        if (err) return res.status(500).json({ error: err.message });
        if (!user) return res.status(404).json({ error: "Utilisateur introuvable" });

        // @ts-ignore
        const isValid = bcrypt.compareSync(password, user.password);
        if (!isValid) return res.status(401).json({ error: "Mot de passe incorrect" });

        // @ts-ignore
        const token = jwt.sign({ id: user.id, role: user.role }, JWT_SECRET, { expiresIn: '24h' });

        // @ts-ignore
        const extraData = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extraData };
        delete userObj.password;
        delete userObj.data;

        res.cookie('token', token, { 
            httpOnly: true, 
            secure: false, 
            sameSite: 'lax', 
            maxAge: 24 * 60 * 60 * 1000 
        });

        res.json(userObj);
    });
});

// Check Session
app.get('/api/auth/me', (req, res) => {
    const token = req.cookies.token;
    if (!token) return res.status(401).json({ error: "Not authenticated" });

    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(403).json({ error: "Invalid token" });

        // @ts-ignore
        db.get("SELECT * FROM users WHERE id = ?", [decoded.id], (err, user) => {
            if (!user) return res.status(404).json({ error: "User not found" });

            // @ts-ignore
            const extraData = JSON.parse(user.data || '{}');
            const userObj = { ...user, ...extraData };
            // @ts-ignore
            delete userObj.password;
            // @ts-ignore
            delete userObj.data;

            res.json(userObj);
        });
    });
});

// Logout
app.post('/api/auth/logout', (req, res) => {
    res.clearCookie('token');
    res.json({ success: true });
});

// Création Utilisateur
app.post('/api/users', (req, res) => {
    const { id, username, password, name, role, school, city, ...extraData } = req.body;

    const hash = bcrypt.hashSync(password, 10);
    const jsonData = JSON.stringify(extraData);

    db.run(`INSERT INTO users (id, username, password, name, role, school, city, data) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [id, username.trim().toLowerCase(), hash, name, role, school, city, jsonData],
        function(err) {
            if (err) {
                if (err.message.includes('UNIQUE constraint failed')) {
                    return res.status(400).json({ error: "Cet identifiant existe déjà." });
                }
                return res.status(400).json({ error: err.message });
            }
            res.json({ success: true, id });
        }
    );
});

