import { User, QuizResult } from '../types';
import { StorageService } from './storageService';

// Ce service sert de pont vers le Backend Node.js
// Il est destiné à remplacer progressivement le storageService (localStorage)
export const ApiService = {
    // Vérifier si l'application est installée (Admin existe)
    checkInstallStatus: async (): Promise<boolean> => {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 1000); 

        try {
            const res = await fetch('/api/setup/status', { signal: controller.signal });
            clearTimeout(timeoutId);

            if (!res.ok) throw new Error("API Unreachable");
            const data = await res.json();
            return data.installed;
        } catch (e) {
            return StorageService.hasAdmin(); 
        }
    },

    // Installer l'application
    installApp: async (adminData: any): Promise<boolean> => {
        try {
            const res = await fetch('/api/setup/install', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(adminData)
            });
            if (!res.ok) throw new Error("API Error");
            return res.ok;
        } catch (e) {
            console.warn("Backend non joignable, installation locale...");
            return StorageService.createAdmin(adminData);
        }
    },

    // Connexion via API (HttpOnly Cookies)
    login: async (username: string, password?: string): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
                credentials: 'include'
            });

            if (!res.ok) throw new Error('Login failed');

            const user = await res.json();
            return user;
        } catch (e) {
            console.error("Erreur Connexion API", e);
            return null;
        }
    },

    // Vérifier la session active
    checkSession: async (): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/me', {
                method: 'GET',
                credentials: 'include'
            });
            if (res.ok) {
                return await res.json();
            }
            return null;
        } catch (e) {
            return null;
        }
    },

    // Déconnexion
    logout: async () => {
        try {
            await fetch('/api/auth/logout', { method: 'POST', credentials: 'include' });
        } catch (e) {
            console.error("Erreur Logout API", e);
        }
    },

    getUsers: async (school?: string, city?: string): Promise<User[]> => {
        try {
            let url = '/api/users?';
            if (school) url += `school=${encodeURIComponent(school)}&`;
            if (city) url += `city=${encodeURIComponent(city)}`;

            const res = await fetch(url);
            return await res.json();
        } catch (e) {
            return [];
        }
    },

    createUser: async (user: User): Promise<boolean> => {
        try {
            const res = await fetch('/api/users', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(user)
            });
            return res.ok;
        } catch (e) {
            return false;
        }
    },

    submitQuiz: async (payload: { quizId: string, studentId: string, studentName: string, answers: any, timeSpent: number, essayScores: any }): Promise<QuizResult | null> => {
        try {
            const res = await fetch('/api/quiz/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error("Submission Failed");
            return await res.json();
        } catch (e) {
            console.warn("Backend submit failed, using fallback:", e);
            return null;
        }
    },

    // --- FILE UPLOAD ---
    uploadFile: async (file: File): Promise<string> => {
        const formData = new FormData();
        formData.append('file', file);

        try {
            // Try uploading to backend
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData,
            });

            if (res.ok) {
                const data = await res.json();
                // Ensure URL matches the environment (proxy handles /api, but static files might need full path if dev server differs)
                // Here we assume standard relative path behavior
                return data.url;
            }
            throw new Error('Server upload failed');
        } catch (e) {
            console.warn("Upload API failed, falling back to Base64 (Local Mode)", e);

            // Fallback: Convert to Base64 for LocalStorage support
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.readAsDataURL(file);
                reader.onload = () => resolve(reader.result as string);
                reader.onerror = (error) => reject(error);
            });
        }
    }
};

