                             {s.isActive ? <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded animate-pulse">LIVE</span> : <span className="bg-gray-100 text-gray-500 text-xs px-2 py-1 rounded">Closed</span>}
                         </div>
