                  <a href={url} target="_blank" rel="noopener noreferrer" className="mt-2 bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 flex items-center gap-2">
                      <ExternalLink className="w-4 h-4"/> Ouvrir le PDF
                  </a>
              </div>
          );
      }

      // 4. Default Fallback
      return (
          <div className="flex items-center justify-between bg-white p-4 rounded border">
              <div className="flex items-center gap-3 overflow-hidden">
                  <div className="p-2 bg-gray-100 rounded">
                      <File className="w-5 h-5 text-gray-600"/>
                  </div>
                  <span className="text-sm font-medium text-gray-700 truncate">{url.split('/').pop() || 'Lien vers le contenu'}</span>
              </div>
              <a href={url} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline flex items-center gap-1 text-sm shrink-0">
                  {t('viewContent')} <ExternalLink className="w-3 h-3"/>
              </a>
          </div>
      );
  };

  if (activeQuiz) {
      return (
          <div className="min-h-screen bg-gray-100 p-8" dir={dir}>
              <button 
                onClick={() => { setActiveQuiz(null); }} // Refresh happens via useEffect
                className="mb-4 text-blue-600 hover:underline"
              >
                  &larr; {t('toDashboard')}
              </button>
              <QuizTaker 
                quiz={activeQuiz} 
                studentId={user.id} 
                studentName={user.name} 
                onComplete={() => setActiveQuiz(null)} 
              />
          </div>
      )
  }

  if (activeWhiteboard) {
      return <WhiteboardRoom user={user} accessKey={activeWhiteboard} onExit={() => setActiveWhiteboard(null)} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 relative" dir={dir}>
      <header className="bg-white shadow px-6 py-4 flex justify-between items-center sticky top-0 z-20">
        <div className="flex items-center gap-4">
            <span className="text-2xl font-black text-blue-700 font-logo tracking-tight">
                {t('appName')}
            </span>
            <div className="h-6 w-px bg-gray-300"></div>
            <div>
                <h1 className="text-sm font-bold text-gray-700 uppercase tracking-wide">{t('studentSpace')}</h1>
                <p className="text-gray-500 text-xs">{user.name}</p>
