import express from 'express';
import cors from 'cors';
import sqlite3 from 'sqlite3';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join, extname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3001; // Support Cloud Port
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_opensource_secret_key_change_me_in_prod';

// --- CONFIGURATION MULTER (UPLOAD) ---
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
    destination: function (req, file, cb) {
        cb(null, uploadDir)
    },
    filename: function (req, file, cb) {
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, file.fieldname + '-' + uniqueSuffix + extname(file.originalname));
    }
});

const upload = multer({ 
    storage: storage,
    limits: { fileSize: 5 * 1024 * 1024 } // Limite 5MB
});

// Middleware
app.use(cors({
    origin: process.env.NODE_ENV === 'production' ? false : 'http://localhost:3000', // Allow same origin in prod
    credentials: true 
}));
app.use(express.json({ limit: '50mb' }));
app.use(cookieParser());

// Servir les fichiers uploadés statiquement
app.use('/uploads', express.static(uploadDir));

// Base de données SQLite (Utiliser /data/database.sqlite pour la persistance sur certains hébergeurs comme Render avec Disk)
const dbPath = process.env.DB_PATH || './database.sqlite';
const db = new sqlite3.Database(dbPath, (err) => {
    if (err) console.error('Erreur ouverture base de données', err);
    else console.log(`Connecté à la base de données SQLite (${dbPath})`);
});

// Initialisation des Tables
db.serialize(() => {
    db.run(`CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        username TEXT UNIQUE,
        password TEXT,
        name TEXT,
        role TEXT,
        school TEXT,
        city TEXT,
        data TEXT
    )`);

    db.run(`CREATE TABLE IF NOT EXISTS quizzes (
        id TEXT PRIMARY KEY,
        professorId TEXT,
        title TEXT,
        status TEXT,
        data TEXT
    )`);

    db.run(`CREATE TABLE IF NOT EXISTS results (
        id TEXT PRIMARY KEY,
        quizId TEXT,
        studentId TEXT,
        score REAL,
        data TEXT
    )`);
});

// --- API ROUTES ---

app.post('/api/upload', upload.single('file'), (req, res) => {
    if (!req.file) {
        return res.status(400).json({ error: 'Aucun fichier uploadé.' });
    }
    const fileUrl = `/uploads/${req.file.filename}`;
    res.json({ url: fileUrl, filename: req.file.filename });
});

app.get('/api/setup/status', (req, res) => {
    db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'", [], (err, row) => {
        if (err) return res.status(500).json({ error: err.message });
        // @ts-ignore
        res.json({ installed: row.count > 0 });
    });
});

app.post('/api/setup/install', (req, res) => {
    const { username, password, name, schoolName } = req.body;
    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'", [], (err, row) => {
        // @ts-ignore
        if (row && row.count > 0) {
