    const exportSchoolFullData = (schoolName: string, schoolCity: string) => {
        const schoolUsers = users.filter(u => u.school === schoolName && u.city === schoolCity);

        const staff = schoolUsers.filter(u => u.role === UserRole.PROFESSOR || u.role === UserRole.COORDINATOR);
        const staffData = staff.map(u => ({
            Role: u.role === UserRole.COORDINATOR ? 'Coordinator' : 'Professor',
            Name: u.name,
            Subject: u.subject || '-',
            Username: u.username,
            Password: u.password
        }));

        const students = schoolUsers.filter(u => u.role === UserRole.STUDENT);
        const studentData = students.map(u => ({
            Name: u.name,
            Classes: u.enrolledClasses?.join(', ') || '-',
            Username: u.username,
            Password: u.password
        }));

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(staffData), "Personnel");
        XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(studentData), "Etudiants");
        XLSX.writeFile(wb, `${schoolName.replace(/[^a-z0-9]/gi, '_')}_Full_Data.xlsx`);
