                    <Building className="w-4 h-4"/> {t('addCoordinator')}
                </button>
                </div>

                {isCreating && (
                    <div className="bg-indigo-50 p-4 rounded-lg flex flex-col md:flex-row gap-2 border border-indigo-100 animate-fade-in">
