const IndividualsView: React.FC = () => {
    const { t } = useLanguage();
    const [users, setUsers] = useState<User[]>([]);
    const [isCreating, setIsCreating] = useState(false);
    const [newName, setNewName] = useState('');
    const [newCity, setNewCity] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [cityFilter, setCityFilter] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const [selectedUser, setSelectedUser] = useState<User | null>(null);

    useEffect(() => {
        // Fetch all initially for city filter logic (simplified for PoC)
        const load = async () => {
            const all = await ApiService.getUsers();
            setUsers(all);
        };
        load();
    }, []);

    const cleanInput = (str: string) => str.trim().toLowerCase().replace(/[^a-z0-9]/g, '');

    const handleCreateUser = () => {
        if(!newName.trim()) return;
        const cleanName = cleanInput(newName);
        const randomSuffix = Math.floor(Math.random() * 9000) + 1000;
        const username = `prof_${cleanName.substring(0, 10)}_${randomSuffix}`;
        const password = Math.floor(100000 + Math.random() * 900000).toString();

        const newUser: User = {
            id: `usr-${Date.now()}`,
            name: newName.trim(),
            username,
            password,
            readablePassword: password, // Explicitly save readable password
            role: UserRole.PROFESSOR,
            city: newCity.trim() || undefined,
            accountType: 'INDIVIDUAL'
        };

        ApiService.createUser(newUser).then(() => {
            setIsCreating(false);
            setNewName(''); setNewCity('');
            alert(`${t('professor')} ${t('completed')}!\nID: ${username}\nPass: ${password}`);
            // Reload users
            ApiService.getUsers().then(setUsers);
        });
    };

    const handleDeleteUser = (id: string) => {
        if (confirm(t('delete') + '?')) {
            StorageService.deleteUser(id);
            ApiService.getUsers().then(setUsers);
            setSelectedUser(null);
        }
    };

    const exportIndividuals = () => {
        const individuals = users.filter(u => u.role === UserRole.PROFESSOR && u.accountType !== 'ESTABLISHMENT');
        const data = individuals.map(u => ({
            Name: u.name,
            City: u.city || '',
            Username: u.username,
            Password: u.readablePassword || u.password || 'N/A' // Fix: Export readable password
        }));
        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Free_Clients");
        XLSX.writeFile(wb, "Clients_Libres_Identifiants.xlsx");
    };

    const individuals = users.filter(u => u.role === UserRole.PROFESSOR && u.accountType !== 'ESTABLISHMENT');
    const cities = Array.from(new Set(individuals.map(u => u.city).filter(Boolean))) as string[];

    const filtered = individuals.filter(u => {
        const matchSearch = u.name.toLowerCase().includes(searchTerm.toLowerCase()) || u.username.toLowerCase().includes(searchTerm.toLowerCase());
        const matchCity = cityFilter ? u.city === cityFilter : true;
        return matchSearch && matchCity;
    });

    const paginated = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);
    const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);

    return (
