                        placeholder={t('globalSearchPlaceholder')}
                        value={searchTerm}
                        onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }}
                    />
                    {loading && <div className="absolute right-3 top-3"><Loader2 className="w-5 h-5 animate-spin text-indigo-500"/></div>}
