const ModeratorsView: React.FC = () => {
    // Keeping existing moderators view
    const { t } = useLanguage();
    const [users, setUsers] = useState<User[]>([]);
    const [isCreating, setIsCreating] = useState(false);
    const [newName, setNewName] = useState('');

    useEffect(() => {
        ApiService.getUsers().then(setUsers);
    }, []);

    const cleanInput = (str: string) => str.trim().toLowerCase().replace(/[^a-z0-9]/g, '');

    const handleCreateUser = () => {
        if(!newName.trim()) return;
        const cleanName = cleanInput(newName);
        const randomSuffix = Math.floor(Math.random() * 9000) + 1000;
        const username = `mod_${cleanName.substring(0, 10)}_${randomSuffix}`;
        const password = Math.floor(100000 + Math.random() * 900000).toString();

        const newUser: User = {
            id: `usr-${Date.now()}`,
            name: newName.trim(),
            username,
            password,
            readablePassword: password, // Explicitly save readable password
            role: UserRole.MODERATOR,
            accountType: 'INDIVIDUAL'
        };

        ApiService.createUser(newUser).then(() => {
            setIsCreating(false);
            setNewName('');
            alert(`${t('moderator')} ${t('completed')}!\nID: ${username}\nPass: ${password}`);
            ApiService.getUsers().then(setUsers);
        });
    };

    const handleDeleteUser = (id: string) => {
        if (confirm(t('delete') + '?')) {
            StorageService.deleteUser(id);
            ApiService.getUsers().then(setUsers);
        }
    };

    const moderators = users.filter(u => u.role === UserRole.MODERATOR);

    return (
        <div className="space-y-4 animate-fade-in">
                <div className="flex justify-end">
                    <button onClick={() => setIsCreating(true)} className="bg-purple-600 text-white px-4 py-2 rounded text-sm flex items-center gap-2 hover:bg-purple-700">
