                                {q.status === 'PUBLISHED' ? <span className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded-full">{t('published')}</span> : <span className="bg-gray-200 text-gray-600 text-xs px-2 py-1 rounded-full">{t('draft')}</span>}
