        setActiveSession(newSession.id);
        setNewTitle('');
    };

    if (activeSession) {
        return <WhiteboardRoom user={user} sessionId={activeSession} onExit={() => { setActiveSession(null); setSessions(StorageService.getWhiteboards().filter(w => w.hostId === user.id)); }} />;
