            console.error("Search failed", e);
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteUser = async (id: string) => {
        if (confirm(t('delete') + '?')) {
            await ApiService.deleteUser(id); 
            fetchUsers(currentPage, searchTerm);
