import React, { useState, useEffect } from 'react';
import { User, Quiz, UserRole, Message, Lesson, LessonType } from '../../types';
import { StorageService } from '../../services/storageService';
import { ApiService } from '../../services/apiService';
import QuizTaker from '../Quiz/QuizTaker';
import WhiteboardRoom from '../Whiteboard/WhiteboardRoom';
import { LogOut, CheckCircle, Play, Lock, Clock, Calendar, MessageCircle, Send, BookOpen, Video, File, ExternalLink, User as UserIcon, Award, Star, Zap, PenTool, Download, Image as ImageIcon, FileText } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';

interface Props {
  user: User;
  onLogout: () => void;
  autoLaunchQuizId?: string | null;
}

const StudentDashboard: React.FC<Props> = ({ user: initialUser, onLogout, autoLaunchQuizId }) => {
  const { t, dir } = useLanguage();
  // Keep user state in sync for Gamification updates
  const [user, setUser] = useState<User>(initialUser);
  const [activeTab, setActiveTab] = useState<'quizzes' | 'lessons' | 'messages' | 'whiteboard'>('quizzes');
  const [activeQuiz, setActiveQuiz] = useState<Quiz | null>(null);
  const [selectedQuizForAuth, setSelectedQuizForAuth] = useState<Quiz | null>(null);
  const [accessCodeInput, setAccessCodeInput] = useState('');
  const [errorMsg, setErrorMsg] = useState('');

  // Messaging
  const [professors, setProfessors] = useState<User[]>([]);
  const [selectedProfId, setSelectedProfId] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');

  // Whiteboard
  const [wbKey, setWbKey] = useState('');
  const [activeWhiteboard, setActiveWhiteboard] = useState<string | null>(null);

  // Refresh user data (XP/Badges) periodically & Update Last Login
  useEffect(() => {
    // 1. Update Last Login
    StorageService.updateLastLogin(user.id);

    // 2. Poll for updates
    const interval = setInterval(() => {
        const freshUsers = StorageService.getUsers();
        const me = freshUsers.find(u => u.id === user.id);
        if (me) setUser(me);
    }, 5000);
    return () => clearInterval(interval);
  }, [user.id]);

  // Pass the full user object to enable school filtering
  const quizzes = StorageService.getAvailableQuizzesForStudent(user);
  const lessons = StorageService.getLessonsForStudent(user);
  const myResults = StorageService.getResults().filter(r => r.studentId === user.id);

  const getQuizResult = (quizId: string) => myResults.find(r => r.quizId === quizId);

  useEffect(() => {
      // Load professors linked to the student (using API to be safe)
      const loadProfs = async () => {
          const apiUsers = await ApiService.getUsers();
          const studentClasses = new Set(user.enrolledClasses || []);
          if (user.class) studentClasses.add(user.class);

          const myProfs = apiUsers.filter(u => 
              u.role === UserRole.PROFESSOR && 
              u.school === user.school && 
              u.city === user.city &&
              u.assignedSections?.some(section => studentClasses.has(section))
          );
          setProfessors(myProfs);
      };
      loadProfs();
  }, [user]);

  useEffect(() => {
      if (selectedProfId) {
          setMessages(StorageService.getMessages(user.id, selectedProfId));
      }
  }, [selectedProfId]);

  useEffect(() => {
      if (autoLaunchQuizId) {
          const found = quizzes.find(q => q.id === autoLaunchQuizId);
          if (found && !getQuizResult(found.id)) {
              handleStartClick(found);
          }
      }
  }, [autoLaunchQuizId]); 

  const handleStartClick = (quiz: Quiz) => {
      // Check dates
      const now = new Date();
      if (quiz.startDate && new Date(quiz.startDate) > now) return;
      if (quiz.dueDate && new Date(quiz.dueDate) < now) return;

      if (quiz.accessCode) {
          setSelectedQuizForAuth(quiz);
          setAccessCodeInput('');
          setErrorMsg('');
      } else {
          setActiveQuiz(quiz);
      }
  };

  const verifyAccessCode = () => {
      if (selectedQuizForAuth && accessCodeInput === selectedQuizForAuth.accessCode) {
          setActiveQuiz(selectedQuizForAuth);
          setSelectedQuizForAuth(null);
      } else {
          setErrorMsg(t('codeIncorrect'));
      }
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedProfId) return;

    const msg: Message = {
        id: `msg-${Date.now()}`,
        senderId: user.id,
        senderName: user.name,
        receiverId: selectedProfId,
        content: newMessage,
        timestamp: new Date().toISOString(),
        read: false
    };

    StorageService.sendMessage(msg);
    setMessages([...messages, msg]);
    setNewMessage('');
  };

  const joinWhiteboard = () => {
      const wb = StorageService.getWhiteboardByKey(wbKey.trim().toUpperCase());
      if (wb) {
          setActiveWhiteboard(wb.accessKey);
      } else {
          alert(t('codeIncorrect'));
      }
  };

  // Quiz Availability Helpers
  const getAvailabilityStatus = (quiz: Quiz) => {
      const now = new Date();
      if (quiz.startDate && new Date(quiz.startDate) > now) {
          return { status: 'FUTURE', date: new Date(quiz.startDate) };
      }
      if (quiz.dueDate && new Date(quiz.dueDate) < now) {
          return { status: 'EXPIRED', date: new Date(quiz.dueDate) };
      }
      return { status: 'OPEN' };
  };

  const getYoutubeId = (url: string) => {
      if (!url) return null;
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
      return (match && match[2].length === 11) ? match[2] : null;
  };

  const getProfName = (profId: string) => {
      // Try local first, but ideally should be ID lookup if we had full list
      const prof = StorageService.getUsers().find(u => u.id === profId);
      return prof ? prof.name : 'Professeur';
  };

  // Gamification Helper
  const getBadgeIcon = (id: string) => {
      switch(id) {
          case 'badge_first_quiz': return <CheckCircle className="w-5 h-5 text-green-500" />;
          case 'badge_perfect_score': return <Star className="w-5 h-5 text-yellow-500" />;
          case 'badge_speedster': return <Zap className="w-5 h-5 text-purple-500" />;
          default: return <Award className="w-5 h-5 text-blue-500" />;
      }
  };

  const renderLessonContent = (lesson: Lesson) => {
      const url = lesson.contentUrl;
      const isVideo = lesson.type === LessonType.VIDEO;

      // 1. YouTube Video
      if (isVideo) {
          const ytId = getYoutubeId(url);
          if (ytId) {
              return (
                  <div className="aspect-video rounded-lg overflow-hidden shadow">
                      <iframe 
                        width="100%" 
                        height="100%" 
                        src={`https://www.youtube.com/embed/${ytId}`} 
                        title={lesson.title}
                        frameBorder="0" 
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                        allowFullScreen
                      ></iframe>
                  </div>
              );
          }
      }

      // 2. Images
      if (url.match(/\.(jpeg|jpg|gif|png|webp)$/i)) {
          return (
              <div className="bg-gray-50 rounded-lg p-4 flex flex-col items-center">
                  <img src={url} alt={lesson.title} className="max-h-[400px] w-auto rounded shadow-sm border" />
                  <a href={url} download className="mt-4 text-blue-600 hover:underline flex items-center gap-2">
                      <Download className="w-4 h-4"/> Télécharger l'image
                  </a>
              </div>
          );
      }

      // 3. PDF
      if (url.match(/\.pdf$/i)) {
          return (
              <div className="bg-gray-50 rounded-lg p-4 border flex flex-col items-center justify-center min-h-[200px]">
                  <FileText className="w-16 h-16 text-red-500 mb-2"/>
