                             <button onClick={() => setForm({...form, type: LessonType.DOCUMENT})} className={`flex-1 py-2 border rounded ${form.type === LessonType.DOCUMENT ? 'bg-blue-50 border-blue-500 text-blue-600' : ''}`}>Doc</button>
