const StudentsView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [classFilter, setClassFilter] = useState('');
    const [students, setStudents] = useState<User[]>([]);
    const [localAssignedClasses, setLocalAssignedClasses] = useState<string[]>(user.assignedSections || []);

    // Individual Mode State
    const isIndividual = user.accountType === 'INDIVIDUAL';
    const [newClassName, setNewClassName] = useState('');
    const [showPasswords, setShowPasswords] = useState(false);

    const refreshStudents = async () => {
        const allUsers = await ApiService.getUsers();
        setStudents(allUsers.filter(u => u.role === UserRole.STUDENT));
    };

    useEffect(() => {
        refreshStudents();
    }, []);

    // Filter Logic
    const filteredStudents = students.filter(s => {
        // For individual, match school/city scope (which is usually the Prof name or "Individual")
        // or check if student is in one of the prof's custom classes
        if (s.school !== user.school || s.city !== user.city) return false;

        const sClasses = s.enrolledClasses || [];
        const isInProfClasses = sClasses.some(c => localAssignedClasses.includes(c));

        if (!isInProfClasses) return false;
        if (classFilter) return sClasses.includes(classFilter);
        return true;
    });

    // --- INDIVIDUAL MODE ACTIONS ---

    const handleAddClass = async () => {
        if (!newClassName.trim()) return;
        if (localAssignedClasses.includes(newClassName.trim())) {
            alert(t('classExists'));
            return;
        }
        const updatedClasses = [...localAssignedClasses, newClassName.trim()];
        setLocalAssignedClasses(updatedClasses);

        // Update User Profile with new class list
        await ApiService.updateUser(user.id, { assignedSections: updatedClasses });
        setNewClassName('');
    };

    const handleDeleteClass = async (cls: string) => {
        if (!confirm(t('delete') + ` ${cls}?`)) return;
        const updatedClasses = localAssignedClasses.filter(c => c !== cls);
        setLocalAssignedClasses(updatedClasses);
        await ApiService.updateUser(user.id, { assignedSections: updatedClasses });
    };

    const handleStudentUpload = (e: React.ChangeEvent<HTMLInputElement>, targetClass: string) => {
        const file = e.target.files?.[0];
        if (!file || !targetClass) return;

        const reader = new FileReader();
        reader.onload = async (evt) => {
            const bstr = evt.target?.result;
            const wb = XLSX.read(bstr, { type: 'binary' });
            const ws = wb.Sheets[wb.SheetNames[0]];
            const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

            let added = 0;
            const existingUsers = await ApiService.getUsers();

            for (const row of data.slice(1)) {
                // @ts-ignore
                if (row[0]) {
                    // @ts-ignore
                    const name = String(row[0]).trim();
                    if (!name) continue;

                    // Generate unique username
                    const cleanName = name.toLowerCase().replace(/[^a-z0-9]/g, '');
                    const username = `${cleanName.substring(0,8)}${Math.floor(Math.random()*9000)+1000}`;
                    const password = Math.floor(100000 + Math.random() * 900000).toString();

                    const newStudent: User = {
                        id: `stu-${Date.now()}-${Math.random()}`,
                        name,
                        username,
                        password,
                        readablePassword: password,
                        role: UserRole.STUDENT,
                        class: targetClass,
                        enrolledClasses: [targetClass],
                        // Important: Link student to Individual Prof's "School/City" scope
                        school: user.school,
                        city: user.city,
                        accountType: 'INDIVIDUAL' // Mark student as belonging to individual
                    };
                    await ApiService.createUser(newStudent);
                    added++;
                }
            }
            alert(`${added} ${t('studentsAdded')}`);
            e.target.value = '';
            refreshStudents();
        };
        reader.readAsBinaryString(file);
    };

    return (
        <div className="space-y-6 animate-fade-in">
            {/* --- INDIVIDUAL PROFESSOR MANAGEMENT SECTION --- */}
            {isIndividual && (
                <div className="bg-indigo-50 border border-indigo-100 p-6 rounded-lg shadow-sm">
                    <h2 className="text-lg font-bold text-indigo-800 mb-4 flex items-center gap-2">
                        <Settings className="w-5 h-5"/> Gestion de mes Classes (Indépendant)
                    </h2>

                    <div className="flex gap-2 mb-6">
                        <input 
                            className="border rounded p-2 text-sm flex-1" 
                            placeholder="Nom de la nouvelle classe (ex: Soutien Math Lundi)" 
                            value={newClassName} 
                            onChange={e => setNewClassName(e.target.value)} 
                        />
                        <button onClick={handleAddClass} className="bg-indigo-600 text-white px-4 py-2 rounded text-sm flex items-center gap-2 hover:bg-indigo-700">
                            <PlusCircle className="w-4 h-4"/> {t('addClass')}
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {localAssignedClasses.map(cls => (
                            <div key={cls} className="bg-white p-4 rounded border flex flex-col gap-3 relative group">
                                <div className="flex justify-between items-start">
                                    <h3 className="font-bold text-gray-800">{cls}</h3>
                                    <button onClick={() => handleDeleteClass(cls)} className="text-gray-400 hover:text-red-500"><Trash2 className="w-4 h-4"/></button>
                                </div>
                                <label className="cursor-pointer bg-blue-50 text-blue-700 border border-blue-200 px-3 py-2 rounded text-xs flex items-center justify-center gap-2 hover:bg-blue-100 transition">
                                    <Upload className="w-3 h-3"/> {t('importExcel')} (Liste Élèves)
                                    <input type="file" accept=".xlsx" className="hidden" onChange={(e) => handleStudentUpload(e, cls)} />
                                </label>
                            </div>
                        ))}
