                                    <h3 className="font-bold text-lg text-gray-800">{l.title}</h3>
                                    <p className="text-gray-600 text-sm mb-1">{l.description}</p>
                                    <div className="flex items-center gap-2 text-xs text-gray-500">
                                        <UserIcon className="w-3 h-3"/>
