                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <form onSubmit={handleSendMessage} className="p-4 border-t flex gap-2">
                                    <input 
                                        className="flex-1 border rounded-full px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                                        placeholder={t('typeMessage')}
                                        value={newMessage}
                                        onChange={(e) => setNewMessage(e.target.value)}
                                    />
                                    <button type="submit" className="bg-blue-600 text-white p-2 rounded-full hover:bg-blue-700">
                                        <Send className="w-5 h-5 rtl:flip" />
                                    </button>
                                </form>
                           </>
                       ) : (
                           <div className="flex-1 flex items-center justify-center text-gray-400"><p>{t('selectProf')}</p></div>
                       )}
                 </div>
             </div>
          )}

          {activeTab === 'whiteboard' && (
              <div className="bg-white p-8 rounded-lg shadow-sm border text-center max-w-md mx-auto">
                  <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
                      <PenTool className="w-8 h-8"/>
                  </div>
                  <h2 className="text-xl font-bold mb-2">{t('joinWhiteboard')}</h2>
                  <p className="text-gray-500 mb-6">{t('enterWbKey')}</p>
                  <div className="flex gap-2">
                      <input 
                          className="flex-1 border rounded-lg p-3 text-center font-mono uppercase tracking-widest text-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
                          placeholder="######"
                          value={wbKey}
                          onChange={e => setWbKey(e.target.value.toUpperCase())}
                          maxLength={6}
                      />
                      <button onClick={joinWhiteboard} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-blue-700">
                          {t('enter')}
                      </button>
                  </div>
              </div>
          )}

      </main>
    </div>
  );
};

