                            {Number(avgCO2) > 1000 ? (
                                <div className="text-xs text-red-600 mt-1 font-bold animate-pulse">{t('warning')}</div>
                            ) : (
                                <div className="text-xs text-green-600 mt-1">{t('airQuality')} OK</div>
