    const handleCreateWhiteboard = () => {
        const key = Math.random().toString(36).substring(2, 8).toUpperCase();
        const session = {
            id: `wb-${Date.now()}`,
            hostId: user.id,
            hostName: user.name,
            title: `Cours de ${user.name}`,
            accessKey: key,
            isActive: true,
