        <div className="min-h-screen bg-gray-50 flex" dir={dir}>
            {/* Sidebar */}
            <aside className="w-64 bg-white border-r hidden md:flex flex-col z-10">
                <div className="p-6 border-b flex items-center gap-3 bg-blue-700 text-white">
