const StructureView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [structure, setStructure] = useState<SchoolStructure>({
        id: '', school: user.school || '', city: user.city || '', classes: []
    });
    const [newClass, setNewClass] = useState('');

    useEffect(() => {
        if (user.school && user.city) {
            const existing = StorageService.getSchoolStructure(user.school, user.city);
            if (existing) setStructure(existing);
        }
    }, [user]);

    const addClass = () => {
        if (!newClass.trim()) return;
        if (structure.classes.includes(newClass.trim())) {
            alert(t('classExists'));
            return;
        }
        const updated = { ...structure, classes: [...structure.classes, newClass.trim()] };
        setStructure(updated);
        StorageService.saveSchoolStructure(updated);
        setNewClass('');
    };

    const removeClass = (cls: string) => {
        if(confirm(t('delete') + '?')) {
            const updated = { ...structure, classes: structure.classes.filter(c => c !== cls) };
            setStructure(updated);
            StorageService.saveSchoolStructure(updated);
        }
    };

    return (
        <div className="space-y-6 animate-fade-in">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                <Building className="w-6 h-6"/> {t('manageStructure')}
            </h2>

            <div className="bg-white p-6 rounded-xl shadow-sm border">
                <h3 className="font-bold text-lg mb-4 text-gray-700">{t('addClassToStructure')}</h3>
                <div className="flex gap-2 mb-6">
                    <input 
                        className="flex-1 border p-2 rounded"
                        placeholder="Ex: 2ème Année Bac - A"
                        value={newClass}
                        onChange={e => setNewClass(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && addClass()}
                    />
                    <button onClick={addClass} className="bg-blue-600 text-white px-4 py-2 rounded font-medium">{t('addQuestion')}</button>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                    {structure.classes.map(cls => (
                        <div key={cls} className="bg-gray-50 p-3 rounded border flex justify-between items-center group">
                            <span className="font-medium text-gray-800">{cls}</span>
                            <button onClick={() => removeClass(cls)} className="text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition">
                                <Trash2 className="w-4 h-4"/>
                            </button>
                        </div>
                    ))}
                    {structure.classes.length === 0 && <p className="text-gray-400 italic">Aucune classe configurée.</p>}
                </div>
            </div>
        </div>
    );
};

const StaffManagementView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [profs, setProfs] = useState<User[]>([]);
    const [structure, setStructure] = useState<SchoolStructure | undefined>(undefined);
    const [selectedProf, setSelectedProf] = useState<User | null>(null);

    useEffect(() => {
        if (user.school && user.city) {
            setStructure(StorageService.getSchoolStructure(user.school, user.city));
            const allUsers = StorageService.getUsers();
            setProfs(allUsers.filter(u => u.role === UserRole.PROFESSOR && u.school === user.school && u.city === user.city));
        }
    }, [user]);

    const handleAssign = (profId: string, sections: string[]) => {
        const prof = profs.find(p => p.id === profId);
        if (prof) {
            const updated = { ...prof, assignedSections: sections };
            StorageService.saveUser(updated);
            setProfs(profs.map(p => p.id === profId ? updated : p));
        }
    };

    return (
        <div className="space-y-6 animate-fade-in">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                <Users className="w-6 h-6"/> {t('manageStaff')}
            </h2>

            <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 border-b">
                        <tr>
                            <th className="p-4">{t('profName')}</th>
                            <th className="p-4">{t('assignedClassesToProf')}</th>
                            <th className="p-4 text-end">{t('actions')}</th>
                        </tr>
                    </thead>
                    <tbody>
                        {profs.map(p => (
                            <tr key={p.id} className="border-b last:border-0 hover:bg-gray-50">
                                <td className="p-4 font-bold">{p.name}</td>
                                <td className="p-4">
                                    {(p.assignedSections && p.assignedSections.length > 0) ? (
                                        <div className="flex flex-wrap gap-1">
                                            {p.assignedSections.map(s => <span key={s} className="bg-blue-100 text-blue-700 px-2 py-0.5 rounded text-xs">{s}</span>)}
                                        </div>
                                    ) : (
                                        <span className="text-gray-400 italic text-xs">{t('noAssignedClasses')}</span>
                                    )}
                                </td>
                                <td className="p-4 text-end">
                                    <button onClick={() => setSelectedProf(p)} className="text-blue-600 hover:underline text-xs font-medium">{t('assignClasses')}</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {selectedProf && structure && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-lg">
                        <h3 className="font-bold text-lg mb-4">{t('selectClassesForProf')} {selectedProf.name}</h3>
                        <div className="grid grid-cols-2 gap-2 max-h-60 overflow-y-auto mb-6">
                            {structure.classes.map(cls => {
                                const isAssigned = selectedProf.assignedSections?.includes(cls);
                                return (
                                    <label key={cls} className={`flex items-center gap-2 p-2 rounded border cursor-pointer ${isAssigned ? 'bg-blue-50 border-blue-200' : 'hover:bg-gray-50'}`}>
                                        <input 
                                            type="checkbox" 
                                            checked={isAssigned || false}
                                            onChange={() => {
                                                const current = selectedProf.assignedSections || [];
                                                const newSections = isAssigned ? current.filter(c => c !== cls) : [...current, cls];
                                                handleAssign(selectedProf.id, newSections);
                                                // Local update for modal
                                                setSelectedProf({ ...selectedProf, assignedSections: newSections });
                                            }}
                                            className="rounded text-blue-600"
                                        />
                                        <span className="text-sm">{cls}</span>
                                    </label>
                                );
                            })}
                        </div>
                        <div className="flex justify-end">
                            <button onClick={() => setSelectedProf(null)} className="px-4 py-2 bg-gray-100 hover:bg-gray-200 rounded text-sm font-medium">{t('close')}</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

