const IoTView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [devices, setDevices] = useState<IoTDevice[]>([]);

    useEffect(() => {
        if (user.school && user.city) {
            setDevices(StorageService.getIoTDevices(user.school, user.city));
