                                    </div>
                                </>
                            )}
                            {d.type === 'GPS_TRACKER' && (
                                <>
                                    <div className="flex justify-between items-center">
                                        <span className="text-gray-500 text-xs uppercase font-bold">{t('speed')}</span>
                                        <span className="font-mono font-bold text-gray-800">{d.data.speed} km/h</span>
