                                <button onClick={() => setShowPasswords(!showPasswords)} className="flex items-center gap-1 hover:text-indigo-600">
                                    {t('password')} {showPasswords ? <EyeOff className="w-3 h-3"/> : <Eye className="w-3 h-3"/>}
                                </button>
