    useEffect(() => {
        const timer = setInterval(() => {
            setElapsedTime(prev => {
                if (prev + 1 >= requiredTime) setCanComplete(true);
                return prev + 1;
            });
        }, 1000);
        return () => clearInterval(timer);
    }, [requiredTime]);

    const handleSaveNotes = () => {
        // Here we could save notes to a DB in a future update
        localStorage.setItem(`notes_${lesson.id}`, notes);
        alert("Notes enregistrées !");
    };

    const progress = Math.min((elapsedTime / requiredTime) * 100, 100);

    return (
        <div className="fixed inset-0 bg-gray-100 z-50 flex flex-col animate-fade-in">
            {/* Top Bar */}
            <div className="bg-white border-b p-4 flex justify-between items-center shadow-sm h-16 shrink-0">
