const StudentDashboard: React.FC<{ user: User, onLogout: () => void, autoLaunchQuizId?: string | null }> = ({ user, onLogout, autoLaunchQuizId }) => {
    const { t, dir } = useLanguage();
    const location = useLocation();
    const [activeQuiz, setActiveQuiz] = useState<Quiz | null>(null);
    const [joinWbKey, setJoinWbKey] = useState('');
    const [showWbInput, setShowWbInput] = useState(false);
    const [wbAccessKey, setWbAccessKey] = useState<string | null>(null);

    // Auto-launch quiz if ID passed
    useEffect(() => {
        if (autoLaunchQuizId) {
            const quiz = StorageService.getQuizzes().find(q => q.id === autoLaunchQuizId);
            if (quiz) setActiveQuiz(quiz);
        }
    }, [autoLaunchQuizId]);

    const isActive = (path: string) => location.pathname.includes(`/student/${path}`);

    const handleJoinWhiteboard = () => {
        if (joinWbKey.length === 6) {
            setWbAccessKey(joinWbKey);
            setShowWbInput(false);
        } else {
            alert("Code invalide (6 caractères)");
        }
    };

    if (activeQuiz) {
        return (
            <div className="min-h-screen bg-gray-50 py-8 px-4" dir={dir}>
                <QuizTaker 
                    quiz={activeQuiz} 
                    studentId={user.id} 
                    studentName={user.name} 
                    onComplete={() => setActiveQuiz(null)} 
                />
            </div>
