                                className="w-full border rounded-lg p-3 text-center text-2xl font-mono tracking-widest uppercase mb-4 focus:ring-2 focus:ring-blue-500 outline-none"
                                maxLength={6}
                                placeholder="ABC123"
                                value={joinWbKey}
                                onChange={e => setJoinWbKey(e.target.value.toUpperCase())}
                            />
                            <div className="flex gap-2">
                                <button onClick={() => setShowWbInput(false)} className="flex-1 py-2 text-gray-500 hover:bg-gray-100 rounded">{t('cancel')}</button>
                                <button onClick={handleJoinWhiteboard} className="flex-1 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 font-medium">{t('enter')}</button>
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

