                         <span className="text-xs text-gray-400">{new Date(l.createdAt).toLocaleDateString()}</span>
                    </div>
                    <h3 className="font-bold text-lg text-gray-800 mb-2 group-hover:text-blue-600 transition-colors">{l.title}</h3>
                    <p className="text-sm text-gray-500 line-clamp-3 mb-4">{l.description}</p>

                    {l.type === 'INTERACTIVE' ? (
                        <button 
                            onClick={() => setActiveLesson(l)}
                            className="block w-full text-center bg-indigo-600 hover:bg-indigo-700 text-white py-2 rounded-lg font-bold transition flex items-center justify-center gap-2"
                        >
                            <Eye className="w-4 h-4"/> Commencer la lecture
                        </button>
                    ) : (
                        <a 
                            href={l.contentUrl} 
                            target="_blank" 
                            rel="noreferrer" 
                            className="block w-full text-center bg-gray-50 hover:bg-gray-100 border text-gray-700 py-2 rounded-lg font-medium transition"
                        >
                            {t('viewContent')}
                        </a>
                    )}
