            ))}
            {lessons.length === 0 && (
                <div className="col-span-full text-center py-12 bg-white rounded-xl border border-dashed border-gray-300">
                    <BookOpen className="w-12 h-12 text-gray-300 mx-auto mb-3"/>
                    <p className="text-gray-500">Aucun cours disponible.</p>
                </div>
            )}
        </div>
    );
};

// Main Dashboard Component
const StudentDashboard: React.FC<{ user: User, onLogout: () => void, autoLaunchQuizId?: string | null }> = ({ user, onLogout, autoLaunchQuizId }) => {
    const { t, dir } = useLanguage();
    const location = useLocation();
    const [activeQuiz, setActiveQuiz] = useState<Quiz | null>(null);
    const [joinWbKey, setJoinWbKey] = useState('');
    const [showWbInput, setShowWbInput] = useState(false);
    const [wbAccessKey, setWbAccessKey] = useState<string | null>(null);

    // Auto-launch quiz if ID passed
    useEffect(() => {
        if (autoLaunchQuizId) {
            const quiz = StorageService.getQuizzes().find(q => q.id === autoLaunchQuizId);
            if (quiz) setActiveQuiz(quiz);
        }
    }, [autoLaunchQuizId]);

    const isActive = (path: string) => location.pathname.includes(`/student/${path}`);

    const handleJoinWhiteboard = () => {
        if (joinWbKey.length === 6) {
            setWbAccessKey(joinWbKey);
            setShowWbInput(false);
        } else {
            alert("Code invalide (6 caractères)");
        }
    };

    if (activeQuiz) {
        return (
            <div className="min-h-screen bg-gray-50 py-8 px-4" dir={dir}>
                <QuizTaker 
                    quiz={activeQuiz} 
                    studentId={user.id} 
                    studentName={user.name} 
                    onComplete={() => setActiveQuiz(null)} 
                />
            </div>
        );
    }

    if (wbAccessKey) {
        return <WhiteboardRoom user={user} accessKey={wbAccessKey} onExit={() => setWbAccessKey(null)} />;
    }

    return (
        <div className="min-h-screen bg-gray-50 flex" dir={dir}>
            {/* Sidebar */}
            <aside className="w-64 bg-white border-r hidden md:flex flex-col z-10">
                <div className="p-6 border-b flex items-center gap-3 bg-blue-700 text-white">
                    <div className="w-10 h-10 bg-white/20 rounded-lg flex items-center justify-center backdrop-blur-sm">
                        <UserIcon className="w-6 h-6 text-white"/>
                    </div>
                    <div>
                        <h1 className="font-bold font-logo text-lg tracking-tight">Tinmel</h1>
                        <p className="text-xs text-blue-200">{t('studentSpace')}</p>
                    </div>
                </div>

                <nav className="flex-1 p-4 space-y-1">
                    {[
                        { id: 'home', icon: LayoutDashboard, label: 'Accueil' },
                        { id: 'quizzes', icon: FileText, label: 'Quiz' },
                        { id: 'lessons', icon: BookOpen, label: 'Cours' },
                    ].map(item => (
                        <Link 
                            key={item.id}
                            to={`/student/${item.id}`}
                            className={`flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-lg transition-colors ${isActive(item.id) ? 'bg-blue-50 text-blue-600' : 'text-gray-600 hover:bg-gray-50 hover:text-blue-600'}`}
                        >
                            <item.icon className="w-5 h-5"/> {item.label}
                        </Link>
                    ))}
                    <button 
                        onClick={() => setShowWbInput(true)}
                        className="w-full flex items-center gap-3 px-4 py-3 text-sm font-medium text-gray-600 hover:bg-gray-50 hover:text-blue-600 rounded-lg transition-colors text-start"
                    >
                        <PenTool className="w-5 h-5"/> {t('joinWhiteboard')}
                    </button>
                </nav>

                <div className="p-4 border-t">
                     <button onClick={onLogout} className="flex items-center gap-2 text-red-600 hover:bg-red-50 w-full px-4 py-2 rounded-lg transition-colors text-sm font-medium">
                        <LogOut className="w-4 h-4 rtl:flip"/> {t('logout')}
                    </button>
                </div>
            </aside>

            {/* Main Content */}
            <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
                <header className="h-16 bg-white border-b flex items-center justify-between px-6 shrink-0 relative z-0">
                     <HeaderBackground />
                     <div className="z-10 flex items-center gap-4">
                         <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 text-white rounded-full flex items-center justify-center font-bold text-lg shadow">
                             {user.name.charAt(0).toUpperCase()}
                         </div>
                         <div>
                             <h2 className="font-bold text-gray-800">{user.name}</h2>
                             <p className="text-xs text-gray-500">{user.class || 'Classe non assignée'}</p>
                         </div>
                     </div>
                </header>

                <div className="flex-1 overflow-auto p-6 relative z-0">
                    <Routes>
                        <Route path="home" element={<HomeView user={user} />} />
                        <Route path="quizzes" element={<QuizzesListView user={user} onStartQuiz={setActiveQuiz} />} />
                        <Route path="lessons" element={<LessonsView user={user} />} />
                        <Route path="*" element={<Navigate to="home" replace />} />
                    </Routes>
                </div>

                {/* Whiteboard Join Modal */}
                {showWbInput && (
                    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-fade-in">
                        <div className="bg-white rounded-xl shadow-2xl p-6 w-full max-w-sm">
                            <h3 className="font-bold text-lg mb-4 flex items-center gap-2">
                                <PenTool className="w-5 h-5 text-blue-600"/> {t('joinWhiteboard')}
                            </h3>
                            <p className="text-sm text-gray-500 mb-4">{t('enterWbKey')}</p>
                            <input 
                                className="w-full border rounded-lg p-3 text-center text-2xl font-mono tracking-widest uppercase mb-4 focus:ring-2 focus:ring-blue-500 outline-none"
                                maxLength={6}
                                placeholder="ABC123"
                                value={joinWbKey}
                                onChange={e => setJoinWbKey(e.target.value.toUpperCase())}
                            />
                            <div className="flex gap-2">
                                <button onClick={() => setShowWbInput(false)} className="flex-1 py-2 text-gray-500 hover:bg-gray-100 rounded">{t('cancel')}</button>
                                <button onClick={handleJoinWhiteboard} className="flex-1 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 font-medium">{t('enter')}</button>
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

