                                    <span className="text-[10px] text-orange-600 font-bold bg-white px-1 rounded border border-orange-200 mt-1 inline-block">EXAMEN / DEVOIR</span>
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-8 text-gray-400 flex flex-col items-center">
                                <Calendar className="w-8 h-8 mb-2 opacity-50"/>
                                <p className="text-sm">Aucune date limite proche.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Subjects Table / Cards */}
            <div>
                <h2 className="text-xl font-bold text-gray-800 mb-6 flex items-center gap-2">
                    <Book className="w-6 h-6 text-indigo-600"/> Mes Matières & Progression
                </h2>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    {subjectStats.map((sub, idx) => (
                        <div key={idx} className="bg-white rounded-xl border border-gray-200 shadow-sm p-5 hover:shadow-md transition-shadow">
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <h3 className="font-bold text-lg text-gray-800 flex items-center gap-2">
                                        {sub.subject}
                                    </h3>
                                    <p className="text-sm text-gray-500">{t('prof')} {sub.profName}</p>
                                </div>
                                <div className={`text-xl font-black ${sub.average >= 70 ? 'text-green-600' : sub.average >= 50 ? 'text-yellow-600' : 'text-red-500'}`}>
                                    {sub.average}%
                                </div>
                            </div>

                            <div className="space-y-4">
                                {/* Progress Bar */}
                                <div>
                                    <div className="flex justify-between text-xs text-gray-600 mb-1 font-medium">
                                        <span>Avancement du programme</span>
                                        <span>{sub.quizzesTaken} / {sub.totalQuizzes} Quiz</span>
                                    </div>
                                    <div className="w-full bg-gray-100 h-2.5 rounded-full overflow-hidden">
                                        <div 
                                            className={`h-full rounded-full transition-all duration-1000 ${sub.progress === 100 ? 'bg-green-500' : 'bg-blue-600'}`} 
                                            style={{ width: `${sub.progress}%` }}
                                        ></div>
                                    </div>
                                </div>

                                {/* Quick Stats Row */}
                                <div className="flex gap-4 pt-2 border-t border-gray-100">
                                    <div className="flex-1 bg-gray-50 rounded-lg p-2 text-center">
                                        <div className="text-xs text-gray-400 uppercase font-bold">Dernière activité</div>
                                        <div className="text-xs font-mono text-gray-700 mt-1">
                                            {sub.lastActivity ? new Date(sub.lastActivity).toLocaleDateString() : '-'}
                                        </div>
                                    </div>
                                    <div className="flex-1 bg-gray-50 rounded-lg p-2 text-center cursor-pointer hover:bg-yellow-50 transition group">
                                        <div className="text-xs text-gray-400 uppercase font-bold group-hover:text-yellow-600">Statut</div>
                                        <div className="text-xs font-bold text-gray-700 mt-1 flex justify-center items-center gap-1 group-hover:text-yellow-700">
                                            {sub.progress === 100 ? <><Award className="w-3 h-3"/> Complet</> : 'En cours'}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                    {subjectStats.length === 0 && (
                        <div className="col-span-full text-center py-12 bg-gray-50 rounded-xl border border-dashed border-gray-300">
                            <BookOpen className="w-12 h-12 text-gray-300 mx-auto mb-3"/>
                            <p className="text-gray-500">Vous n'êtes inscrit à aucune matière pour le moment.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

const StudentMessagesView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [contacts, setContacts] = useState<User[]>([]);
    const [selectedContactId, setSelectedContactId] = useState<string | null>(null);
    const [messages, setMessages] = useState<Message[]>([]);
    const [newMessage, setNewMessage] = useState('');

    useEffect(() => {
        const loadContacts = async () => {
            const allUsers = await ApiService.getUsers();
            const myClasses = user.enrolledClasses || (user.class ? [user.class] : []);

            // Filter: Only PROFESSORS who teach one of the student's classes
            const myTeachers = allUsers.filter(u => 
                u.role === UserRole.PROFESSOR && 
                u.school === user.school &&
                u.assignedSections?.some(section => myClasses.includes(section))
            );

            setContacts(myTeachers);
        };
        loadContacts();
    }, [user]);

    useEffect(() => {
        if (selectedContactId) {
            setMessages(StorageService.getMessages(user.id, selectedContactId));
            const interval = setInterval(() => {
                setMessages(StorageService.getMessages(user.id, selectedContactId));
            }, 3000);
            return () => clearInterval(interval);
        }
    }, [selectedContactId, user.id]);

    const handleSend = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMessage.trim() || !selectedContactId) return;
        const msg: Message = { id: `msg-${Date.now()}`, senderId: user.id, senderName: user.name, receiverId: selectedContactId, content: newMessage, timestamp: new Date().toISOString(), read: false };
        StorageService.sendMessage(msg);
        setMessages(prev => [...prev, msg]);
        setNewMessage('');
    };

    return (
        <div className="bg-white rounded-lg shadow h-[600px] flex overflow-hidden border animate-fade-in">
             <div className="w-1/3 border-e bg-gray-50 flex flex-col">
                <div className="p-4 border-b font-bold text-gray-700 flex items-center gap-2">
                    <MessageCircle className="w-5 h-5"/> {t('messages')}
                </div>
                <div className="flex-1 overflow-y-auto">
                     {contacts.length === 0 && (
                         <div className="p-6 text-center text-gray-400">
                             <p className="text-sm">Aucun enseignant assigné.</p>
                         </div>
                     )}
                     {contacts.map(contact => (
                        <button 
                            key={contact.id} 
                            onClick={() => setSelectedContactId(contact.id)} 
                            className={`w-full p-4 text-start hover:bg-blue-50 transition border-b flex justify-between items-center ${selectedContactId === contact.id ? 'bg-blue-100' : ''}`}
                        >
                            <div>
                                <div className="font-medium text-gray-800">{contact.name}</div>
                                <div className="text-xs text-gray-500 font-medium">{contact.subject || 'Professeur'}</div>
                            </div>
                            <ChevronRight className="w-4 h-4 text-gray-300"/>
                        </button>
                     ))}
                </div>
             </div>
             <div className="w-2/3 flex flex-col bg-white">
                  {selectedContactId ? (
                       <>
                            <div className="p-4 border-b font-bold bg-white flex items-center gap-2 shadow-sm z-10">
                                <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold">
                                    {contacts.find(u => u.id === selectedContactId)?.name.charAt(0)}
                                </div>
                                <div>
                                    <div className="text-gray-800 font-bold">{contacts.find(u => u.id === selectedContactId)?.name}</div>
                                    <div className="text-xs text-green-600 flex items-center gap-1"><div className="w-2 h-2 bg-green-500 rounded-full"></div> En ligne</div>
                                </div>
                            </div>
                            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50">
                                {messages.map(m => (
                                    <div key={m.id} className={`flex ${m.senderId === user.id ? 'justify-end' : 'justify-start'}`}>
                                        <div className={`max-w-[70%] p-3 rounded-2xl text-sm shadow-sm ${m.senderId === user.id ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border rounded-bl-none'}`}>
                                            {m.content}
                                            <div className={`text-[10px] mt-1 opacity-70 ${m.senderId === user.id ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                        </div>
                                    </div>
                                ))}
                                {messages.length === 0 && (
                                    <div className="text-center mt-10 text-gray-400">
                                        <p>Dites bonjour à votre professeur !</p>
                                    </div>
                                )}
                            </div>
                            <form onSubmit={handleSend} className="p-4 border-t bg-white flex gap-2">
                                <input 
                                    className="flex-1 border rounded-full px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none bg-gray-50" 
                                    placeholder={t('typeMessage')} 
                                    value={newMessage} 
                                    onChange={(e) => setNewMessage(e.target.value)} 
                                />
                                <button type="submit" className="bg-blue-600 text-white p-2 rounded-full hover:bg-blue-700 shadow-sm"><Send className="w-5 h-5 rtl:flip" /></button>
                            </form>
                       </>
                   ) : (
                       <div className="flex-1 flex flex-col items-center justify-center text-gray-400">
                           <MessageCircle className="w-16 h-16 mb-4 text-gray-200"/>
                           <p>Sélectionnez un professeur pour discuter.</p>
                       </div>
                   )}
             </div>
         </div>
    );
};

const QuizzesListView: React.FC<{ user: User, onStartQuiz: (q: Quiz) => void }> = ({ user, onStartQuiz }) => {
    const { t } = useLanguage();
    const [available, setAvailable] = useState<Quiz[]>([]);
    const [history, setHistory] = useState<QuizResult[]>([]);

    useEffect(() => {
        setAvailable(StorageService.getAvailableQuizzesForStudent(user));
