                     {contacts.length === 0 && (
                         <div className="p-6 text-center text-gray-400">
                             <p className="text-sm">Aucun enseignant assigné.</p>
                         </div>
                     )}
                     {contacts.map(contact => (
                        <button 
                            key={contact.id} 
                            onClick={() => setSelectedContactId(contact.id)} 
                            className={`w-full p-4 text-start hover:bg-blue-50 transition border-b flex justify-between items-center ${selectedContactId === contact.id ? 'bg-blue-100' : ''}`}
                        >
                            <div>
                                <div className="font-medium text-gray-800">{contact.name}</div>
                                <div className="text-xs text-gray-500 font-medium">{contact.subject || 'Professeur'}</div>
                            </div>
                            <ChevronRight className="w-4 h-4 text-gray-300"/>
                        </button>
                     ))}
                </div>
             </div>
             <div className="w-2/3 flex flex-col bg-white">
                  {selectedContactId ? (
                       <>
                            <div className="p-4 border-b font-bold bg-white flex items-center gap-2 shadow-sm z-10">
                                <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold">
                                    {contacts.find(u => u.id === selectedContactId)?.name.charAt(0)}
                                </div>
                                <div>
                                    <div className="text-gray-800 font-bold">{contacts.find(u => u.id === selectedContactId)?.name}</div>
                                    <div className="text-xs text-green-600 flex items-center gap-1"><div className="w-2 h-2 bg-green-500 rounded-full"></div> En ligne</div>
                                </div>
                            </div>
                            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50">
                                {messages.map(m => (
                                    <div key={m.id} className={`flex ${m.senderId === user.id ? 'justify-end' : 'justify-start'}`}>
                                        <div className={`max-w-[70%] p-3 rounded-2xl text-sm shadow-sm ${m.senderId === user.id ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border rounded-bl-none'}`}>
                                            {m.content}
                                            <div className={`text-[10px] mt-1 opacity-70 ${m.senderId === user.id ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</div>
                                        </div>
                                    </div>
                                ))}
                                {messages.length === 0 && (
                                    <div className="text-center mt-10 text-gray-400">
                                        <p>Dites bonjour à votre professeur !</p>
                                    </div>
                                )}
                            </div>
                            <form onSubmit={handleSend} className="p-4 border-t bg-white flex gap-2">
                                <input 
                                    className="flex-1 border rounded-full px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none bg-gray-50" 
                                    placeholder={t('typeMessage')} 
                                    value={newMessage} 
                                    onChange={(e) => setNewMessage(e.target.value)} 
                                />
                                <button type="submit" className="bg-blue-600 text-white p-2 rounded-full hover:bg-blue-700 shadow-sm"><Send className="w-5 h-5 rtl:flip" /></button>
                            </form>
                       </>
                   ) : (
                       <div className="flex-1 flex flex-col items-center justify-center text-gray-400">
                           <MessageCircle className="w-16 h-16 mb-4 text-gray-200"/>
                           <p>Sélectionnez un professeur pour discuter.</p>
                       </div>
                   )}
             </div>
         </div>
    );
};

const QuizzesListView: React.FC<{ user: User, onStartQuiz: (q: Quiz) => void }> = ({ user, onStartQuiz }) => {
    const { t } = useLanguage();
    const [available, setAvailable] = useState<Quiz[]>([]);
