                                l.type === 'VIDEO' ? 'bg-red-600 text-white hover:bg-red-700' :
                                l.type === 'INTERACTIVE' ? 'bg-indigo-600 text-white hover:bg-indigo-700' :
                                'bg-blue-600 text-white hover:bg-blue-700'
