const QuizzesView: React.FC<{ user: User, autoLaunchQuizId?: string | null }> = ({ user, autoLaunchQuizId }) => {
    const { t } = useLanguage();
    const [quizzes, setQuizzes] = useState<Quiz[]>([]);
    const [selectedQuiz, setSelectedQuiz] = useState<Quiz | null>(null);
    const [results, setResults] = useState<QuizResult[]>([]);

    useEffect(() => {
        const available = StorageService.getAvailableQuizzesForStudent(user);
        const myResults = StorageService.getResults().filter(r => r.studentId === user.id);

        // Mark taken quizzes
        const quizzesWithStatus = available.map(q => {
             const result = myResults.find(r => r.quizId === q.id);
             return { ...q, _result: result }; // Attach result for easy access
        });

        // @ts-ignore
        setQuizzes(quizzesWithStatus);
        setResults(myResults);

        if (autoLaunchQuizId) {
            const target = available.find(q => q.id === autoLaunchQuizId);
            if (target && !myResults.find(r => r.quizId === target.id)) {
                setSelectedQuiz(target);
            }
        }
    }, [user, autoLaunchQuizId]);

    if (selectedQuiz) {
        return (
            <div className="animate-fade-in">
                <button onClick={() => setSelectedQuiz(null)} className="mb-4 text-blue-600 hover:underline flex items-center gap-2">
                    <X className="w-4 h-4"/> {t('cancel')}
                </button>
                <QuizTaker 
                    quiz={selectedQuiz}
                    studentId={user.id}
                    studentName={user.name}
                    onComplete={() => {
                        setSelectedQuiz(null);
                        // Refresh
                        window.location.reload(); 
                    }}
                />
            </div>
        );
    }

    return (
        <div className="space-y-6 animate-fade-in">
            <h2 className="text-2xl font-bold text-gray-800">{t('myQuizzes')}</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {quizzes.map((q: any) => (
                    <div key={q.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 flex flex-col justify-between hover:shadow-md transition">
                        <div>
                            <div className="flex justify-between items-start mb-2">
                                <span className="bg-blue-50 text-blue-600 px-2 py-1 rounded text-xs font-bold">{q.questions.length} questions</span>
                                {q._result && (
                                    <span className="bg-green-100 text-green-700 px-2 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                                        <CheckCircle className="w-3 h-3"/> {t('completed')}
                                    </span>
                                )}
                            </div>
                            <h3 className="font-bold text-lg text-gray-800 mb-2">{q.title}</h3>
                            <p className="text-sm text-gray-500 mb-4 line-clamp-2">{q.description}</p>
                            {q.timeLimit && (
                                <div className="text-xs text-gray-500 flex items-center gap-1 mb-2">
                                    <Clock className="w-3 h-3"/> {q.timeLimit} {t('timeLimitLabel')}
                                </div>
                            )}
                        </div>

                        <div className="mt-4 pt-4 border-t">
                            {q._result ? (
                                <div className="text-center">
                                    <p className="text-xs text-gray-500 mb-1">{t('score')}</p>
                                    <div className="text-xl font-black text-gray-800">
                                        {q._result.score} / {q._result.maxScore}
                                    </div>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setSelectedQuiz(q)}
                                    className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 transition flex items-center justify-center gap-2"
                                >
                                    <Play className="w-4 h-4 fill-current"/> {t('start')}
                                </button>
                            )}
                        </div>
                    </div>
                ))}
                {quizzes.length === 0 && (
                    <div className="col-span-full text-center py-12 bg-white rounded-xl border border-dashed border-gray-300">
                        <FileText className="w-12 h-12 text-gray-300 mx-auto mb-3"/>
                        <p className="text-gray-500">Aucun quiz disponible pour le moment.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

