const MessagesView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [profs, setProfs] = useState<User[]>([]);
    const [selectedProfId, setSelectedProfId] = useState<string | null>(null);
    const [messages, setMessages] = useState<Message[]>([]);
    const [newMessage, setNewMessage] = useState('');

    useEffect(() => {
        const myProfs = StorageService.getProfessorsForStudent(user);
        setProfs(myProfs);
    }, [user]);

    useEffect(() => {
        if (selectedProfId) {
            setMessages(StorageService.getMessages(user.id, selectedProfId));
            const interval = setInterval(() => {
                setMessages(StorageService.getMessages(user.id, selectedProfId));
            }, 3000);
            return () => clearInterval(interval);
        }
    }, [selectedProfId, user.id]);

    const handleSend = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMessage.trim() || !selectedProfId) return;

        const msg: Message = { 
            id: `msg-${Date.now()}`, 
            senderId: user.id, 
            senderName: user.name, 
            receiverId: selectedProfId, 
            content: newMessage, 
            timestamp: new Date().toISOString(), 
            read: false 
        };

        StorageService.sendMessage(msg);
        setMessages(prev => [...prev, msg]);
        setNewMessage('');
    };

    return (
        <div className="bg-white rounded-lg shadow h-[600px] flex overflow-hidden border animate-fade-in">
             <div className="w-1/3 border-e bg-gray-50 flex flex-col">
                <div className="p-4 border-b font-bold text-gray-700">{t('contact')}</div>
                <div className="flex-1 overflow-y-auto">
                     {profs.length === 0 && <p className="p-4 text-sm text-gray-500 text-center">Aucun professeur assigné.</p>}
                     {profs.map(prof => (
                        <button 
                            key={prof.id} 
                            onClick={() => setSelectedProfId(prof.id)} 
                            className={`w-full p-4 text-start hover:bg-blue-50 transition border-b flex justify-between items-center group ${selectedProfId === prof.id ? 'bg-blue-100 border-l-4 border-l-blue-600' : 'border-l-4 border-l-transparent'}`}
                        >
                            <div>
                                <div className="font-bold text-gray-800 text-sm group-hover:text-blue-700">{prof.name}</div>
                                <div className="text-xs text-gray-500">{prof.subject}</div>
                            </div>
                            <ChevronRight className={`w-4 h-4 text-gray-300 ${selectedProfId === prof.id ? 'text-blue-500' : ''}`}/>
                        </button>
                     ))}
                </div>
             </div>
             <div className="w-2/3 flex flex-col bg-white">
                  {selectedProfId ? (
                       <>
                            <div className="p-4 border-b font-bold bg-white flex items-center gap-3 shadow-sm z-10">
                                <div className="w-3 h-3 rounded-full bg-green-500 animate-pulse"></div>
                                <div>
                                    <div className="text-gray-800">{profs.find(u => u.id === selectedProfId)?.name}</div>
                                    <div className="text-xs text-gray-400 font-normal">{t('online')}</div>
                                </div>
                            </div>
                            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
                                {messages.map(m => (
                                    <div key={m.id} className={`flex ${m.senderId === user.id ? 'justify-end' : 'justify-start'}`}>
                                        <div className={`max-w-[70%] p-3 rounded-2xl text-sm shadow-sm ${m.senderId === user.id ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white border text-gray-800 rounded-bl-none'}`}>
                                            {m.content}
                                            <div className={`text-[10px] mt-1 text-end ${m.senderId === user.id ? 'text-blue-200' : 'text-gray-400'}`}>
                                                {new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                            <form onSubmit={handleSend} className="p-4 border-t bg-white flex gap-2">
                                <input 
                                    className="flex-1 border rounded-full px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none bg-gray-50" 
                                    placeholder={t('typeMessage')} 
                                    value={newMessage} 
                                    onChange={(e) => setNewMessage(e.target.value)} 
                                />
                                <button type="submit" className="bg-blue-600 text-white p-3 rounded-full hover:bg-blue-700 shadow-md transition transform active:scale-95">
                                    <Send className="w-5 h-5 rtl:flip" />
                                </button>
                            </form>
                       </>
                   ) : (
                       <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-gray-50/30">
                           <MessageCircle className="w-16 h-16 text-gray-200 mb-4"/>
                           <p>Sélectionnez un professeur pour discuter.</p>
                       </div>
                   )}
             </div>
         </div>
    );
};

