                        <Route path="home" element={<HomeView user={user} />} />
                        <Route path="quizzes" element={<QuizzesView user={user} autoLaunchQuizId={autoLaunchQuizId} />} />
                        <Route path="lessons" element={<LessonsView user={user} />} />
                        <Route path="results" element={<ResultsView user={user} />} />
                        <Route path="messages" element={<MessagesView user={user} />} />
