                                        {(currentUser.assignedSections || []).length > 0 ? (
                                            currentUser.assignedSections?.map(cls => (
                                                <label key={cls} className="flex items-center gap-2 text-sm cursor-pointer p-1 rounded hover:bg-white transition">
