};

// --- MAIN APP COMPONENT ---

const AppContent: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isInstalled, setIsInstalled] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [autoLaunchQuizId, setAutoLaunchQuizId] = useState<string | null>(null);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
      const init = async () => {
          setLoading(true);

          // 1. Check Install Status
          try {
              const installStatus = await ApiService.checkInstallStatus();
              setIsInstalled(installStatus);

              if (!installStatus) {
                  setLoading(false);
                  return; // Stop here if not installed, show Wizard
              }
          } catch (e) {
              console.warn("Could not check install status", e);
              setIsInstalled(false); // Default to not installed on error
              setLoading(false);
              return;
          }

          // 2. Check Session
          const apiUser = await ApiService.checkSession();
          if (apiUser) {
              setUser(apiUser);
          } else {
              const session = StorageService.getSession();
              if (session) setUser(session);
          }

          const params = new URLSearchParams(window.location.search);
          const qId = params.get('quizId');
          if (qId) setAutoLaunchQuizId(qId);

          setLoading(false);
      };
      init();
  }, []);

  const getDashboardPath = (role: UserRole) => {
      switch(role) {
          case UserRole.ADMIN: return '/admin';
          case UserRole.PROFESSOR: return '/professor';
          case UserRole.STUDENT: return '/student';
          case UserRole.COORDINATOR: return '/coordinator';
          case UserRole.MODERATOR: return '/moderator';
          default: return '/';
      }
  };

  const handleLoginSuccess = (loggedInUser: User) => {
      StorageService.saveSession(loggedInUser);
      setUser(loggedInUser);
      navigate(getDashboardPath(loggedInUser.role));
  };

  const handleLogout = async () => {
      await ApiService.logout();
      StorageService.clearSession();
      setUser(null);
      navigate('/');
  };

  if (loading) {
      return (
          <div className="min-h-screen bg-blue-900 flex items-center justify-center">
              <div className="flex flex-col items-center gap-4">
                  <Loader2 className="w-12 h-12 text-white animate-spin" />
                  <p className="text-blue-200 text-sm font-medium">Initialisation du système...</p>
              </div>
          </div>
      );
  }

  // Si pas installé, afficher le Wizard
  if (isInstalled === false) {
      return <InstallationWizard onInstalled={() => { setIsInstalled(true); window.location.reload(); }} />;
  }

  return (
    <Routes>
        {/* Public Routes */}
        <Route path="/" element={!user ? <LandingPage /> : <Navigate to={getDashboardPath(user.role)} replace />} />

        <Route path="/login/student" element={
            !user ? <LoginPage role="STUDENT" onLoginSuccess={handleLoginSuccess} /> : <Navigate to={getDashboardPath(user.role)} replace />
        } />

        <Route path="/login/staff" element={
            !user ? <LoginPage role="STAFF" onLoginSuccess={handleLoginSuccess} /> : <Navigate to={getDashboardPath(user.role)} replace />
        } />

        {/* Admin Portal Route (Legacy/Direct) */}
        <Route path="/tinmelad/*" element={
            !user ? <LoginPage role="ADMIN" onLoginSuccess={handleLoginSuccess} /> : 
            (user.role === UserRole.ADMIN ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />)
        } />

        {/* Protected Routes */}
        <Route path="/admin/*" element={<AuthGuard user={user} requiredRole={UserRole.ADMIN}><AdminDashboard onLogout={handleLogout} /></AuthGuard>} />
        <Route path="/professor/*" element={<AuthGuard user={user} requiredRole={UserRole.PROFESSOR}><ProfessorDashboard user={user!} onLogout={handleLogout} /></AuthGuard>} />
        <Route path="/student/*" element={<AuthGuard user={user} requiredRole={UserRole.STUDENT}><StudentDashboard user={user!} onLogout={handleLogout} autoLaunchQuizId={autoLaunchQuizId} /></AuthGuard>} />
        <Route path="/coordinator/*" element={<AuthGuard user={user} requiredRole={UserRole.COORDINATOR}><CoordinatorDashboard user={user!} onLogout={handleLogout} /></AuthGuard>} />
        <Route path="/moderator/*" element={<AuthGuard user={user} requiredRole={UserRole.MODERATOR}><ModeratorDashboard user={user!} onLogout={handleLogout} /></AuthGuard>} />

        <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
};

const App: React.FC = () => {
  return (
    <LanguageProvider>
        <BrowserRouter>
            <AppContent />
        </BrowserRouter>
    </LanguageProvider>
  );
};

export default App;

import express from 'express';
import cors from 'cors';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import os from 'os'; // Added for system checks
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

// Nouveaux imports
import { db } from './backend/db.js';
import { emailService } from './backend/email.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3001;
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_opensource_secret_key_change_me_in_prod';
const LOCK_FILE = join(__dirname, 'installed.lock');

// --- INITIALISATION DB ---
db.connect({ path: process.env.DB_PATH || './database.sqlite' });

// --- CONFIGURATION MULTER ---
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
    destination: function (req, file, cb) { cb(null, uploadDir) },
    filename: function (req, file, cb) {
        const safeName = file.originalname.replace(/[^a-zA-Z0-9.]/g, "_");
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, uniqueSuffix + '-' + safeName);
    }
});

const upload = multer({ 
    storage: storage,
    limits: { fileSize: 5 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
        const allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        if (allowedTypes.includes(file.mimetype) || file.mimetype.startsWith('image/')) {
            cb(null, true);
        } else {
            cb(null, true); 
        }
    }
});

// Middleware
app.use(cors({
    origin: process.env.NODE_ENV === 'production' ? false : 'http://localhost:3000',
    credentials: true 
}));
app.use(express.json({ limit: '10mb' }));
app.use(cookieParser());
app.use('/uploads', express.static(uploadDir));

// --- AUTH MIDDLEWARE ---
const authenticateToken = (req, res, next) => {
    const token = req.cookies.token;
    if (!token) return res.status(401).json({ error: "Non authentifié" });

    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(403).json({ error: "Token invalide" });
        req.user = decoded;
        next();
    });
};

const requireRole = (roles) => {
    return (req, res, next) => {
        if (!req.user || !roles.includes(req.user.role)) {
            return res.status(403).json({ error: "Accès refusé" });
        }
        next();
    };
};

// --- SYSTEM & INSTALLATION ROUTES ---

// Vérification de l'état d'installation
app.get('/api/setup/status', async (req, res) => {
    try {
        const isLocked = fs.existsSync(LOCK_FILE);
        const admin = await db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'");

        const installed = isLocked && admin.count > 0;
        res.json({ installed });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// System Health Checks for Installer
app.get('/api/setup/checks', (req, res) => {
    const checks = {
        nodeVersion: process.version,
        platform: os.platform(),
        memory: Math.round(os.totalmem() / 1024 / 1024) + " MB",
        writeAccess: false,
        dbConnection: false
    };

    // Check Write Access
    try {
        const testFile = join(__dirname, 'write_test.tmp');
        fs.writeFileSync(testFile, 'test');
        fs.unlinkSync(testFile);
        checks.writeAccess = true;
    } catch (e) {
        checks.writeAccess = false;
    }

    // Check DB Connection (Since db is initialized at start)
    if (db.db) {
        checks.dbConnection = true;
    }

    res.json(checks);
});

// Installation Initiale (One-time)
app.post('/api/setup/install', async (req, res) => {
    if (fs.existsSync(LOCK_FILE)) {
        return res.status(403).json({ error: "L'application est déjà installée." });
    }

    const { username, password, name, schoolName, adminEmail, dbType, envMode } = req.body;
    if (!username || !password || !schoolName) return res.status(400).json({ error: "Champs requis" });

    try {
        // 1. Sauvegarder la configuration
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['site_name', schoolName]);
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['install_date', new Date().toISOString()]);
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['db_type', dbType || 'sqlite']);
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['env_mode', envMode || 'production']);

        // 2. Créer l'administrateur
        const id = `admin-${Date.now()}`;
        const hash = bcrypt.hashSync(password, 10);

        await db.run(
            `INSERT INTO users (id, username, password, name, role, email, data) VALUES (?, ?, ?, ?, ?, ?, ?)`, 
            [id, username.trim().toLowerCase(), hash, name || 'Administrateur', 'ADMIN', adminEmail || '', JSON.stringify({ schoolName })]
        );

        // 3. Verrouiller l'installation
        fs.writeFileSync(LOCK_FILE, `INSTALLED_ON=${new Date().toISOString()}\nDB=${dbType}\nMODE=${envMode}`);

        // 4. Envoyer email de bienvenue
        if (adminEmail) {
            await emailService.send(
                adminEmail, 
                "Bienvenue sur Tinmel LMS", 
                `Votre instance Tinmel a été installée avec succès.\nURL: ${req.get('host')}\nAdmin: ${username}\nMode: ${envMode}`
            );
        }

        res.json({ success: true });
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: err.message });
    }
});

