import sqlite3 from 'sqlite3';
import { join } from 'path';

// Abstraction de la base de données
// Permet de changer facilement de stratégie (SQLite -> MySQL/Postgres) plus tard.
class Database {
    constructor() {
        this.db = null;
        this.type = 'sqlite'; // 'sqlite', 'mysql', 'postgres'
    }

    connect(config = {}) {
        return new Promise((resolve, reject) => {
            if (this.type === 'sqlite') {
                const dbPath = config.path || './database.sqlite';
                this.db = new sqlite3.Database(dbPath, (err) => {
                    if (err) {
                        console.error('❌ DB Connection Error:', err);
                        reject(err);
                    } else {
                        console.log(`✅ Connected to SQLite database at ${dbPath}`);
                        this.initSchema().then(resolve).catch(reject);
                    }
                });
            } else {
                reject(new Error("Driver not implemented yet"));
            }
        });
    }

    // Promisify SQLite methods
    query(sql, params = []) {
        return new Promise((resolve, reject) => {
            this.db.all(sql, params, (err, rows) => {
                if (err) reject(err);
                else resolve(rows);
            });
        });
    }

    get(sql, params = []) {
        return new Promise((resolve, reject) => {
            this.db.get(sql, params, (err, row) => {
                if (err) reject(err);
                else resolve(row);
            });
        });
    }

    run(sql, params = []) {
        return new Promise((resolve, reject) => {
            this.db.run(sql, params, function (err) {
                if (err) reject(err);
                else resolve({ id: this.lastID, changes: this.changes });
            });
        });
    }

    async initSchema() {
        // Schema agnostique (ANSI SQL compatible autant que possible)
        const schemas = [
            `CREATE TABLE IF NOT EXISTS settings (
                key TEXT PRIMARY KEY,
                value TEXT
            )`,
            `CREATE TABLE IF NOT EXISTS users (
                id TEXT PRIMARY KEY,
                username TEXT UNIQUE,
                password TEXT,
                name TEXT,
                role TEXT,
                school TEXT,
                city TEXT,
                email TEXT,
                data TEXT
            )`,
            `CREATE TABLE IF NOT EXISTS quizzes (
                id TEXT PRIMARY KEY,
                professorId TEXT,
                title TEXT,
                status TEXT,
                data TEXT
            )`,
            `CREATE TABLE IF NOT EXISTS results (
                id TEXT PRIMARY KEY,
                quizId TEXT,
                studentId TEXT,
                score REAL,
                submittedAt TEXT,
                data TEXT
            )`,
            `CREATE TABLE IF NOT EXISTS email_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                to_email TEXT,
                subject TEXT,
                body TEXT,
                status TEXT,
                sent_at TEXT
            )`
        ];

        for (const sql of schemas) {
            await this.run(sql);
        }

        // --- MIGRATIONS AUTOMATIQUES ---
        // Vérifie et corrige la structure si la base de données existait déjà
        if (this.type === 'sqlite') {
            try {
                // Vérifier si la colonne 'email' existe dans 'users'
                const cols = await this.query("PRAGMA table_info(users)");
                const hasEmail = cols.some(c => c.name === 'email');

                if (!hasEmail) {
                    console.log("🔄 Migration DB : Ajout de la colonne 'email' à la table 'users'...");
                    await this.run("ALTER TABLE users ADD COLUMN email TEXT");
                }
            } catch (e) {
                console.warn("⚠️ Echec de la migration automatique:", e.message);
            }
        }
    }
}

export const db = new Database();

import express from 'express';
import cors from 'cors';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import os from 'os'; // Added for system checks
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

// Nouveaux imports
import { db } from './backend/db.js';
import { emailService } from './backend/email.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3001;
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_opensource_secret_key_change_me_in_prod';
const LOCK_FILE = join(__dirname, 'installed.lock');

// --- INITIALISATION DB ---
db.connect({ path: process.env.DB_PATH || './database.sqlite' });

// --- CONFIGURATION MULTER ---
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
    destination: function (req, file, cb) { cb(null, uploadDir) },
    filename: function (req, file, cb) {
        const safeName = file.originalname.replace(/[^a-zA-Z0-9.]/g, "_");
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        cb(null, uniqueSuffix + '-' + safeName);
    }
});

const upload = multer({ 
    storage: storage,
    limits: { fileSize: 5 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
        const allowedTypes = ['image/jpeg', 'image/png', 'image/gif', 'application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
        if (allowedTypes.includes(file.mimetype) || file.mimetype.startsWith('image/')) {
            cb(null, true);
        } else {
            cb(null, true); 
        }
    }
});

// Middleware
app.use(cors({
    origin: process.env.NODE_ENV === 'production' ? false : 'http://localhost:3000',
    credentials: true 
}));
app.use(express.json({ limit: '10mb' }));
app.use(cookieParser());
app.use('/uploads', express.static(uploadDir));

// --- AUTH MIDDLEWARE ---
const authenticateToken = (req, res, next) => {
    const token = req.cookies.token;
    if (!token) return res.status(401).json({ error: "Non authentifié" });

    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(403).json({ error: "Token invalide" });
        req.user = decoded;
        next();
    });
};

const requireRole = (roles) => {
    return (req, res, next) => {
        if (!req.user || !roles.includes(req.user.role)) {
            return res.status(403).json({ error: "Accès refusé" });
        }
        next();
    };
};

// --- SYSTEM & INSTALLATION ROUTES ---

// Vérification de l'état d'installation
app.get('/api/setup/status', async (req, res) => {
    try {
        const isLocked = fs.existsSync(LOCK_FILE);
        const admin = await db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'");

        // Installed only if lock file exists AND admin exists
        // If DB wiped but lock exists, allow reinstall logic via frontend checks
        const installed = isLocked && admin && admin.count > 0;
        res.json({ installed });
    } catch (err) {
        res.status(500).json({ error: err.message });
    }
});

// System Health Checks for Installer
app.get('/api/setup/checks', (req, res) => {
    const checks = {
        nodeVersion: process.version,
        platform: os.platform(),
        memory: Math.round(os.totalmem() / 1024 / 1024) + " MB",
        writeAccess: false,
        dbConnection: false
    };

    // Check Write Access
    try {
        const testFile = join(__dirname, 'write_test.tmp');
        fs.writeFileSync(testFile, 'test');
        fs.unlinkSync(testFile);
        checks.writeAccess = true;
    } catch (e) {
        checks.writeAccess = false;
    }

    // Check DB Connection (Since db is initialized at start)
    if (db.db) {
        checks.dbConnection = true;
    }

    res.json(checks);
});

// Installation Initiale (One-time)
app.post('/api/setup/install', async (req, res) => {
    // Note: We removed the strict lock check here to allow re-installation over an existing dirty state
    // if the user somehow got into the wizard (e.g. deleted lock file but kept DB).
    // The wizard UI logic normally protects this, but backend should be robust.

    const { username, password, name, schoolName, adminEmail, dbType, envMode } = req.body;
    if (!username || !password || !schoolName) return res.status(400).json({ error: "Champs requis" });

    try {
        // 1. Sauvegarder la configuration
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['site_name', schoolName]);
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['install_date', new Date().toISOString()]);
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['db_type', dbType || 'sqlite']);
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['env_mode', envMode || 'production']);

        // 2. Créer l'administrateur
        const id = `admin-${Date.now()}`;
        const hash = bcrypt.hashSync(password, 10);

        // Vérifier si l'utilisateur existe déjà (pour éviter l'erreur UNIQUE constraint)
        const existingUser = await db.get("SELECT id FROM users WHERE username = ?", [username.trim().toLowerCase()]);

        if (existingUser) {
            // Mise à jour de l'utilisateur existant pour devenir Admin
            await db.run(
                `UPDATE users SET password = ?, name = ?, role = 'ADMIN', email = ?, data = ? WHERE id = ?`, 
                [hash, name || 'Administrateur', adminEmail || '', JSON.stringify({ schoolName }), existingUser.id]
            );
        } else {
            // Création propre
            await db.run(
                `INSERT INTO users (id, username, password, name, role, email, data) VALUES (?, ?, ?, ?, ?, ?, ?)`, 
                [id, username.trim().toLowerCase(), hash, name || 'Administrateur', 'ADMIN', adminEmail || '', JSON.stringify({ schoolName })]
            );
        }

        // 3. Verrouiller l'installation
        fs.writeFileSync(LOCK_FILE, `INSTALLED_ON=${new Date().toISOString()}\nDB=${dbType}\nMODE=${envMode}`);

        // 4. Envoyer email de bienvenue
        if (adminEmail) {
            await emailService.send(
                adminEmail, 
                "Bienvenue sur Tinmel LMS", 
                `Votre instance Tinmel a été installée avec succès.\nURL: ${req.get('host')}\nAdmin: ${username}\nMode: ${envMode}`
            );
        }

        res.json({ success: true });
    } catch (err) {
        console.error("Install Error:", err);
        // Si c'est une erreur de contrainte unique non gérée ci-dessus (ex: conflit d'ID, rare), on renvoie une erreur lisible
        if (err.message && err.message.includes('UNIQUE constraint')) {
             return res.status(400).json({ error: "Conflit de données : Cet utilisateur existe déjà." });
        }
        res.status(500).json({ error: err.message });
    }
});

// --- ROUTES MÉTIER ---

app.post('/api/upload', authenticateToken, upload.single('file'), (req, res) => {
    if (!req.file) return res.status(400).json({ error: 'Aucun fichier uploadé.' });
    res.json({ url: `/uploads/${req.file.filename}`, filename: req.file.filename });
});

app.post('/api/auth/login', async (req, res) => {
    const { username, password } = req.body;
    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    try {
        const user = await db.get("SELECT * FROM users WHERE username = ?", [username.trim().toLowerCase()]);
        if (!user) return res.status(404).json({ error: "Utilisateur introuvable" });

        const isValid = bcrypt.compareSync(password, user.password);
        if (!isValid) return res.status(401).json({ error: "Mot de passe incorrect" });

        const token = jwt.sign({ id: user.id, role: user.role }, JWT_SECRET, { expiresIn: '24h' });

        const extraData = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extraData };
        delete userObj.password;

        if (user.role !== 'ADMIN' && user.role !== 'COORDINATOR') {
            delete userObj.readablePassword; // Sécurité: ne jamais renvoyer le mdp en clair sauf admin
        }
        delete userObj.data;

        res.cookie('token', token, { httpOnly: true, secure: false, sameSite: 'lax', maxAge: 24 * 60 * 60 * 1000 });
        res.json(userObj);
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

