              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ 
                  question: questionText, 
                  answer: studentAnswer, 
                  context: correctAnswerContext 
              })
          });

          if (!response.ok) throw new Error("Erreur grading");

          return await response.json();
      } catch (e) {
