import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, (process as any).cwd(), '');

  // Create an object with process.env.KEY: "value" for string replacement
  // Fix: Explicitly type the accumulator as Record<string, string>
  const processEnvValues = Object.keys(env).reduce<Record<string, string>>((acc, key) => {
    if (key.startsWith('VITE_') || key.startsWith('REACT_APP_') || key === 'NODE_ENV') {
      acc[`process.env.${key}`] = JSON.stringify(env[key]);
    }
    return acc;
  }, {});

  return {
    plugins: [react()],
    build: {
      outDir: 'dist',
      sourcemap: false,
      chunkSizeWarningLimit: 1600,
    },
    server: {
      port: 3000,
      open: true,
      proxy: {
        '/api': {
          target: 'http://localhost:3001',
          changeOrigin: true,
          secure: false
        },
        '/uploads': {
          target: 'http://localhost:3001',
          changeOrigin: true,
          secure: false
        }
      }
    },
    define: {
      // Replace specific process.env.KEY calls
      ...processEnvValues,
      // Safe fallback for libs using process.env
      'process.env': {}
    }
  };
});

