                                    >
                                        <Check className="w-3 h-3"/> {t('markContacted')}
                                    </button>
                                </td>
                            </tr>
                        ))}
                        {pending.length === 0 && <tr><td colSpan={6} className="p-6 text-center text-gray-400">{t('noResults')}</td></tr>}
