                </table>
            </div>

            {contacted.length > 0 && (
                <>
                <h2 className="text-xl font-bold text-gray-700 mt-8 opacity-60">Historique</h2>
                <div className="bg-gray-50 rounded-lg border overflow-hidden opacity-60">
