const GlobalSearchView: React.FC = () => {
    const { t } = useLanguage();
    const [searchTerm, setSearchTerm] = useState('');
    const [users, setUsers] = useState<User[]>([]);
    const [currentPage, setCurrentPage] = useState(1);
    const [totalUsers, setTotalUsers] = useState(0);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const timer = setTimeout(() => {
            fetchUsers(currentPage, searchTerm);
        }, 500); 

        return () => clearTimeout(timer);
    }, [searchTerm, currentPage]);

    const fetchUsers = async (page: number, q: string) => {
        setLoading(true);
        try {
            const res = await ApiService.getUsersPaginated({ page, limit: ITEMS_PER_PAGE, q });
            setUsers(res.data);
            setTotalUsers(res.meta.total);
        } catch (e) {
            console.error("Search failed", e);
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteUser = async (id: string) => {
        if (confirm(t('delete') + '?')) {
            await ApiService.deleteUser(id); 
            fetchUsers(currentPage, searchTerm);
        }
    };

    const handleResetPassword = async (id: string) => {
        const newPass = Math.floor(100000 + Math.random() * 900000).toString();
        await ApiService.updateUser(id, { password: newPass });
        fetchUsers(currentPage, searchTerm);
        alert(`${t('passResetSuccess')} ${newPass}`);
    };

    const totalPages = Math.ceil(totalUsers / ITEMS_PER_PAGE);

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="bg-white p-6 rounded-lg shadow-sm">
                <h2 className="text-xl font-bold mb-4 flex items-center gap-2 text-indigo-700">
