// --- MAIN APP COMPONENT ---

const AppContent: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isInstalled, setIsInstalled] = useState<boolean | null>(null);
  const [loading, setLoading] = useState(true);
  const [autoLaunchQuizId, setAutoLaunchQuizId] = useState<string | null>(null);
  const history = useHistory();
  const location = useLocation();

  useEffect(() => {
      const init = async () => {
          setLoading(true);

          try {
              const installStatus = await ApiService.checkInstallStatus();
              setIsInstalled(installStatus);

              if (!installStatus) {
                  setLoading(false);
                  return; 
              }
          } catch (e) {
              console.warn("Could not check install status", e);
              setIsInstalled(false); 
              setLoading(false);
              return;
          }

          const apiUser = await ApiService.checkSession();
          if (apiUser) {
              setUser(apiUser);
          } else {
              const session = StorageService.getSession();
              if (session) setUser(session);
          }

          const params = new URLSearchParams(window.location.search);
          const qId = params.get('quizId');
          if (qId) setAutoLaunchQuizId(qId);

          setLoading(false);
      };
      init();
  }, []);

  const getDashboardPath = (role: UserRole) => {
      switch(role) {
          case UserRole.ADMIN: return '/admin';
          case UserRole.PROFESSOR: return '/professor';
          case UserRole.STUDENT: return '/student';
          case UserRole.COORDINATOR: return '/coordinator';
          case UserRole.MODERATOR: return '/moderator';
          default: return '/';
      }
  };

  const handleLoginSuccess = (loggedInUser: User) => {
      StorageService.saveSession(loggedInUser);
      setUser(loggedInUser);
      history.push(getDashboardPath(loggedInUser.role));
  };

  const handleLogout = async () => {
      await ApiService.logout();
      StorageService.clearSession();
      setUser(null);
      history.push('/');
  };

  if (loading) {
      return (
          <div className="min-h-screen bg-blue-900 flex items-center justify-center">
              <div className="flex flex-col items-center gap-4">
                  <Loader2 className="w-12 h-12 text-white animate-spin" />
                  <p className="text-blue-200 text-sm font-medium">Initialisation du système...</p>
              </div>
          </div>
      );
  }

  if (isInstalled === false) {
      return <InstallationWizard onInstalled={() => { setIsInstalled(true); window.location.reload(); }} />;
  }

  return (
    <Switch>
        <Route exact path="/">
            {!user ? <LandingPage /> : <Redirect to={getDashboardPath(user.role)} />}
        </Route>

        <Route path="/login/student">
            {!user ? <LoginPage role="STUDENT" onLoginSuccess={handleLoginSuccess} /> : <Redirect to={getDashboardPath(user.role)} />}
        </Route>

        <Route path="/login/staff">
            {!user ? <LoginPage role="STAFF" onLoginSuccess={handleLoginSuccess} /> : <Redirect to={getDashboardPath(user.role)} />}
        </Route>

        <Route path="/tinmelad">
            {!user ? <LoginPage role="ADMIN" onLoginSuccess={handleLoginSuccess} /> : 
            (user.role === UserRole.ADMIN ? <Redirect to="/admin" /> : <Redirect to="/" />)
            }
        </Route>

        <Route path="/admin">
            <AuthGuard user={user} requiredRole={UserRole.ADMIN}><AdminDashboard onLogout={handleLogout} /></AuthGuard>
        </Route>
        <Route path="/professor">
            <AuthGuard user={user} requiredRole={UserRole.PROFESSOR}><ProfessorDashboard user={user!} onLogout={handleLogout} /></AuthGuard>
        </Route>
        <Route path="/student">
            <AuthGuard user={user} requiredRole={UserRole.STUDENT}><StudentDashboard user={user!} onLogout={handleLogout} autoLaunchQuizId={autoLaunchQuizId} /></AuthGuard>
        </Route>
        <Route path="/coordinator">
            <AuthGuard user={user} requiredRole={UserRole.COORDINATOR}><CoordinatorDashboard user={user!} onLogout={handleLogout} /></AuthGuard>
        </Route>
        <Route path="/moderator">
            <AuthGuard user={user} requiredRole={UserRole.MODERATOR}><ModeratorDashboard user={user!} onLogout={handleLogout} /></AuthGuard>
        </Route>

        <Redirect to="/" />
    </Switch>
  );
};

