const ITEMS_PER_PAGE = 10;

// --- VIEW: USER MANAGEMENT (LITE) ---
const UsersManagementView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [users, setUsers] = useState<User[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [roleFilter, setRoleFilter] = useState<string>('');
    const [currentPage, setCurrentPage] = useState(1);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        loadUsers();
    }, []);

    const loadUsers = async () => {
        setLoading(true);
        // Moderators can see Professors and Students, usually globally or scoped if logic added later
        const allUsers = await ApiService.getUsers(); 
        // Security: Filter out Admins and other Moderators to prevent privilege escalation attacks
        const manageableUsers = allUsers.filter(u => u.role === UserRole.PROFESSOR || u.role === UserRole.STUDENT);
        setUsers(manageableUsers);
        setLoading(false);
    };

    const handleResetPassword = async (targetId: string, targetName: string) => {
        if (confirm(`Réinitialiser le mot de passe pour ${targetName} ?`)) {
            const newPass = Math.floor(100000 + Math.random() * 900000).toString();
            await ApiService.updateUser(targetId, { password: newPass });
            alert(`Nouveau mot de passe pour ${targetName} : ${newPass}\n\nNotez-le, il ne sera plus affiché.`);
            loadUsers();
        }
    };

    // Filter Logic
    const filtered = users.filter(u => {
        const matchesSearch = u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                              u.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
                              (u.school || '').toLowerCase().includes(searchTerm.toLowerCase());
        const matchesRole = roleFilter ? u.role === roleFilter : true;
        return matchesSearch && matchesRole;
    });

    // Pagination
    const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
    const paginated = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <UserPlus className="w-5 h-5 text-blue-600"/> {t('staffList')} / {t('studentsList')}
                </h2>

                <div className="flex flex-col md:flex-row gap-4 mb-4">
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 rtl:right-3 rtl:left-auto"/>
