                    {t('schoolBreakdown')}
                </div>
                <table className="w-full text-sm text-start">
                    <thead className="bg-gray-50 border-b">
                        <tr>
                            <th className="p-4 text-start">{t('school')}</th>
                            <th className="p-4 text-start">{t('city')}</th>
