                            <th className="p-4 text-center">{t('totalLessons')}</th>
                        </tr>
                    </thead>
                    <tbody>
                        {schoolStatsArray.map((s, idx) => (
                            <tr key={idx} className="border-b last:border-0 hover:bg-gray-50">
                                <td className="p-4 font-bold text-gray-800">{s.name}</td>
