import React, { useState, useEffect } from 'react';
import { Routes, Route, Link, useLocation, Navigate, useNavigate } from 'react-router-dom';
import { User, UserRole, Announcement, Message } from '../../types';
import { StorageService } from '../../services/storageService';
import { ApiService } from '../../services/apiService';
import { LogOut, Trash, UserPlus, Megaphone, Send, Info, X, MessageCircle, Shield, Search, Filter, ChevronLeft, ChevronRight, FileDown, RefreshCcw, Lock, CheckCircle } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';
import * as XLSX from 'xlsx';

interface Props {
  user: User;
  onLogout: () => void;
}

const ITEMS_PER_PAGE = 10;

// --- VIEW: USER MANAGEMENT (LITE) ---
const UsersManagementView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [users, setUsers] = useState<User[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [roleFilter, setRoleFilter] = useState<string>('');
    const [currentPage, setCurrentPage] = useState(1);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        loadUsers();
    }, []);

    const loadUsers = async () => {
        setLoading(true);
        // Moderators can see Professors and Students, usually globally or scoped if logic added later
        const allUsers = await ApiService.getUsers(); 
        // Security: Filter out Admins and other Moderators to prevent privilege escalation attacks
        const manageableUsers = allUsers.filter(u => u.role === UserRole.PROFESSOR || u.role === UserRole.STUDENT);
        setUsers(manageableUsers);
        setLoading(false);
    };

    const handleResetPassword = async (targetId: string, targetName: string) => {
        if (confirm(`Réinitialiser le mot de passe pour ${targetName} ?`)) {
            const newPass = Math.floor(100000 + Math.random() * 900000).toString();
            await ApiService.updateUser(targetId, { password: newPass });
            alert(`Nouveau mot de passe pour ${targetName} : ${newPass}\n\nNotez-le, il ne sera plus affiché.`);
            loadUsers();
        }
    };

    // Filter Logic
    const filtered = users.filter(u => {
        const matchesSearch = u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                              u.username.toLowerCase().includes(searchTerm.toLowerCase()) ||
                              (u.school || '').toLowerCase().includes(searchTerm.toLowerCase());
        const matchesRole = roleFilter ? u.role === roleFilter : true;
        return matchesSearch && matchesRole;
    });

    // Pagination
    const totalPages = Math.ceil(filtered.length / ITEMS_PER_PAGE);
    const paginated = filtered.slice((currentPage - 1) * ITEMS_PER_PAGE, currentPage * ITEMS_PER_PAGE);

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <UserPlus className="w-5 h-5 text-blue-600"/> {t('staffList')} / {t('studentsList')}
                </h2>

                <div className="flex flex-col md:flex-row gap-4 mb-4">
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-400 rtl:right-3 rtl:left-auto"/>
                        <input 
                            className="w-full pl-9 pr-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-blue-500 rtl:pr-9 rtl:pl-3" 
                            placeholder={t('globalSearchPlaceholder')} 
                            value={searchTerm} 
                            onChange={e => {setSearchTerm(e.target.value); setCurrentPage(1)}} 
                        />
                    </div>
                    <select 
                        className="border rounded-lg px-3 py-2 text-sm bg-gray-50"
                        value={roleFilter}
                        onChange={e => setRoleFilter(e.target.value)}
                    >
                        <option value="">Tous les rôles</option>
                        <option value={UserRole.PROFESSOR}>{t('professor')}</option>
                        <option value={UserRole.STUDENT}>{t('student')}</option>
                    </select>
                    <button onClick={loadUsers} className="p-2 bg-gray-100 rounded-lg hover:bg-gray-200" title="Actualiser">
                        <RefreshCcw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`}/>
                    </button>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 border-b text-gray-600 uppercase text-xs">
                            <tr>
                                <th className="p-3">Nom</th>
                                <th className="p-3">Rôle</th>
                                <th className="p-3">Identifiant</th>
                                <th className="p-3">École</th>
                                <th className="p-3 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {paginated.map(u => (
                                <tr key={u.id} className="border-b last:border-0 hover:bg-gray-50">
                                    <td className="p-3 font-medium text-gray-900">{u.name}</td>
                                    <td className="p-3">
                                        <span className={`px-2 py-1 rounded text-xs font-bold ${u.role === UserRole.PROFESSOR ? 'bg-blue-100 text-blue-700' : 'bg-green-100 text-green-700'}`}>
                                            {t(u.role.toLowerCase())}
                                        </span>
                                    </td>
                                    <td className="p-3 font-mono text-gray-500">{u.username}</td>
                                    <td className="p-3 text-gray-500">{u.school || '-'}</td>
                                    <td className="p-3 text-right">
                                        <button 
                                            onClick={() => handleResetPassword(u.id, u.name)}
                                            className="text-orange-600 hover:bg-orange-50 px-3 py-1 rounded border border-orange-200 text-xs font-medium transition-colors flex items-center gap-1 ml-auto"
                                        >
                                            <Lock className="w-3 h-3"/> {t('resetPass')}
                                        </button>
                                    </td>
                                </tr>
                            ))}
                            {paginated.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="p-8 text-center text-gray-400 italic">{t('noResults')}</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {totalPages > 1 && (
                    <div className="flex justify-center gap-2 mt-4 pt-4 border-t">
                        <button disabled={currentPage === 1} onClick={() => setCurrentPage(p => p - 1)} className="p-2 border rounded disabled:opacity-50 hover:bg-gray-50"><ChevronLeft className="w-4 h-4 rtl:flip"/></button>
                        <span className="py-2 px-4 text-sm text-gray-600">Page {currentPage} / {totalPages}</span>
                        <button disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => p + 1)} className="p-2 border rounded disabled:opacity-50 hover:bg-gray-50"><ChevronRight className="w-4 h-4 rtl:flip"/></button>
                    </div>
                )}
            </div>
        </div>
    );
};

// --- VIEW: COMMUNICATION ---
const CommunicationView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [history, setHistory] = useState<Announcement[]>([]);

    useEffect(() => {
        setHistory(StorageService.getAnnouncements());
    }, []);

    const handleBroadcast = () => {
        if(!title.trim() || !content.trim()) return;
        const ann: Announcement = { 
            id: `ann-${Date.now()}`, 
            title, 
            content, 
            date: new Date().toISOString(), 
            author: user.name + ' (Modération)'
        };
        StorageService.saveAnnouncement(ann);
        setHistory([ann, ...history]);
        setTitle(''); setContent('');
        alert(t('announceSent'));
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 animate-fade-in">
            {/* Formulaire */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
                <h2 className="text-lg font-bold text-gray-800 mb-6 flex items-center gap-2">
                    <Megaphone className="w-5 h-5 text-purple-600"/> {t('broadcastNews')}
                </h2>
                <div className="space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t('announceTitle')}</label>
                        <input 
                            className="w-full border rounded-lg p-3 focus:ring-2 focus:ring-purple-500 outline-none transition" 
                            value={title} 
                            onChange={e => setTitle(e.target.value)}
                            placeholder="Ex: Fermeture pour jours fériés" 
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">{t('announceContent')}</label>
                        <textarea 
                            className="w-full border rounded-lg p-3 h-32 focus:ring-2 focus:ring-purple-500 outline-none transition" 
                            value={content} 
                            onChange={e => setContent(e.target.value)} 
                            placeholder="Message à afficher sur le tableau de bord de tous les utilisateurs..."
                        />
                    </div>
                    <button 
                        onClick={handleBroadcast} 
                        className="w-full bg-purple-600 text-white py-3 rounded-lg hover:bg-purple-700 flex items-center justify-center gap-2 font-bold shadow-md transition-transform active:scale-95"
                    >
                        <Send className="w-4 h-4 rtl:flip"/> {t('publish')}
                    </button>
                </div>
            </div>

            {/* Historique */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <Info className="w-5 h-5 text-gray-500"/> Historique des annonces
                </h2>
                <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                    {history.length === 0 && <p className="text-gray-400 text-center py-10 italic">Aucune annonce publiée.</p>}
                    {history.map(ann => (
                        <div key={ann.id} className="p-4 bg-gray-50 rounded-lg border border-gray-100 hover:bg-gray-100 transition-colors">
                            <div className="flex justify-between items-start mb-2">
                                <h3 className="font-bold text-gray-900">{ann.title}</h3>
                                <span className="text-xs text-gray-500 bg-white px-2 py-1 rounded border">
                                    {new Date(ann.date).toLocaleDateString()}
                                </span>
                            </div>
                            <p className="text-sm text-gray-600 line-clamp-3">{ann.content}</p>
                            <p className="text-xs text-purple-600 mt-2 font-medium">Par: {ann.author}</p>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

