import express from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { db } from '../db.js';

const router = express.Router();
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_secure_key_' + Date.now();

// Middleware local pour ce routeur si besoin, sinon utiliser celui importé dans server.js
// Pour simplifier, nous réutilisons la logique mais idéalement les middlewares devraient être dans un dossier à part.

router.post('/login', async (req, res) => {
    const { username, password } = req.body;
    if (!username || !password) return res.status(400).json({ error: "Champs requis" });

    try {
        const user = await db.get("SELECT * FROM users WHERE username = ?", [username.trim().toLowerCase()]);
        if (!user) return res.status(404).json({ error: "Utilisateur introuvable" });

        const isValid = bcrypt.compareSync(password, user.password);
        if (!isValid) return res.status(401).json({ error: "Mot de passe incorrect" });

        const token = jwt.sign({ id: user.id, role: user.role }, JWT_SECRET, { expiresIn: '24h' });

        const extraData = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extraData };
        delete userObj.password;

        if (user.role !== 'ADMIN' && user.role !== 'COORDINATOR') {
            delete userObj.readablePassword; 
        }
        delete userObj.data;

        res.cookie('token', token, { 
            httpOnly: true, 
            secure: process.env.NODE_ENV === 'production', 
            sameSite: 'lax', 
            maxAge: 24 * 60 * 60 * 1000 
        });
        res.json(userObj);
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

router.post('/logout', (req, res) => {
    res.clearCookie('token');
    res.json({ success: true });
});

router.get('/me', async (req, res) => {
    // Note: req.user est injecté par le middleware authenticateToken dans server.js
    // Si ce routeur est monté après le middleware, cela fonctionne.
    if (!req.user) return res.status(401).json({ error: "Non authentifié" });

    try {
        const user = await db.get("SELECT * FROM users WHERE id = ?", [req.user.id]);
        if (!user) return res.status(404).json({ error: "User not found" });

        const extraData = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extraData };
        delete userObj.password;
        if (user.role !== 'ADMIN' && user.role !== 'COORDINATOR') delete userObj.readablePassword;
        delete userObj.data;
        res.json(userObj);
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

