import express from 'express';
import { GoogleGenAI, Type } from "@google/genai";

const router = express.Router();
const API_KEY = process.env.API_KEY || process.env.GEMINI_API_KEY;

// Middleware de vérification de rôle devrait être passé depuis server.js ou réimporté
// Pour l'instant, on assume que les routes sont protégées au niveau du montage dans server.js

router.post('/generate-quiz', async (req, res) => {
    // Vérification basique de rôle (double sécurité)
    if (!req.user || (req.user.role !== 'PROFESSOR' && req.user.role !== 'ADMIN')) {
        return res.status(403).json({ error: "Accès réservé aux professeurs" });
    }

    const { topic, context, count, language } = req.body;

    if (!API_KEY) return res.status(500).json({ error: "Clé API Gemini non configurée serveur." });

    try {
        const ai = new GoogleGenAI({ apiKey: API_KEY });
        const langName = language === 'ar' ? 'Arabe' : 'Français';
        const booleanInstructions = language === 'ar' ? 'Pour BOOLEAN, la réponse doit être "Vrai" ou "Faux" (je traduirai coté client).' : 'Pour BOOLEAN, la réponse doit être "Vrai" ou "Faux".';

        let contentPrompt = "";
        if (context) {
            contentPrompt = `Basé sur le texte suivant :\n"${context.substring(0, 5000)}"\n`;
        } else {
            contentPrompt = `Sur le sujet : "${topic}"\n`;
        }

        const prompt = `
          Génère un quiz de ${count || 5} questions.
          ${contentPrompt}
          Le quiz doit être OBLIGATOIREMENT en ${langName}.

          Types de questions autorisés (Mélange-les) : 
          1. Choix Multiples (MCQ) : 4 options.
          2. Vrai/Faux (BOOLEAN) : ${booleanInstructions}
          3. Réponse Courte (SHORT_ANSWER).
          4. Appariement (MATCHING) : 4 paires.
          5. Question Ouverte (ESSAY).
          6. Texte à trous (FILL_IN_THE_BLANK).

          Format JSON Strict.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            text: { type: Type.STRING },
                            type: { 
                                type: Type.STRING, 
                                enum: ['MCQ', 'BOOLEAN', 'SHORT_ANSWER', 'MATCHING', 'ESSAY', 'FILL_IN_THE_BLANK'] 
                            },
                            points: { type: Type.NUMBER },
                            options: { type: Type.ARRAY, items: { type: Type.STRING } },
                            correctAnswer: { type: Type.STRING },
                            matchingPairs: { 
                                type: Type.ARRAY, 
                                items: { 
                                    type: Type.OBJECT, 
                                    properties: { left: { type: Type.STRING }, right: { type: Type.STRING } }
                                } 
                            },
                            explanation: { type: Type.STRING }
                        },
                        required: ["text", "type", "points"]
                    }
                }
            }
        });

        res.json({ questions: JSON.parse(response.text) });
    } catch (e) {
        console.error("AI Error:", e);
        res.status(500).json({ error: "Erreur IA: " + e.message });
    }
});

