    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        const foundUser = await ApiService.login(username, password);
        const localUser = !foundUser ? StorageService.login(username, password) : null;
        const finalUser = foundUser || localUser;

        if (finalUser) {
            // SECURITY CHECK: Role Segregation
            // 1. Student Portal Check
            if (role === 'STUDENT' && finalUser.role !== UserRole.STUDENT) {
                setError(t('invalidCreds'));
                return;
            }

            // 2. Staff Portal Check (Strict: No Admins, No Students)
            if (role === 'STAFF') {
                const allowedStaffRoles = [UserRole.PROFESSOR, UserRole.COORDINATOR, UserRole.MODERATOR];
                if (!allowedStaffRoles.includes(finalUser.role)) {
                    if (finalUser.role === UserRole.ADMIN) {
                        setError("Administration : Veuillez utiliser le portail sécurisé /tinmelad");
                    } else {
                        setError(t('accessDenied'));
                    }
                    return;
                }
            }

            // 3. Admin Portal Check
            if (role === 'ADMIN' && finalUser.role !== UserRole.ADMIN) {
                 setError("Accès réservé aux Administrateurs.");
                 return;
            }

            onLoginSuccess(finalUser);
        } else {
            setError(t('invalidCreds'));
        }
