import express from 'express';
import cors from 'cors';
import bcrypt from 'bcryptjs';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import os from 'os';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { rateLimit } from 'express-rate-limit';
import helmet from 'helmet';
import jwt from 'jsonwebtoken';

// Imports internes
import { db } from './backend/db.js';
import { emailService } from './backend/email.js';

// Routes Import
import authRoutes from './backend/routes/auth.js';
import aiRoutes from './backend/routes/ai.js';
import userRoutes from './backend/routes/users.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3001;
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_secure_key_' + Date.now();
const LOCK_FILE = join(__dirname, 'installed.lock');

// --- SÉCURITÉ & CONFIGURATION ---

const limiter = rateLimit({
	windowMs: 15 * 60 * 1000, 
	limit: 300, 
	standardHeaders: 'draft-7',
	legacyHeaders: false,
    message: { error: "Trop de requêtes." }
});

const authLimiter = rateLimit({
    windowMs: 60 * 60 * 1000,
    limit: 20,
    message: { error: "Trop de tentatives de connexion." }
});

app.use(helmet({ contentSecurityPolicy: false, crossOriginEmbedderPolicy: false }));
app.use(cors({ origin: process.env.NODE_ENV === 'production' ? false : 'http://localhost:3000', credentials: true }));
app.use(express.json({ limit: '10mb' }));
app.use(cookieParser());

// Initialisation DB
db.connect({ path: process.env.DB_PATH || './database.sqlite' });

// Uploads Config
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) fs.mkdirSync(uploadDir, { recursive: true });

const storage = multer.diskStorage({
    destination: (req, file, cb) => cb(null, uploadDir),
    filename: (req, file, cb) => {
        const safeName = file.originalname.replace(/[^a-zA-Z0-9.]/g, "_");
        cb(null, Date.now() + '-' + Math.round(Math.random() * 1E9) + '-' + safeName);
    }
});
const upload = multer({ 
    storage, limits: { fileSize: 50 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
        if (file.mimetype.match(/(image|audio|video|application\/pdf|application\/msword)/)) cb(null, true);
        else cb(null, true);
    }
});

app.use('/uploads', express.static(uploadDir));
app.use('/api/', limiter); 

// --- MIDDLEWARES AUTH ---
const authenticateToken = (req, res, next) => {
    const token = req.cookies.token;
    if (!token) return res.status(401).json({ error: "Non authentifié" });
    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(403).json({ error: "Token invalide" });
        req.user = decoded;
        next();
    });
};

// --- ROUTES ---

// 1. Auth & Users
app.use('/api/auth', authRoutes); // Auth utilise ses propres middlewares si besoin, ou on peut wrapper
app.use('/api/users', authenticateToken, userRoutes);

// 2. AI
app.use('/api/ai', authenticateToken, aiRoutes);

// 3. System & Install (Resté ici pour l'instant car très spécifique au bootstrap)
app.get('/api/setup/status', async (req, res) => {
    try {
        const isLocked = fs.existsSync(LOCK_FILE);
        const admin = await db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'");
        res.json({ installed: isLocked && admin && admin.count > 0 });
    } catch (err) { res.status(500).json({ error: err.message }); }
});

app.get('/api/setup/checks', (req, res) => {
    const checks = { nodeVersion: process.version, platform: os.platform(), memory: Math.round(os.totalmem() / 1024 / 1024) + " MB", writeAccess: false, dbConnection: !!db.db };
    try { fs.writeFileSync(join(__dirname, 'write_test.tmp'), 'test'); fs.unlinkSync(join(__dirname, 'write_test.tmp')); checks.writeAccess = true; } catch (e) {}
    res.json(checks);
});

app.post('/api/setup/install', async (req, res) => {
    const { username, password, name, schoolName, adminEmail, dbType, envMode } = req.body;
    try {
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['site_name', schoolName]);
        const id = `admin-${Date.now()}`;
        const hash = bcrypt.hashSync(password, 10);
        await db.run(`INSERT INTO users (id, username, password, name, role, email, data) VALUES (?, ?, ?, ?, 'ADMIN', ?, ?)`, [id, username.trim().toLowerCase(), hash, name || 'Administrateur', adminEmail || '', JSON.stringify({ schoolName })]);
        fs.writeFileSync(LOCK_FILE, `INSTALLED_ON=${new Date().toISOString()}`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
});

// 4. File Upload
app.post('/api/upload', authenticateToken, upload.single('file'), (req, res) => {
    if (!req.file) return res.status(400).json({ error: "No file uploaded" });
    res.json({ url: `/uploads/${req.file.filename}` });
});

// 5. Quiz Result (Manque dans les modules précédents, laissé ici pour l'instant)
app.post('/api/quiz/submit', authenticateToken, async (req, res) => {
    const { quizId, studentId, studentName, answers, timeSpent, essayScores, score, maxScore } = req.body;
    try {
        const result = { id: `res-${Date.now()}`, quizId, studentId, studentName, answers, timeSpent, score: score || 0, maxScore: maxScore || 0, submittedAt: new Date().toISOString(), essayScores };
        await db.run(`INSERT INTO results (id, quizId, studentId, score, submittedAt, data) VALUES (?, ?, ?, ?, ?, ?)`, [result.id, quizId, studentId, result.score, result.submittedAt, JSON.stringify(result)]);
        res.json(result);
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// --- STATIC SERVING ---
const distPath = join(__dirname, 'dist');
if (fs.existsSync(distPath)) {
    app.use(express.static(distPath));
    app.get('*', (req, res) => { if (!req.path.startsWith('/api')) res.sendFile(join(distPath, 'index.html')); });
} else {
    // Mode DEV : Indication claire
    app.get('/', (req, res) => {
        res.send(`
            <h1>⚠️ Mauvais Port</h1>
            <p>Vous êtes sur le serveur API (Port ${PORT}).</p>
            <p>Accédez à l'application via le port Frontend : <a href="http://localhost:3000">http://localhost:3000</a></p>
        `);
    });
}

app.listen(PORT, () => console.log(`🚀 Serveur Tinmel (Modularisé) sur le port ${PORT}`));

