const HeaderBackground = () => {
    // ... (Même code visuel que précédemment, conservé pour l'esthétique)
    const elements = useMemo(() => {
        const items = [];
        const chars = ['ا', 'ب', 'Tinmel', 'Education', '∑', '∫', 'π', 'A', 'B'];
        for (let i = 0; i < 20; i++) {
            items.push({
                char: chars[Math.floor(Math.random() * chars.length)],
                top: Math.random() * 100,
                left: Math.random() * 100,
                size: Math.random() * 2 + 1,
                duration: Math.random() * 30 + 20,
                delay: Math.random() * 20,
                initialRotate: Math.random() * 360,
                opacity: Math.random() * 0.15 + 0.05,
                font: Math.random() > 0.5 ? 'Amiri' : 'sans-serif' 
            });
        }
        return items;
    }, []);

    return (
        <div className="absolute inset-0 overflow-hidden pointer-events-none select-none">
            {elements.map((el, i) => (
                <div key={i} style={{
                    position: 'absolute',
                    top: `${el.top}%`,
                    left: `${el.left}%`,
                    fontSize: `${el.size}rem`,
                    color: `rgba(37, 99, 235, ${el.opacity})`,
                    transform: `rotate(${el.initialRotate}deg)`
                }}>{el.char}</div>
            ))}
        </div>
    );
};

