const QuizzesView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [quizzes, setQuizzes] = useState<Quiz[]>([]);
    const [isCreating, setIsCreating] = useState(false);
    const [availableClasses, setAvailableClasses] = useState<string[]>([]);

    useEffect(() => {
        setQuizzes(StorageService.getQuizzesByProf(user.id));
        // Retrieve classes from School Structure or user assignments
        const struct = StorageService.getSchoolStructure(user.school || '', user.city || '');
        setAvailableClasses(struct?.classes || user.assignedSections || []);
    }, [user, isCreating]);

    const handleDelete = (id: string) => {
        if (confirm(t('delete') + '?')) {
            const newQ = quizzes.filter(q => q.id !== id);
            setQuizzes(newQ);
            localStorage.setItem('quizmaster_quizzes', JSON.stringify(newQ)); // Direct update for simplicity in POC
        }
    };

    if (isCreating) {
        return (
            <QuizBuilder 
                profId={user.id} 
                onSave={(q) => { StorageService.saveQuiz(q); setIsCreating(false); }} 
                onCancel={() => setIsCreating(false)} 
                availableClasses={availableClasses}
            />
        );
    }

    return (
        <div className="space-y-6 animate-fade-in">
            <div className="flex justify-between items-center">
                <h2 className="text-xl font-bold flex items-center gap-2"><FileText className="w-6 h-6 text-blue-600"/> {t('myQuizzes')}</h2>
                <button onClick={() => setIsCreating(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-700">
                    <Plus className="w-4 h-4"/> {t('createQuiz')}
                </button>
            </div>
            <div className="grid gap-4">
                {quizzes.map(q => (
                    <div key={q.id} className="bg-white p-4 rounded-xl shadow-sm border flex justify-between items-center hover:shadow-md transition">
                        <div>
                            <h3 className="font-bold text-gray-800 text-lg">{q.title}</h3>
                            <div className="flex gap-2 mt-1">
                                <span className={`text-xs px-2 py-0.5 rounded font-bold ${q.status === 'PUBLISHED' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>{t(q.status.toLowerCase())}</span>
                                <span className="text-xs text-gray-500 bg-gray-50 px-2 py-0.5 rounded border">{q.questions.length} questions</span>
                                <span className="text-xs text-blue-500 bg-blue-50 px-2 py-0.5 rounded border">{q.assignedClasses.join(', ') || 'Aucune classe'}</span>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            <button onClick={() => handleDelete(q.id)} className="p-2 text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-5 h-5"/></button>
                        </div>
                    </div>
                ))}
                {quizzes.length === 0 && <p className="text-center text-gray-500 py-10">{t('noResults')}</p>}
            </div>
        </div>
    );
};

