const StudentsManagementView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [students, setStudents] = useState<User[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ name: '', username: '', password: '', class: '' });
    const [structure, setStructure] = useState<SchoolStructure | null>(null);

    const load = () => {
        const all = StorageService.getUsers();
        setStudents(all.filter(u => u.role === UserRole.STUDENT && u.school === user.school && u.city === user.city));
    };

    useEffect(() => { 
        load();
        if(user.school && user.city) setStructure(StorageService.getSchoolStructure(user.school, user.city));
    }, [user]);

    const createStudent = async (e: React.FormEvent) => {
        e.preventDefault();
        const newU: User = {
            id: `stu-${Date.now()}`,
            name: form.name,
            username: form.username,
            password: form.password,
            role: UserRole.STUDENT,
            school: user.school,
            city: user.city,
            enrolledClasses: [form.class],
            class: form.class, // Legacy
            accountType: 'ESTABLISHMENT'
        };
        await ApiService.createUser(newU);
        setShowForm(false);
        setForm({ name: '', username: '', password: '', class: '' });
        load();
    };

    return (
        <div className="space-y-6 animate-fade-in">
