                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 border-b">
                        <tr><th className="p-4">Nom</th><th className="p-4">ID</th><th className="p-4">Classe</th><th className="p-4 text-right">Actions</th></tr>
                    </thead>
                    <tbody>
                        {students.map(p => (
                            <tr key={p.id} className="border-b hover:bg-gray-50">
                                <td className="p-4 font-bold">{p.name}</td>
                                <td className="p-4 font-mono text-gray-500">{p.username}</td>
                                <td className="p-4"><span className="bg-green-100 text-green-800 px-2 py-1 rounded text-xs">{p.enrolledClasses?.join(', ')}</span></td>
