const StructureView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [structure, setStructure] = useState<SchoolStructure | null>(null);
    const [newClass, setNewClass] = useState('');

    useEffect(() => {
        if(user.school && user.city) {
            const s = StorageService.getSchoolStructure(user.school, user.city);
            if(s) setStructure(s);
            else {
                // Init if empty
                const newS = { id: `struct-${Date.now()}`, school: user.school, city: user.city, classes: [] };
                StorageService.saveSchoolStructure(newS);
                setStructure(newS);
            }
        }
    }, [user]);

    const addClass = () => {
        if(newClass && structure) {
            if(structure.classes.includes(newClass)) return alert(t('classExists'));
            const updated = { ...structure, classes: [...structure.classes, newClass] };
            StorageService.saveSchoolStructure(updated);
            setStructure(updated);
            setNewClass('');
        }
    };

    return (
        <div className="space-y-6 animate-fade-in">
            <h2 className="text-xl font-bold flex items-center gap-2"><Building className="w-6 h-6 text-indigo-600"/> {t('manageStructure')}</h2>
            <div className="bg-white p-6 rounded-xl shadow-sm border">
                <div className="flex gap-2 mb-6">
                    <input 
                        className="border p-2 rounded flex-1" 
                        placeholder="Nom de la classe (ex: CP, CE1...)" 
                        value={newClass}
                        onChange={e => setNewClass(e.target.value)}
                    />
                    <button onClick={addClass} className="bg-indigo-600 text-white px-4 py-2 rounded font-bold">{t('addClassToStructure')}</button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {structure?.classes.map(c => (
                        <div key={c} className="bg-gray-50 p-4 rounded-lg border text-center font-bold text-gray-700 flex justify-between items-center group">
                            {c}
                            <button 
                                onClick={() => {
                                    const updated = { ...structure, classes: structure.classes.filter(x => x !== c) };
                                    StorageService.saveSchoolStructure(updated);
                                    setStructure(updated);
                                }}
                                className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100"
                            >
                                <X className="w-4 h-4"/>
                            </button>
                        </div>
                    ))}
                    {structure?.classes.length === 0 && <p className="col-span-full text-center text-gray-400">Aucune classe définie.</p>}
                </div>
            </div>
        </div>
    );
};

const StaffManagementView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [profs, setProfs] = useState<User[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ name: '', username: '', password: '' });

    // Classes assignment modal
    const [selectedProf, setSelectedProf] = useState<User | null>(null);
    const [structure, setStructure] = useState<SchoolStructure | null>(null);

    const load = () => {
        const all = StorageService.getUsers();
        setProfs(all.filter(u => u.role === UserRole.PROFESSOR && u.school === user.school && u.city === user.city));
    };

    useEffect(() => { 
        load();
        if(user.school && user.city) setStructure(StorageService.getSchoolStructure(user.school, user.city) || null);
    }, [user]);

    const createProf = async (e: React.FormEvent) => {
        e.preventDefault();
        const newU: User = {
            id: `prof-${Date.now()}`,
            name: form.name,
            username: form.username,
            password: form.password,
            role: UserRole.PROFESSOR,
            school: user.school,
            city: user.city,
            accountType: 'ESTABLISHMENT'
        };
        await ApiService.createUser(newU);
        setShowForm(false);
        setForm({ name: '', username: '', password: '' });
        load();
    };

    const toggleClassAssignment = (cls: string) => {
        if (!selectedProf) return;
        const current = selectedProf.assignedSections || [];
        let updated: string[];
        if (current.includes(cls)) updated = current.filter(c => c !== cls);
        else updated = [...current, cls];

        const newProf = { ...selectedProf, assignedSections: updated };
        ApiService.updateUser(newProf.id, { assignedSections: updated });
        setSelectedProf(newProf);
        // Update list locally
        setProfs(profs.map(p => p.id === newProf.id ? newProf : p));
    };

    return (
        <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center">
                <h2 className="text-xl font-bold flex items-center gap-2"><Users className="w-6 h-6 text-blue-600"/> {t('manageStaff')}</h2>
                <button onClick={() => setShowForm(!showForm)} className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-700">
                    <Plus className="w-4 h-4"/> Ajouter Professeur
                </button>
            </div>

            {showForm && (
                <div className="bg-white p-6 rounded-xl shadow border border-blue-100 mb-6">
                    <form onSubmit={createProf} className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <input className="border p-2 rounded" placeholder="Nom" required value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
                        <input className="border p-2 rounded" placeholder="Identifiant" required value={form.username} onChange={e => setForm({...form, username: e.target.value})} />
                        <input className="border p-2 rounded" placeholder="Mot de passe" required value={form.password} onChange={e => setForm({...form, password: e.target.value})} />
                        <button className="bg-green-600 text-white font-bold rounded">Sauvegarder</button>
                    </form>
                </div>
            )}

            {/* Class Assignment Modal */}
            {selectedProf && (
                <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4 animate-fade-in">
                    <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden">
                        <div className="p-4 border-b bg-gray-50 flex justify-between items-center">
                            <h3 className="font-bold">Classes pour {selectedProf.name}</h3>
                            <button onClick={() => setSelectedProf(null)}><X className="w-5 h-5"/></button>
                        </div>
                        <div className="p-4 grid grid-cols-2 gap-2 max-h-60 overflow-y-auto">
                            {structure?.classes.map(cls => (
                                <button 
                                    key={cls}
                                    onClick={() => toggleClassAssignment(cls)}
                                    className={`p-2 rounded border font-medium ${selectedProf.assignedSections?.includes(cls) ? 'bg-blue-100 border-blue-300 text-blue-800' : 'bg-white hover:bg-gray-50 text-gray-600'}`}
                                >
                                    {cls}
                                </button>
                            ))}
                            {(!structure || structure.classes.length === 0) && <p className="col-span-2 text-center text-gray-400">Aucune classe définie dans la structure.</p>}
                        </div>
                        <div className="p-4 border-t bg-gray-50 text-right">
                            <button onClick={() => setSelectedProf(null)} className="bg-blue-600 text-white px-4 py-2 rounded font-bold">Fermer</button>
                        </div>
                    </div>
                </div>
            )}

            <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-50 border-b">
                        <tr><th className="p-4">Nom</th><th className="p-4">ID</th><th className="p-4">Classes Attribuées</th><th className="p-4 text-right">Actions</th></tr>
                    </thead>
                    <tbody>
                        {profs.map(p => (
                            <tr key={p.id} className="border-b hover:bg-gray-50">
                                <td className="p-4 font-bold">{p.name}</td>
                                <td className="p-4 font-mono text-gray-500">{p.username}</td>
                                <td className="p-4">
                                    <div className="flex flex-wrap gap-1">
                                        {p.assignedSections?.map(c => <span key={c} className="bg-gray-100 px-1.5 rounded text-xs">{c}</span>)}
                                        {(!p.assignedSections || p.assignedSections.length === 0) && <span className="text-gray-400 italic text-xs">Aucune</span>}
                                    </div>
                                </td>
                                <td className="p-4 text-right flex justify-end gap-2">
                                    <button onClick={() => setSelectedProf(p)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded border border-blue-200 text-xs">Gérer Classes</button>
                                    <button onClick={() => {if(confirm('Supprimer?')) ApiService.deleteUser(p.id).then(load)}} className="text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4"/></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

