                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-l-4 border-l-green-500">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-gray-500 text-xs font-bold uppercase">{t('totalStudents')}</p>
                            <h3 className="text-3xl font-black text-gray-800">{students.length}</h3>
                        </div>
                        <GraduationCap className="text-green-200 w-8 h-8"/>
                    </div>
                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-l-4 border-l-purple-500">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-gray-500 text-xs font-bold uppercase">{t('totalQuizzes')}</p>
                            <h3 className="text-3xl font-black text-gray-800">{quizzesCount}</h3>
                        </div>
                        <FileText className="text-purple-200 w-8 h-8"/>
                    </div>
                </div>
                 <div className="bg-white p-6 rounded-xl shadow-sm border border-l-4 border-l-orange-500">
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-gray-500 text-xs font-bold uppercase">{t('totalLessons')}</p>
                            <h3 className="text-3xl font-black text-gray-800">{lessonsCount}</h3>
