// 1. STATS (Already implemented, kept as is)
const StatsView: React.FC = () => {
    const { t } = useLanguage();
    const [users, setUsers] = useState<User[]>([]);
    const [loading, setLoading] = useState(true);
    const [quizzesCount, setQuizzesCount] = useState(0);
    const [lessonsCount, setLessonsCount] = useState(0);
    const [resultsCount, setResultsCount] = useState(0);

    useEffect(() => {
        const loadStats = async () => {
            try {
                const allUsers = await ApiService.getUsers();
                if (Array.isArray(allUsers)) setUsers(allUsers);
                setQuizzesCount(StorageService.getQuizzes().length);
                setLessonsCount(StorageService.getLessons().length);
                setResultsCount(StorageService.getResults().length);
            } catch(e) { console.error(e); } finally { setLoading(false); }
        }
        loadStats();
    }, []);

    if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin w-8 h-8 text-blue-600"/></div>;

    const profs = users.filter(u => u.role === UserRole.PROFESSOR);
    const students = users.filter(u => u.role === UserRole.STUDENT);

    // School Stats Calculation
    const schoolStats = new Map<string, any>();
    users.forEach(u => {
        if (u.school && u.city) {
            const key = `${u.school}|${u.city}`;
            if (!schoolStats.has(key)) schoolStats.set(key, { name: u.school, city: u.city, profs: 0, students: 0 });
