const HeaderBackground = () => {
    // Restaurer l'effet visuel pour le coordinateur aussi
    const elements = useMemo(() => {
        const items = [];
        const chars = ['ا', 'ب', 'A', 'B', 'IoT', 'Smart'];
        for (let i = 0; i < 15; i++) {
            items.push({
                char: chars[Math.floor(Math.random() * chars.length)],
                top: Math.random() * 100,
                left: Math.random() * 100,
                size: Math.random() * 2 + 1,
                opacity: Math.random() * 0.15 + 0.05,
                rotate: Math.random() * 360
            });
        }
        return items;
    }, []);

    return (
        <div className="absolute inset-0 overflow-hidden pointer-events-none select-none bg-indigo-50/20">
            {elements.map((el, i) => (
                <div key={i} style={{
                    position: 'absolute',
                    top: `${el.top}%`,
                    left: `${el.left}%`,
                    fontSize: `${el.size}rem`,
                    color: `rgba(79, 70, 229, ${el.opacity})`,
