import { User, QuizResult } from '../types';
import { StorageService } from './storageService';

export interface PaginatedResponse<T> {
    data: T[];
    meta: {
        total: number;
        page: number;
        limit: number;
    };
}

export interface SystemChecks {
    nodeVersion: string;
    platform: string;
    memory: string;
    writeAccess: boolean;
    dbConnection: boolean;
}

export const ApiService = {
    // Vérifier si l'application est installée (Admin existe)
    checkInstallStatus: async (): Promise<boolean> => {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 1000); 

        try {
            const res = await fetch('/api/setup/status', { signal: controller.signal });
            clearTimeout(timeoutId);

            if (!res.ok) throw new Error("API Unreachable");
            const data = await res.json();

            // HYBRID FIX: If backend says not installed, but we have a Local Admin,
            // we trust LocalStorage to allow access (Legacy/Dev mode support).
            if (!data.installed && StorageService.hasAdmin()) {
                return true;
            }

            return data.installed;
        } catch (e) {
            // Offline or API down -> Trust LocalStorage
            return StorageService.hasAdmin(); 
        }
    },

    getSystemChecks: async (): Promise<SystemChecks> => {
        try {
            const res = await fetch('/api/setup/checks');
            if (!res.ok) throw new Error("Check failed");
            return await res.json();
        } catch (e) {
            // Mock if offline
            return {
                nodeVersion: 'Offline Mode',
                platform: 'Browser',
                memory: 'N/A',
                writeAccess: true, // Optimistic for local storage
                dbConnection: true
            };
        }
    },

    // Installer l'application
    installApp: async (adminData: any): Promise<boolean> => {
        let backendSuccess = false;
        try {
            const res = await fetch('/api/setup/install', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(adminData)
            });
            if (res.ok) backendSuccess = true;
        } catch (e) {
            console.warn("Backend install failed, continuing to local...");
        }

        // Always ensure local admin exists for hybrid compatibility
        const localSuccess = StorageService.createAdmin(adminData);

        return backendSuccess || localSuccess;
    },

    // Connexion via API (HttpOnly Cookies)
    login: async (username: string, password?: string): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
                credentials: 'include'
            });

            if (!res.ok) throw new Error('Login failed');

            const user = await res.json();
            return user;
        } catch (e) {
            console.error("Erreur Connexion API", e);
            return null;
        }
    },

    // Vérifier la session active
    checkSession: async (): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/me', {
                method: 'GET',
                credentials: 'include'
            });
            if (res.ok) {
                return await res.json();
            }
            return null;
        } catch (e) {
            return null;
        }
    },

    // Déconnexion
    logout: async () => {
        try {
            await fetch('/api/auth/logout', { method: 'POST', credentials: 'include' });
        } catch (e) {
            console.error("Erreur Logout API", e);
        }
    },

    // Legacy method (fetches all, mostly for fallback)
    getUsers: async (school?: string, city?: string): Promise<User[]> => {
        try {
            let url = '/api/users?';
            if (school) url += `school=${encodeURIComponent(school)}&`;
            if (city) url += `city=${encodeURIComponent(city)}`;

            const res = await fetch(url);
            const response = await res.json();

            // SECURITY FIX: Ensure we return an array, even if API errors
            if (response.data && Array.isArray(response.data)) return response.data;
            if (Array.isArray(response)) return response;
            return [];
        } catch (e) {
            return StorageService.getUsers(); // Fallback Local
        }
    },

    // NEW: Paginated Fetch
    getUsersPaginated: async (params: { page: number, limit: number, q?: string, role?: string, school?: string }): Promise<PaginatedResponse<User>> => {
        try {
            const searchParams = new URLSearchParams();
            searchParams.append('page', params.page.toString());
            searchParams.append('limit', params.limit.toString());
            if (params.q) searchParams.append('q', params.q);
            if (params.role) searchParams.append('role', params.role);
            if (params.school) searchParams.append('school', params.school);

            const res = await fetch(`/api/users?${searchParams.toString()}`);
            if (!res.ok) throw new Error("Fetch failed");
            return await res.json();
        } catch (e) {
            console.warn("API Paginated Fetch failed, falling back to local simulation", e);

            // Offline/Local Simulation of Pagination & Search
            let allUsers = StorageService.getUsers();

            if (params.role) allUsers = allUsers.filter(u => u.role === params.role);
            if (params.school) allUsers = allUsers.filter(u => u.school === params.school);
            if (params.q) {
                const q = params.q.toLowerCase();
                allUsers = allUsers.filter(u => u.name.toLowerCase().includes(q) || u.username.toLowerCase().includes(q));
            }

            const start = (params.page - 1) * params.limit;
            const end = start + params.limit;

            return {
                data: allUsers.slice(start, end),
                meta: {
                    total: allUsers.length,
                    page: params.page,
                    limit: params.limit
                }
            };
        }
    },

    createUser: async (user: User): Promise<boolean> => {
        try {
            const res = await fetch('/api/users', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(user)
            });
            return res.ok;
        } catch (e) {
            StorageService.saveUser(user);
            return true;
        }
    },

    updateUser: async (id: string, updates: Partial<User>): Promise<boolean> => {
        try {
            await fetch(`/api/users/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updates)
            });
            return true;
        } catch (e) {
            // Local fallback
            const users = StorageService.getUsers();
            const idx = users.findIndex(u => u.id === id);
            if (idx >= 0) {
                users[idx] = { ...users[idx], ...updates };
                localStorage.setItem('quizmaster_users', JSON.stringify(users));
            }
            return true;
        }
    },

    deleteUser: async (id: string): Promise<boolean> => {
        try {
            await fetch(`/api/users/${id}`, { method: 'DELETE' });
            return true;
        } catch (e) {
            StorageService.deleteUser(id);
            return true;
        }
    },

    submitQuiz: async (payload: { quizId: string, studentId: string, studentName: string, answers: any, timeSpent: number, essayScores: any, score: number, maxScore: number }): Promise<QuizResult | null> => {
        try {
            const res = await fetch('/api/quiz/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error("Submission Failed");
            return await res.json();
        } catch (e) {
            console.warn("Backend submit failed, using fallback:", e);
            return null;
        }
    },

    uploadFile: async (file: File): Promise<string> => {
        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData,
            });

            if (res.ok) {
                const data = await res.json();
                return data.url;
            }
            throw new Error('Server upload failed');
        } catch (e) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.readAsDataURL(file);
                reader.onload = () => resolve(reader.result as string);
                reader.onerror = (error) => reject(error);
            });
        }
    }
};

import express from 'express';
import cors from 'cors';
import bcrypt from 'bcryptjs';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import os from 'os';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { rateLimit } from 'express-rate-limit';
import helmet from 'helmet';
import jwt from 'jsonwebtoken';

// Imports internes
import { db } from './backend/db.js';
import { emailService } from './backend/email.js';

// Routes Import
import authRoutes from './backend/routes/auth.js';
import aiRoutes from './backend/routes/ai.js';
import userRoutes from './backend/routes/users.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3001;
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_secure_key_' + Date.now();
const LOCK_FILE = join(__dirname, 'installed.lock');

// --- SÉCURITÉ & CONFIGURATION ---

const limiter = rateLimit({
	windowMs: 15 * 60 * 1000, 
	limit: 300, 
	standardHeaders: 'draft-7',
	legacyHeaders: false,
    message: { error: "Trop de requêtes." }
});

const authLimiter = rateLimit({
    windowMs: 60 * 60 * 1000,
    limit: 20,
    message: { error: "Trop de tentatives de connexion." }
});

app.use(helmet({ contentSecurityPolicy: false, crossOriginEmbedderPolicy: false }));
app.use(cors({ origin: process.env.NODE_ENV === 'production' ? false : 'http://localhost:3000', credentials: true }));
app.use(express.json({ limit: '10mb' }));
app.use(cookieParser());

// Initialisation DB
db.connect({ path: process.env.DB_PATH || './database.sqlite' });

// Uploads Config
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) fs.mkdirSync(uploadDir, { recursive: true });

const storage = multer.diskStorage({
    destination: (req, file, cb) => cb(null, uploadDir),
    filename: (req, file, cb) => {
        const safeName = file.originalname.replace(/[^a-zA-Z0-9.]/g, "_");
        cb(null, Date.now() + '-' + Math.round(Math.random() * 1E9) + '-' + safeName);
    }
});
const upload = multer({ 
    storage, limits: { fileSize: 50 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
        if (file.mimetype.match(/(image|audio|video|application\/pdf|application\/msword)/)) cb(null, true);
        else cb(null, true);
    }
});

app.use('/uploads', express.static(uploadDir));
app.use('/api/', limiter); 

// --- MIDDLEWARES AUTH ---
const authenticateToken = (req, res, next) => {
    const token = req.cookies.token;
    if (!token) return res.status(401).json({ error: "Non authentifié" });
    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(403).json({ error: "Token invalide" });
        req.user = decoded;
        next();
    });
};

// --- ROUTES ---

// 1. Auth & Users
app.use('/api/auth', authRoutes); // Auth utilise ses propres middlewares si besoin, ou on peut wrapper
app.use('/api/users', authenticateToken, userRoutes);

// 2. AI
app.use('/api/ai', authenticateToken, aiRoutes);

// 3. System & Install (Resté ici pour l'instant car très spécifique au bootstrap)
app.get('/api/setup/status', async (req, res) => {
    try {
        const isLocked = fs.existsSync(LOCK_FILE);
        const admin = await db.get("SELECT count(*) as count FROM users WHERE role = 'ADMIN'");
        res.json({ installed: isLocked && admin && admin.count > 0 });
    } catch (err) { res.status(500).json({ error: err.message }); }
});

app.get('/api/setup/checks', (req, res) => {
    const checks = { nodeVersion: process.version, platform: os.platform(), memory: Math.round(os.totalmem() / 1024 / 1024) + " MB", writeAccess: false, dbConnection: !!db.db };
    try { fs.writeFileSync(join(__dirname, 'write_test.tmp'), 'test'); fs.unlinkSync(join(__dirname, 'write_test.tmp')); checks.writeAccess = true; } catch (e) {}
    res.json(checks);
});

app.post('/api/setup/install', async (req, res) => {
    const { username, password, name, schoolName, adminEmail } = req.body;
    try {
        await db.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", ['site_name', schoolName]);
        const id = `admin-${Date.now()}`;
        const hash = bcrypt.hashSync(password, 10);

        // Try insert, catch if exists
        try {
            await db.run(`INSERT INTO users (id, username, password, name, role, email, data) VALUES (?, ?, ?, ?, 'ADMIN', ?, ?)`, [id, username.trim().toLowerCase(), hash, name || 'Administrateur', adminEmail || '', JSON.stringify({ schoolName })]);
        } catch (err) {
            if (err.message && err.message.includes('UNIQUE')) {
                // Admin already exists, just proceed to lock
                console.log("Admin exists, proceeding to lock.");
            } else {
                throw err;
            }
        }

        fs.writeFileSync(LOCK_FILE, `INSTALLED_ON=${new Date().toISOString()}`);
        res.json({ success: true });
    } catch (err) { res.status(500).json({ error: err.message }); }
});

// 4. File Upload
app.post('/api/upload', authenticateToken, upload.single('file'), (req, res) => {
    if (!req.file) return res.status(400).json({ error: "No file uploaded" });
    res.json({ url: `/uploads/${req.file.filename}` });
});

// 5. Quiz Result (Manque dans les modules précédents, laissé ici pour l'instant)
app.post('/api/quiz/submit', authenticateToken, async (req, res) => {
    const { quizId, studentId, studentName, answers, timeSpent, essayScores, score, maxScore } = req.body;
    try {
        const result = { id: `res-${Date.now()}`, quizId, studentId, studentName, answers, timeSpent, score: score || 0, maxScore: maxScore || 0, submittedAt: new Date().toISOString(), essayScores };
        await db.run(`INSERT INTO results (id, quizId, studentId, score, submittedAt, data) VALUES (?, ?, ?, ?, ?, ?)`, [result.id, quizId, studentId, result.score, result.submittedAt, JSON.stringify(result)]);
        res.json(result);
    } catch (e) { res.status(500).json({ error: e.message }); }
});

// --- STATIC SERVING ---
const distPath = join(__dirname, 'dist');
if (fs.existsSync(distPath)) {
    app.use(express.static(distPath));
    app.get('*', (req, res) => { if (!req.path.startsWith('/api')) res.sendFile(join(distPath, 'index.html')); });
} else {
    // Mode DEV : Indication claire
    app.get('/', (req, res) => {
