import express from 'express';
import cors from 'cors';
import bcrypt from 'bcryptjs';
import cookieParser from 'cookie-parser';
import multer from 'multer';
import fs from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import jwt from 'jsonwebtoken';
import sqlite3 from 'sqlite3';
import { GoogleGenAI, Type } from "@google/genai";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3001;
const JWT_SECRET = process.env.JWT_SECRET || 'tinmel_secure_key_' + Date.now();
const API_KEY = process.env.API_KEY || process.env.GEMINI_API_KEY;

// --- CONFIGURATION ---
app.use(cors({ 
    origin: process.env.NODE_ENV === 'production' ? false : 'http://localhost:3000', 
    credentials: true 
}));
app.use(express.json({ limit: '10mb' }));
app.use(cookieParser());

// --- DATABASE (SQLite) ---
const dbPath = process.env.DB_PATH || './database.sqlite';
const db = new sqlite3.Database(dbPath, (err) => {
    if (err) console.error('❌ DB Error:', err);
    else console.log(`✅ DB Connected: ${dbPath}`);
});

// Init Tables
db.serialize(() => {
    db.run(`CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT UNIQUE, password TEXT, name TEXT, role TEXT, school TEXT, city TEXT, email TEXT, data TEXT)`);
    db.run(`CREATE TABLE IF NOT EXISTS results (id TEXT PRIMARY KEY, quizId TEXT, studentId TEXT, score REAL, submittedAt TEXT, data TEXT)`);
    db.run(`CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)`);
});

// --- MIDDLEWARE AUTH ---
const authenticateToken = (req, res, next) => {
    const token = req.cookies.token;
    if (!token) return res.status(401).json({ error: "Non authentifié" });
    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(403).json({ error: "Token invalide" });
        req.user = decoded;
        next();
    });
};

// --- UPLOAD CONFIG ---
const uploadDir = join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) fs.mkdirSync(uploadDir, { recursive: true });
const storage = multer.diskStorage({
    destination: (req, file, cb) => cb(null, uploadDir),
    filename: (req, file, cb) => cb(null, Date.now() + '-' + file.originalname.replace(/[^a-zA-Z0-9.]/g, "_"))
});
const upload = multer({ storage });
app.use('/uploads', express.static(uploadDir));

// --- ROUTES API ---

// 1. Auth
app.post('/api/auth/login', (req, res) => {
    const { username, password } = req.body;
    db.get("SELECT * FROM users WHERE username = ?", [username.toLowerCase()], (err, user) => {
        if (!user || !bcrypt.compareSync(password, user.password)) {
            return res.status(401).json({ error: "Identifiants incorrects" });
        }
        const token = jwt.sign({ id: user.id, role: user.role }, JWT_SECRET, { expiresIn: '24h' });

        const extra = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extra };
        delete userObj.password; delete userObj.data;

        res.cookie('token', token, { httpOnly: true, sameSite: 'lax' });
        res.json(userObj);
    });
});

app.post('/api/auth/logout', (req, res) => {
    res.clearCookie('token');
    res.json({ success: true });
});

app.get('/api/auth/me', authenticateToken, (req, res) => {
    db.get("SELECT * FROM users WHERE id = ?", [req.user.id], (err, user) => {
        if (!user) return res.status(404).json({ error: "User not found" });
        const extra = JSON.parse(user.data || '{}');
        const userObj = { ...user, ...extra };
        delete userObj.password; delete userObj.data;
        res.json(userObj);
    });
});

// 2. Users
app.get('/api/users', (req, res) => { // Public/Protected Mixed (Simplified for revert)
    db.all("SELECT * FROM users", [], (err, rows) => {
        if (err) return res.status(500).json({ error: err.message });
        const users = rows.map(r => {
            const extra = JSON.parse(r.data || '{}');
            const u = { ...r, ...extra };
            delete u.password; delete u.data;
            return u;
        });
        res.json({ data: users }); // Structure compatible avec le frontend
    });
});

app.post('/api/users', authenticateToken, (req, res) => {
    const { id, username, password, name, role, school, city, email, ...extra } = req.body;
    const hash = bcrypt.hashSync(password, 10);
    const stmt = db.prepare("INSERT INTO users (id, username, password, name, role, school, city, email, data) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
    stmt.run(id, username.toLowerCase(), hash, name, role, school, city, email || '', JSON.stringify(extra), function(err) {
        if (err) return res.status(400).json({ error: err.message });
        res.json({ success: true });
    });
});

app.delete('/api/users/:id', authenticateToken, (req, res) => {
    db.run("DELETE FROM users WHERE id = ?", [req.params.id], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

// 3. Quiz Results
app.post('/api/quiz/submit', authenticateToken, (req, res) => {
    const { quizId, studentId, score, maxScore, answers, ...rest } = req.body;
    const id = `res-${Date.now()}`;
    const data = JSON.stringify({ quizId, studentId, score, maxScore, answers, ...rest });
    db.run("INSERT INTO results (id, quizId, studentId, score, submittedAt, data) VALUES (?, ?, ?, ?, ?, ?)", 
        [id, quizId, studentId, score, new Date().toISOString(), data], 
        (err) => {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true, id });
        }
    );
});

// 4. AI Generation
app.post('/api/ai/generate-quiz', authenticateToken, async (req, res) => {
    if (!API_KEY) return res.status(500).json({ error: "API Key missing" });
    try {
        const { topic, count, language } = req.body;
        const ai = new GoogleGenAI({ apiKey: API_KEY });
        const prompt = `Génère un quiz de ${count || 5} questions sur "${topic}" en ${language === 'ar' ? 'Arabe' : 'Français'}. Format JSON strict compatible GoogleGenAI Schema.`;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            text: { type: Type.STRING },
                            type: { type: Type.STRING, enum: ['MCQ', 'BOOLEAN', 'SHORT_ANSWER'] },
                            points: { type: Type.NUMBER },
                            options: { type: Type.ARRAY, items: { type: Type.STRING } },
                            correctAnswer: { type: Type.STRING }
                        }
                    }
                }
            }
        });
        res.json({ questions: JSON.parse(response.text) });
    } catch (e) {
        res.status(500).json({ error: e.message });
    }
});

app.post('/api/upload', authenticateToken, upload.single('file'), (req, res) => {
    if (!req.file) return res.status(400).json({error: "No file"});
    res.json({ url: `/uploads/${req.file.filename}` });
});

