             });
        });
    });
});

app.post('/api/users', async (req, res) => {
    // Si c'est le premier utilisateur (Admin), on laisse passer sans auth
    db.get("SELECT count(*) as count FROM users", [], (err, row) => {
        if (row && row.count > 0) {
            // Check auth manually here since we can't easily wrap conditional middleware in this structure
            const token = req.cookies.token;
            if (!token) return res.status(401).json({ error: "Non authentifié" });
            try { jwt.verify(token, JWT_SECRET); } catch(e) { return res.status(403).json({ error: "Token invalide" }); }
        }

        const { id, username, password, name, role, school, city, email, ...extra } = req.body;
        const hash = bcrypt.hashSync(password, 10);
        const stmt = db.prepare("INSERT INTO users (id, username, password, name, role, school, city, email, data) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
        stmt.run(id, username.toLowerCase(), hash, name, role, school, city, email || '', JSON.stringify(extra), function(err) {
            if (err) return res.status(400).json({ error: err.message });
            res.json({ success: true });
        });
    });
});

app.put('/api/users/:id', authenticateToken, (req, res) => {
    const { password, ...updates } = req.body;
    db.get("SELECT * FROM users WHERE id = ?", [req.params.id], (err, user) => {
        if (!user) return res.status(404).json({ error: "User not found" });

        let extra = JSON.parse(user.data || '{}');
        extra = { ...extra, ...updates };

        let newPass = user.password;
        if (password) newPass = bcrypt.hashSync(password, 10);

        const stmt = db.prepare("UPDATE users SET password = ?, data = ?, name = ?, email = ? WHERE id = ?");
        stmt.run(newPass, JSON.stringify(extra), updates.name || user.name, updates.email || user.email, req.params.id, (err) => {
            if (err) return res.status(500).json({ error: err.message });
            res.json({ success: true });
        });
    });
});

app.delete('/api/users/:id', authenticateToken, (req, res) => {
    db.run("DELETE FROM users WHERE id = ?", [req.params.id], (err) => {
        if (err) return res.status(500).json({ error: err.message });
        res.json({ success: true });
    });
});

