import { User, QuizResult } from '../types';
import { StorageService } from './storageService';

export interface PaginatedResponse<T> {
    data: T[];
    meta: {
        total: number;
        page: number;
        limit: number;
    };
}

export const ApiService = {

    // Vérification installation RÉELLE
    checkInstallStatus: async (): Promise<boolean> => {
        try {
            const res = await fetch('/api/setup/status');
            if (res.ok) {
                const data = await res.json();
                return data.installed;
            }
        } catch (e) {
            // Si le serveur est hors ligne, on vérifie le stockage local
            console.warn("API check failed, checking local storage");
        }
        return StorageService.hasAdmin(); 
    },

    getSystemChecks: async () => {
        // Mock checks for UI display
        return { nodeVersion: 'OK', dbConnection: true, writeAccess: true };
    },

    installApp: async (adminData: any): Promise<boolean> => {
        // 1. Local
        StorageService.createAdmin(adminData);
        // 2. API (Try but don't fail if offline)
        try {
            await fetch('/api/users', { 
                method: 'POST', 
                headers: {'Content-Type': 'application/json'}, 
                body: JSON.stringify({...adminData, role: 'ADMIN', id: `admin-${Date.now()}`}) 
            });
        } catch(e) {}
        return true;
    },

    login: async (username: string, password?: string): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
                credentials: 'include'
            });
            if (res.ok) return await res.json();
            throw new Error("API Login Failed");
        } catch (e) {
            console.warn("API Login failed, trying LocalStorage...");
            return StorageService.login(username, password);
        }
    },

    checkSession: async (): Promise<User | null> => {
        try {
            const res = await fetch('/api/auth/me');
            if (res.ok) return await res.json();
        } catch (e) { }
        return StorageService.getSession();
    },

    logout: async () => {
        try { await fetch('/api/auth/logout', { method: 'POST' }); } catch(e) {}
        StorageService.clearSession();
    },

    getUsers: async (school?: string, city?: string): Promise<User[]> => {
        try {
            const res = await fetch('/api/users');
            if (!res.ok) throw new Error("Fetch failed");
            const json = await res.json();
            return json.data || json;
        } catch (e) {
            return StorageService.getUsers();
        }
    },

    getUsersPaginated: async (params: any): Promise<PaginatedResponse<User>> => {
        try {
            const res = await fetch(`/api/users?page=${params.page}&limit=${params.limit}`);
            if(!res.ok) throw new Error();
            return await res.json();
        } catch(e) {
            const all = StorageService.getUsers();
            return { data: all.slice(0, params.limit), meta: { total: all.length, page: 1, limit: params.limit }};
        }
    },

    createUser: async (user: User): Promise<boolean> => {
        try {
            await fetch('/api/users', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(user)
            });
        } catch (e) {}
        StorageService.saveUser(user);
        return true;
    },

    updateUser: async (id: string, updates: Partial<User>): Promise<boolean> => {
        try {
            await fetch(`/api/users/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updates)
            });
        } catch (e) {}
        // Update Local
        const users = StorageService.getUsers();
        const idx = users.findIndex(u => u.id === id);
        if(idx >= 0) {
            users[idx] = { ...users[idx], ...updates };
            localStorage.setItem('quizmaster_users', JSON.stringify(users));
        }
        return true;
    },

    deleteUser: async (id: string): Promise<boolean> => {
        try { await fetch(`/api/users/${id}`, { method: 'DELETE' }); } catch(e) {}
        StorageService.deleteUser(id);
        return true;
    },

    submitQuiz: async (payload: any): Promise<QuizResult | null> => {
        try {
            const res = await fetch('/api/quiz/submit', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            if(res.ok) return await res.json();
        } catch (e) {}
        return null;
    },

    uploadFile: async (file: File): Promise<string> => {
        try {
            const formData = new FormData();
            formData.append('file', file);
            const res = await fetch('/api/upload', { method: 'POST', body: formData });
            if(res.ok) {
                const data = await res.json();
                return data.url;
            }
        } catch(e) {}

        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = () => resolve(reader.result as string);
        });
    }
};

