            setConversation(StorageService.getMessages(user.id, selectedUser.id));
            const interval = setInterval(() => {
                setConversation(StorageService.getMessages(user.id, selectedUser.id));
            }, 2000);
            return () => clearInterval(interval);
        }
    }, [selectedUser, user]);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [conversation]);

    const send = () => {
        if (!msgText.trim() || !selectedUser) return;
        const msg: Message = {
            id: `msg-${Date.now()}`,
            senderId: user.id,
            senderName: user.name,
            receiverId: selectedUser.id,
            content: msgText,
            timestamp: new Date().toISOString(),
            read: false
        };
        StorageService.sendMessage(msg);
        setConversation([...conversation, msg]);
        setMsgText('');
    };

    return (
        <div className="flex h-[calc(100vh-150px)] bg-white rounded-xl shadow-sm border overflow-hidden animate-fade-in">
            {/* Contacts List */}
            <div className="w-1/3 border-r bg-gray-50 flex flex-col">
                <div className="p-4 border-b font-bold text-gray-700">{t('staffChat')}</div>
                <div className="flex-1 overflow-y-auto">
                    {contacts.map(c => (
                        <div 
                            key={c.id} 
                            onClick={() => setSelectedUser(c)}
                            className={`p-4 border-b cursor-pointer hover:bg-white transition-colors ${selectedUser?.id === c.id ? 'bg-white border-l-4 border-l-indigo-600' : ''}`}
                        >
                            <div className="font-bold text-gray-800">{c.name}</div>
                            <div className="text-xs text-gray-500">{t(c.role.toLowerCase())}</div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Chat Area */}
            <div className="flex-1 flex flex-col bg-white">
                {selectedUser ? (
                    <>
                        <div className="p-4 border-b bg-white font-bold flex items-center gap-2 text-indigo-700">
                            <MessageCircle className="w-5 h-5"/> {selectedUser.name}
                        </div>
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50">
                            {conversation.map(m => (
                                <div key={m.id} className={`flex flex-col ${m.senderId === user.id ? 'items-end' : 'items-start'}`}>
                                    <div className={`max-w-[70%] p-3 rounded-lg text-sm shadow-sm ${m.senderId === user.id ? 'bg-indigo-600 text-white rounded-br-none' : 'bg-white border text-gray-800 rounded-bl-none'}`}>
                                        {m.content}
                                    </div>
                                    <span className="text-[10px] text-gray-400 mt-1">{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                </div>
                            ))}
                            <div ref={messagesEndRef}></div>
                        </div>
                        <div className="p-3 border-t bg-white flex gap-2">
                            <input 
                                className="flex-1 border rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                                placeholder={t('typeMessage')}
                                value={msgText}
                                onChange={e => setMsgText(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && send()}
                            />
                            <button onClick={send} className="bg-indigo-600 text-white p-2 rounded-full hover:bg-indigo-700 transition">
                                <Send className="w-5 h-5 rtl:flip"/>
                            </button>
                        </div>
                    </>
                ) : (
                    <div className="flex-1 flex items-center justify-center text-gray-400 flex-col gap-2">
                        <MessageCircle className="w-12 h-12 opacity-20"/>
                        <p>{t('selectProf')}</p>
                    </div>
                )}
            </div>
        </div>
    );
};

