        const res = await ApiService.getUsersPaginated({ page: 1, limit: 50, q });
        setResults(res.data);
    };

    return (
        <div className="space-y-4 animate-fade-in">
            <div className="bg-white p-6 rounded-xl shadow-sm border flex gap-2">
                <div className="relative flex-1">
                    <Search className="absolute left-3 top-3 w-5 h-5 text-gray-400"/>
                    <input className="w-full pl-10 pr-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500" placeholder={t('globalSearchPlaceholder')} value={q} onChange={e => setQ(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSearch()}/>
                </div>
                <button onClick={handleSearch} className="bg-blue-600 text-white px-6 rounded-lg font-bold">{t('search')}</button>
            </div>
            {results.length > 0 && (
                <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                    <table className="w-full text-sm text-left">
                        <thead className="bg-gray-50 border-b">
                            <tr><th className="p-3">Nom</th><th className="p-3">Role</th><th className="p-3">École</th><th className="p-3">Actions</th></tr>
                        </thead>
                        <tbody>
                            {results.map(u => (
                                <tr key={u.id} className="border-b hover:bg-gray-50">
                                    <td className="p-3 font-medium">{u.name}<br/><span className="text-xs text-gray-400">{u.username}</span></td>
                                    <td className="p-3"><span className="px-2 py-1 rounded-full text-xs font-bold bg-gray-100">{u.role}</span></td>
                                    <td className="p-3 text-gray-500">{u.school}</td>
                                    <td className="p-3 text-right">
                                        <button onClick={() => {if(confirm("Supprimer?")) ApiService.deleteUser(u.id).then(handleSearch)}} className="text-red-500 hover:bg-red-50 p-2 rounded"><Trash2 className="w-4 h-4"/></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
};

// 3. ESTABLISHMENTS VIEW (RESTORED LOGIN GENERATION)
const EstablishmentsView: React.FC = () => {
    const { t } = useLanguage();
    const [schools, setSchools] = useState<string[]>([]);
    const [showForm, setShowForm] = useState(false);
    const [form, setForm] = useState({ school: '', city: '', coordinatorName: '', username: '', password: '' });

    // Bulk Gen State
    const [showBulk, setShowBulk] = useState<string | null>(null);
    const [bulkData, setBulkData] = useState({ role: UserRole.STUDENT, count: 10, prefix: '' });

    const load = async () => {
        const users = await ApiService.getUsers();
        const unique = Array.from(new Set(users.filter(u => u.school && u.accountType !== 'INDIVIDUAL').map(u => `${u.school} (${u.city})`)));
        setSchools(unique);
    };

    useEffect(() => { load(); }, []);

    const generateCoordLogin = () => {
        if (form.school && form.city) {
            const code = form.school.substring(0,3).toLowerCase().replace(/\s/g, '');
            setForm(prev => ({ ...prev, username: `coord_${code}` }));
        }
    };

    const createSchool = async (e: React.FormEvent) => {
        e.preventDefault();
        const code = form.school.substring(0,3).toLowerCase().replace(/\s/g, '');
        const coord: User = {
            id: `coord-${Date.now()}`,
            name: form.coordinatorName,
            username: form.username || `coord_${code}_${Date.now().toString().slice(-3)}`,
            password: form.password || '123456',
            role: UserRole.COORDINATOR,
            school: form.school,
            city: form.city,
            accountType: 'ESTABLISHMENT'
        };
        await ApiService.createUser(coord);
        StorageService.saveSchoolStructure({
            id: `struct-${Date.now()}`,
            school: form.school,
            city: form.city,
            classes: []
        });

        setShowForm(false);
        setForm({ school: '', city: '', coordinatorName: '', username: '', password: '' });
        load();
    };

    const handleBulkGenerate = async () => {
        if (!showBulk) return;
        const [schoolName, cityName] = showBulk.replace(')', '').split(' (');
        const generated = [];

        // --- RESTORED GENERATION LOGIC ---
        const basePrefix = bulkData.prefix || (bulkData.role === UserRole.STUDENT ? 'stud' : 'prof');
        const schoolCode = schoolName.substring(0,3).toLowerCase().replace(/\s/g, '');

        for (let i = 1; i <= bulkData.count; i++) {
            const pass = Math.floor(1000 + Math.random() * 9000).toString(); 
            const user: User = {
                id: `gen-${Date.now()}-${i}`,
                name: `${basePrefix === 'stud' ? 'Élève' : 'Prof'} ${i}`,
                username: `${basePrefix}_${schoolCode}_${i}_${Math.floor(Math.random()*100)}`, // Added random suffix to ensure uniqueness
                password: pass,
                role: bulkData.role,
                school: schoolName,
                city: cityName,
                accountType: 'ESTABLISHMENT'
            };
            await ApiService.createUser(user);
            generated.push({ Nom: user.name, Login: user.username, Password: pass, Role: user.role });
        }

        exportToExcel(generated, `Comptes_${schoolName}_${bulkData.role}`);
        alert(`${bulkData.count} comptes générés (Format: ${basePrefix}_...) et exportés !`);
        setShowBulk(null);
    };

    return (
        <div className="space-y-6 animate-fade-in">
             <div className="flex justify-between items-center">
                <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><Building className="w-6 h-6 text-indigo-600"/> {t('establishments')}</h2>
                <button onClick={() => setShowForm(!showForm)} className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold hover:bg-indigo-700">
                    <Plus className="w-4 h-4"/> Nouvelle École
                </button>
            </div>

            {showForm && (
                <div className="bg-white p-6 rounded-xl shadow border border-indigo-100">
                    <h3 className="font-bold mb-4 text-gray-700">Création d'un Espace Coordinateur</h3>
                    <form onSubmit={createSchool} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <input className="border p-2 rounded" placeholder="Nom de l'École" required value={form.school} onChange={e => setForm({...form, school: e.target.value})} onBlur={generateCoordLogin}/>
                        <input className="border p-2 rounded" placeholder="Ville" required value={form.city} onChange={e => setForm({...form, city: e.target.value})} />
                        <input className="border p-2 rounded" placeholder="Nom du Coordinateur" required value={form.coordinatorName} onChange={e => setForm({...form, coordinatorName: e.target.value})} />
                        <div className="relative">
                            <input className="border p-2 rounded w-full" placeholder="Login (ex: coord_...)" value={form.username} onChange={e => setForm({...form, username: e.target.value})} />
                            <button type="button" onClick={generateCoordLogin} className="absolute right-2 top-2 text-indigo-500 hover:text-indigo-700"><Wand2 className="w-4 h-4"/></button>
                        </div>
                        <input className="border p-2 rounded" placeholder="Mot de passe" required value={form.password} onChange={e => setForm({...form, password: e.target.value})} />
                        <button type="submit" className="md:col-span-2 bg-green-600 text-white py-2 rounded font-bold">Créer et Assigner</button>
                    </form>
                </div>
            )}

            {showBulk && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 animate-fade-in">
                    <div className="bg-white p-6 rounded-xl shadow-2xl w-full max-w-md">
                        <h3 className="font-bold text-lg mb-4 flex items-center gap-2"><FileDown className="w-5 h-5"/> Générateur de Comptes</h3>
                        <p className="text-sm text-gray-500 mb-4">Pour : {showBulk}</p>

                        <div className="space-y-3">
                            <select className="w-full border p-2 rounded" value={bulkData.role} onChange={e => setBulkData({...bulkData, role: e.target.value as UserRole})}>
                                <option value={UserRole.STUDENT}>Étudiants (stud_)</option>
                                <option value={UserRole.PROFESSOR}>Professeurs (prof_)</option>
                            </select>
                            <input type="number" className="w-full border p-2 rounded" placeholder="Nombre (ex: 30)" value={bulkData.count} onChange={e => setBulkData({...bulkData, count: parseInt(e.target.value)})} />
                            <input className="w-full border p-2 rounded" placeholder="Préfixe (ex: stud_)" value={bulkData.prefix} onChange={e => setBulkData({...bulkData, prefix: e.target.value})} />
                        </div>

                        <div className="flex gap-2 mt-6 justify-end">
                            <button onClick={() => setShowBulk(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded">Annuler</button>
                            <button onClick={handleBulkGenerate} className="px-4 py-2 bg-indigo-600 text-white rounded font-bold">Générer & Exporter</button>
                        </div>
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {schools.map(s => (
                    <div key={s} className="bg-white p-6 rounded-xl shadow-sm border hover:shadow-md transition">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-12 h-12 bg-indigo-100 rounded-lg flex items-center justify-center text-indigo-600"><Building/></div>
                            <div>
                                <h3 className="font-bold text-gray-800">{s.split('(')[0]}</h3>
                                <p className="text-xs text-gray-500">{s.split('(')[1].replace(')', '')}</p>
                            </div>
                        </div>
                        <div className="flex flex-col gap-2">
                             <button onClick={() => setShowBulk(s)} className="w-full bg-indigo-50 text-indigo-700 py-2 rounded text-sm font-bold hover:bg-indigo-100 flex items-center justify-center gap-2">
                                 <FileDown className="w-4 h-4"/> Générer Accès
                             </button>
                             <div className="flex gap-2">
                                 <button className="flex-1 bg-gray-50 text-gray-600 py-2 rounded text-sm font-medium hover:bg-gray-100">Détails</button>
                                 <button onClick={() => {
                                     if(confirm("Supprimer cette école et TOUS ses utilisateurs ?")) {
                                         const [name, city] = s.replace(')', '').split(' (');
                                         StorageService.deleteSchoolFull(name, city);
                                         load();
                                     }
                                 }} className="p-2 text-red-500 hover:bg-red-50 rounded"><Trash2 className="w-4 h-4"/></button>
                             </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

