import React, { useState } from 'react';
import { ApiService } from '../services/apiService';
import { Server, CheckCircle, AlertTriangle, Loader2, School, User, Lock, Mail } from 'lucide-react';
import { useLanguage } from '../contexts/LanguageContext';

interface Props {
    onInstalled: () => void;
}

const InstallPage: React.FC<Props> = ({ onInstalled }) => {
    const { t, dir } = useLanguage();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');
    const [step, setStep] = useState(1);

    const [formData, setFormData] = useState({
        schoolName: '',
        username: 'admin',
        password: '',
        confirmPassword: '',
        adminEmail: '',
        name: 'Administrateur'
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        if (formData.password !== formData.confirmPassword) {
            setError("Les mots de passe ne correspondent pas.");
            return;
        }

        if (formData.password.length < 6) {
            setError("Le mot de passe doit contenir au moins 6 caractères.");
            return;
        }

        setLoading(true);

        try {
            const success = await ApiService.installApp({
                username: formData.username,
                password: formData.password,
                schoolName: formData.schoolName,
                name: formData.name,
                adminEmail: formData.adminEmail,
                envMode: 'production'
            });

            if (success) {
                // Petite pause pour s'assurer que le backend a fini d'écrire le fichier lock
                setTimeout(() => {
                    onInstalled();
                }, 1000);
            } else {
                setError("Échec de l'installation. Vérifiez les logs serveur.");
                setLoading(false);
            }
        } catch (err) {
            setError("Erreur de connexion au serveur.");
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-slate-900 to-blue-900 flex items-center justify-center p-4 font-sans" dir={dir}>
            <div className="bg-white w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden animate-fade-in">
                {/* Header */}
                <div className="bg-slate-800 p-8 text-center border-b border-slate-700 relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full bg-blue-600/10"></div>
                    <div className="relative z-10">
                        <div className="w-16 h-16 bg-blue-500 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-lg rotate-3">
                            <Server className="w-8 h-8 text-white" />
                        </div>
                        <h1 className="text-3xl font-black text-white font-logo tracking-tight mb-1">{t('installTitle')}</h1>
                        <p className="text-slate-400 text-sm">{t('installDesc')}</p>
                    </div>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-8 space-y-6">
                    {error && (
                        <div className="bg-red-50 text-red-600 p-4 rounded-lg text-sm flex items-center gap-3 border border-red-100 animate-bounce-in">
                            <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                            {error}
                        </div>
                    )}

                    <div className="space-y-4">
                        {/* School Name */}
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">{t('siteName')}</label>
                            <div className="relative">
                                <School className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                                <input 
                                    name="schoolName"
                                    required
                                    className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition bg-gray-50 focus:bg-white"
                                    placeholder="Ex: École Al-Mowahidine"
                                    value={formData.schoolName}
                                    onChange={handleChange}
                                />
                            </div>
                        </div>

                        {/* Admin Username */}
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">{t('adminUsername')}</label>
                                <div className="relative">
                                    <User className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                                    <input 
                                        name="username"
                                        required
                                        className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition bg-gray-50 focus:bg-white"
                                        placeholder="admin"
                                        value={formData.username}
                                        onChange={handleChange}
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1 ml-1">Email (Optionnel)</label>
                                <div className="relative">
                                    <Mail className="absolute left-3 top-3 w-5 h-5 text-gray-400" />
                                    <input 
                                        name="adminEmail"
                                        type="email"
                                        className="w-full pl-10 pr-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition bg-gray-50 focus:bg-white"
                                        placeholder="admin@ecole.ma"
                                        value={formData.adminEmail}
                                        onChange={handleChange}
                                    />
