export const StorageService = {
    // --- GENERIC HELPERS ---
    getItem: <T>(key: string): T[] => {
        try {
            return JSON.parse(localStorage.getItem(key) || '[]');
        } catch {
            return [];
        }
    },

    setItem: (key: string, data: any) => {
        localStorage.setItem(key, JSON.stringify(data));
    },

    // --- USERS ---
    getUsers: (): User[] => StorageService.getItem<User>(STORAGE_KEYS.USERS),

    getUsersByRole: (role: UserRole): User[] => {
        return StorageService.getUsers().filter(u => u.role === role);
    },

    saveUser: (user: User) => {
        const users = StorageService.getUsers();
        const index = users.findIndex(u => u.id === user.id);
        if (index >= 0) {
            users[index] = user;
        } else {
            users.push(user);
        }
        StorageService.setItem(STORAGE_KEYS.USERS, users);
    },

    deleteUser: (id: string) => {
        const users = StorageService.getUsers().filter(u => u.id !== id);
        StorageService.setItem(STORAGE_KEYS.USERS, users);
    },

    // --- QUIZZES ---
    getQuizzes: (): Quiz[] => StorageService.getItem<Quiz>(STORAGE_KEYS.QUIZZES),

    getQuizzesByProf: (profId: string): Quiz[] => {
        return StorageService.getQuizzes().filter(q => q.professorId === profId);
    },

    saveQuiz: (quiz: Quiz) => {
        const quizzes = StorageService.getQuizzes();
        const index = quizzes.findIndex(q => q.id === quiz.id);
        if (index >= 0) {
            quizzes[index] = quiz;
        } else {
            quizzes.push(quiz);
        }
        StorageService.setItem(STORAGE_KEYS.QUIZZES, quizzes);
    },

    deleteQuiz: (id: string) => {
        const quizzes = StorageService.getQuizzes().filter(q => q.id !== id);
        StorageService.setItem(STORAGE_KEYS.QUIZZES, quizzes);
    },

    getAvailableQuizzesForStudent: (user: User): Quiz[] => {
        const quizzes = StorageService.getQuizzes();
        // Filter by assigned classes
        return quizzes.filter(q => 
            q.status === 'PUBLISHED' && 
            q.assignedClasses.some(c => (user.enrolledClasses || []).includes(c))
        );
    },

    // --- LESSONS ---
    getLessons: (): Lesson[] => StorageService.getItem<Lesson>(STORAGE_KEYS.LESSONS),

    getLessonsByProf: (profId: string): Lesson[] => {
        return StorageService.getLessons().filter(l => l.professorId === profId);
    },

    saveLesson: (lesson: Lesson) => {
        const lessons = StorageService.getLessons();
        const index = lessons.findIndex(l => l.id === lesson.id);
        if (index >= 0) {
            lessons[index] = lesson;
        } else {
            lessons.push(lesson);
        }
        StorageService.setItem(STORAGE_KEYS.LESSONS, lessons);
    },

    deleteLesson: (id: string) => {
        const lessons = StorageService.getLessons().filter(l => l.id !== id);
        StorageService.setItem(STORAGE_KEYS.LESSONS, lessons);
    },

    getLessonsForStudent: (user: User): Lesson[] => {
        const lessons = StorageService.getLessons();
        return lessons.filter(l => 
            l.status === 'PUBLISHED' && 
            l.assignedClasses.some(c => (user.enrolledClasses || []).includes(c))
        );
    },

    completeLesson: (lessonId: string, studentId: string) => {
        const lessons = StorageService.getLessons();
        const lesson = lessons.find(l => l.id === lessonId);
        if (lesson) {
            if (!lesson.completedBy) lesson.completedBy = [];
            if (!lesson.completedBy.includes(studentId)) {
                lesson.completedBy.push(studentId);
                StorageService.saveLesson(lesson);
            }
        }
    },

    getActiveStudentCount: (lessonId: string): number => {
        // Mocking active students for demo
        return Math.floor(Math.random() * 5); 
    },

    // --- RESULTS ---
    getResults: (): QuizResult[] => StorageService.getItem<QuizResult>(STORAGE_KEYS.RESULTS),

    saveResult: (result: QuizResult) => {
        const results = StorageService.getResults();
        results.push(result);
        StorageService.setItem(STORAGE_KEYS.RESULTS, results);
    },

    // --- EVENTS ---
    getEventsByProf: (profId: string): SchoolEvent[] => {
        return StorageService.getItem<SchoolEvent>(STORAGE_KEYS.EVENTS).filter(e => e.professorId === profId);
    },

    saveEvent: (event: SchoolEvent) => {
        const events = StorageService.getItem<SchoolEvent>(STORAGE_KEYS.EVENTS);
        events.push(event);
        StorageService.setItem(STORAGE_KEYS.EVENTS, events);
    },

    deleteEvent: (id: string) => {
        const events = StorageService.getItem<SchoolEvent>(STORAGE_KEYS.EVENTS).filter(e => e.id !== id);
        StorageService.setItem(STORAGE_KEYS.EVENTS, events);
    },

    getEventsForStudent: (user: User): SchoolEvent[] => {
        const events = StorageService.getItem<SchoolEvent>(STORAGE_KEYS.EVENTS);
        return events.filter(e => e.assignedClasses.some(c => (user.enrolledClasses || []).includes(c)));
    },

    // --- ANNOUNCEMENTS & REQUESTS ---
    getPartnerRequests: (): PartnerRequest[] => StorageService.getItem<PartnerRequest>(STORAGE_KEYS.PARTNER_REQUESTS),

    updatePartnerRequestStatus: (id: string, status: 'PENDING' | 'CONTACTED') => {
        const reqs = StorageService.getPartnerRequests();
        const r = reqs.find(rq => rq.id === id);
        if (r) {
            r.status = status;
            StorageService.setItem(STORAGE_KEYS.PARTNER_REQUESTS, reqs);
        }
    },

    saveAnnouncement: (ann: Announcement) => {
        const anns = StorageService.getItem<Announcement>(STORAGE_KEYS.ANNOUNCEMENTS);
        anns.push(ann);
        StorageService.setItem(STORAGE_KEYS.ANNOUNCEMENTS, anns);
    },

    // --- AUTH & ADMIN ---
    login: (username: string, password?: string): User | null => {
        const users = StorageService.getUsers();
        // In local mock, simple password check or bypass for demo if no password stored properly
        return users.find(u => u.username.toLowerCase() === username.toLowerCase() && (u.password === password || u.readablePassword === password)) || null;
    },

    hasAdmin: (): boolean => {
        return StorageService.getUsers().some(u => u.role === UserRole.ADMIN);
    },

    createAdmin: (data: any): boolean => {
        const admin: User = {
            id: 'admin-local',
            username: data.username,
            password: data.password, // Plain for local
            readablePassword: data.password,
            name: data.name || 'Admin',
            role: UserRole.ADMIN,
            email: data.adminEmail,
            school: data.schoolName
        };
        StorageService.saveUser(admin);
        return true;
    },

    getSession: (): User | null => {
        const s = localStorage.getItem(STORAGE_KEYS.SESSION);
        return s ? JSON.parse(s) : null;
    },

    saveSession: (user: User) => {
        localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(user));
    },

    clearSession: () => {
        localStorage.removeItem(STORAGE_KEYS.SESSION);
    },

    exportFullDB: (): string => {
        const db = {
            users: StorageService.getUsers(),
            quizzes: StorageService.getQuizzes(),
            lessons: StorageService.getLessons(),
            results: StorageService.getResults(),
            events: StorageService.getItem(STORAGE_KEYS.EVENTS),
            whiteboards: StorageService.getWhiteboards(),
            structure: StorageService.getItem(STORAGE_KEYS.SCHOOL_STRUCTURES),
            devices: StorageService.getItem(STORAGE_KEYS.IOT_DEVICES),
            requests: StorageService.getItem(STORAGE_KEYS.PARTNER_REQUESTS)
        };
        return JSON.stringify(db, null, 2);
    },

    deleteSchoolFull: (schoolName: string, city: string) => {
        // Delete users
        let users = StorageService.getUsers().filter(u => !(u.school === schoolName && u.city === city));
        StorageService.setItem(STORAGE_KEYS.USERS, users);

        // Structure
        let structures = StorageService.getItem<SchoolStructure>(STORAGE_KEYS.SCHOOL_STRUCTURES).filter(s => !(s.school === schoolName && s.city === city));
        StorageService.setItem(STORAGE_KEYS.SCHOOL_STRUCTURES, structures);

        // Devices
        let devices = StorageService.getItem<IoTDevice>(STORAGE_KEYS.IOT_DEVICES).filter(d => !(d.school === schoolName && d.city === city));
        StorageService.setItem(STORAGE_KEYS.IOT_DEVICES, devices);
    },

    // --- SCHOOL STRUCTURE ---
    getSchoolStructure: (school: string, city: string): SchoolStructure => {
        const structures = StorageService.getItem<SchoolStructure>(STORAGE_KEYS.SCHOOL_STRUCTURES);
        return structures.find(s => s.school === school && s.city === city) || { id: 'new', school, city, classes: [] };
    },

    saveSchoolStructure: (structure: SchoolStructure) => {
        const structures = StorageService.getItem<SchoolStructure>(STORAGE_KEYS.SCHOOL_STRUCTURES);
        const idx = structures.findIndex(s => s.school === structure.school && s.city === structure.city);
        if (idx >= 0) structures[idx] = structure;
        else structures.push(structure);
        StorageService.setItem(STORAGE_KEYS.SCHOOL_STRUCTURES, structures);
    },

    // --- WHITEBOARD ---
    getWhiteboards: (): WhiteboardSession[] => StorageService.getItem<WhiteboardSession>(STORAGE_KEYS.WHITEBOARDS),

    getWhiteboardsByProf: (profId: string): WhiteboardSession[] => {
        return StorageService.getWhiteboards().filter(w => w.hostId === profId);
    },

    saveWhiteboard: (wb: WhiteboardSession) => {
        const wbs = StorageService.getWhiteboards();
        const idx = wbs.findIndex(w => w.id === wb.id);
        if (idx >= 0) wbs[idx] = wb;
        else wbs.push(wb);
        StorageService.setItem(STORAGE_KEYS.WHITEBOARDS, wbs);
    },

    getWhiteboardById: (id: string): WhiteboardSession | undefined => {
        return StorageService.getWhiteboards().find(w => w.id === id);
    },

    getWhiteboardByKey: (key: string): WhiteboardSession | undefined => {
        // Correction: On autorise l'accès si la clé correspond et que la session n'est pas TERMINÉE.
        // Cela permet aux élèves d'entrer dans une salle d'attente (SCHEDULED) ou active (LIVE).
        return StorageService.getWhiteboards().find(w => w.accessKey === key && w.status !== 'ENDED');
    },

    getWhiteboardsForStudent: (user: User): WhiteboardSession[] => {
        const wbs = StorageService.getWhiteboards();
        return wbs.filter(w => 
            w.status !== 'ENDED' &&
            (
                (w.assignedClasses && w.assignedClasses.some(c => (user.enrolledClasses || []).includes(c))) ||
                (w.invitedStudentIds && w.invitedStudentIds.includes(user.id))
            )
        );
    },

    getActiveWhiteboardForHost: (hostId: string): WhiteboardSession | undefined => {
        return StorageService.getWhiteboards().find(w => w.hostId === hostId && w.status === 'LIVE');
    },

    endWhiteboardSession: (id: string) => {
        const wbs = StorageService.getWhiteboards();
        const wb = wbs.find(w => w.id === id);
        if (wb) {
            wb.status = 'ENDED';
            wb.isActive = false;
            StorageService.saveWhiteboard(wb);
        }
    },

    addStrokeToWhiteboard: (id: string, stroke: Stroke) => {
        const wb = StorageService.getWhiteboardById(id);
        if (wb) {
            wb.strokes.push(stroke);
            StorageService.saveWhiteboard(wb);
        }
    },

    addMessageToWhiteboard: (id: string, message: WhiteboardMessage) => {
        const wb = StorageService.getWhiteboardById(id);
        if (wb) {
            if (!wb.messages) wb.messages = [];
            wb.messages.push(message);
            StorageService.saveWhiteboard(wb);
        }
    },

    // --- MESSAGING ---
    getAllMessages: (): Message[] => StorageService.getItem<Message>(STORAGE_KEYS.MESSAGES),

    getMessages: (userId1: string, userId2: string): Message[] => {
        const msgs = StorageService.getAllMessages();
        return msgs.filter(m => 
            (m.senderId === userId1 && m.receiverId === userId2) || 
            (m.senderId === userId2 && m.receiverId === userId1)
        ).sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    },

    getGroupMessages: (groupId: string): Message[] => {
        const msgs = StorageService.getAllMessages();
        return msgs.filter(m => m.receiverId === groupId)
                   .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
    },

    sendMessage: (msg: Message) => {
        const msgs = StorageService.getAllMessages();
        msgs.push(msg);
        StorageService.setItem(STORAGE_KEYS.MESSAGES, msgs);
    },

    getConversationsForUser: (userId: string): string[] => {
        const msgs = StorageService.getAllMessages();
        const participants = new Set<string>();
        msgs.forEach(m => {
            if (m.senderId === userId) participants.add(m.receiverId);
            if (m.receiverId === userId) participants.add(m.senderId);
        });
        return Array.from(participants).filter(id => !id.startsWith('chat_')); // Exclude group chats
    },

    // --- IOT ---
    getIoTDevices: (school: string, city: string): IoTDevice[] => {
        // Mock data generator if empty
        let devices = StorageService.getItem<IoTDevice>(STORAGE_KEYS.IOT_DEVICES);
        const myDevices = devices.filter(d => d.school === school && d.city === city);

        if (myDevices.length === 0) {
            // Create some mock devices
            const newDevices: IoTDevice[] = [
                {
                    id: `iot-env-${Date.now()}`,
                    school, city,
                    type: 'ENV_SENSOR',
                    name: 'Capteur Salle 101',
                    status: 'ONLINE',
                    provider: 'MarocIoT Solutions',
                    lastUpdate: new Date().toISOString(),
                    data: { temperature: 24, humidity: 45, co2: 400 }
                },
                {
                    id: `iot-gps-${Date.now()}`,
                    school, city,
                    type: 'GPS_TRACKER',
                    name: 'Bus Scolaire A',
                    status: 'ONLINE',
                    provider: 'GeoTrack MA',
                    lastUpdate: new Date().toISOString(),
                    data: { lat: 33.5731, lng: -7.5898, speed: 45 }
                }
            ];
            devices = [...devices, ...newDevices];
            StorageService.setItem(STORAGE_KEYS.IOT_DEVICES, devices);
            return newDevices;
        }

        // Update mock data for liveliness
        const updated = myDevices.map(d => {
            if (d.type === 'ENV_SENSOR') {
                d.data.temperature = 20 + Math.floor(Math.random() * 5);
                d.data.co2 = 400 + Math.floor(Math.random() * 100);
            }
            d.lastUpdate = new Date().toISOString();
            return d;
        });

        // Don't save updated mock data constantly to avoid thrashing, just return dynamic
        return updated;
    },

    getProfessorsForStudent: (user: User): User[] => {
        const users = StorageService.getUsers();
        const profs = users.filter(u => u.role === UserRole.PROFESSOR && u.school === user.school && u.city === user.city);
        // In a real app, filtering by enrolled classes match would be better
        return profs.filter(p => p.assignedSections?.some(c => (user.enrolledClasses || []).includes(c)));
    }
};

