            q.status === 'PUBLISHED' && 
            user.enrolledClasses?.some(cls => q.assignedClasses.includes(cls))
        );
        setQuizzes(myQuizzes);

        if (autoLaunchQuizId) {
            const quiz = myQuizzes.find(q => q.id === autoLaunchQuizId);
            if (quiz) setActiveQuiz(quiz);
        }
