    const handleJoinWhiteboard = (code: string) => {
        if (!code) return;
        setActiveWhiteboardCode(code.trim());
    };

    if (activeQuiz) {
        return <QuizTaker quiz={activeQuiz} studentId={user.id} studentName={user.name} onComplete={() => setActiveQuiz(null)} />;
