                        <input className="border rounded p-2" placeholder={type === LessonType.VIDEO ? t('videoUrl') : "Lien PDF/Drive"} value={url} onChange={e => setUrl(e.target.value)} />
                        <textarea className="border rounded p-2" placeholder={t('lessonDesc')} value={desc} onChange={e => setDesc(e.target.value)} />

                        <div className="bg-gray-50 p-2 rounded">
                            <label className="text-xs font-bold text-gray-500 block mb-2">{t('assignedClasses')}</label>
