                        <h3 className="font-bold text-lg text-gray-800 mb-1">{lesson.title}</h3>
                        <p className="text-sm text-gray-500 line-clamp-2 mb-4">{lesson.description}</p>
                        <div className="flex justify-between items-center text-xs text-gray-400 border-t pt-3">
                            <span>{lesson.assignedClasses.join(', ')}</span>
                            <a href={lesson.contentUrl} target="_blank" rel="noreferrer" className="text-indigo-600 font-bold hover:underline flex items-center gap-1">
                                {t('viewContent')} <ChevronRight className="w-3 h-3"/>
