const StaffRoomView: React.FC<{ user: User }> = ({ user }) => {
    const { t } = useLanguage();
    const [messages, setMessages] = useState<Message[]>([]);
    const [input, setInput] = useState('');
    const bottomRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        // Load chat for 'staff_room' group
        const load = () => {
            const msgs = StorageService.getGroupMessages('staff_room');
            setMessages(msgs);
        };
        load();
        const interval = setInterval(load, 3000); // Polling 3s
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    const handleSend = (e: React.FormEvent) => {
        e.preventDefault();
        if (!input.trim()) return;

        const msg: Message = {
            id: `stf-${Date.now()}`,
            senderId: user.id,
            senderName: user.name,
            receiverId: 'staff_room', // Special Group ID
            content: input,
            timestamp: new Date().toISOString(),
            read: false
        };
        StorageService.sendMessage(msg);
        setMessages(prev => [...prev, msg]);
        setInput('');
    };

    return (
        <div className="h-[calc(100vh-140px)] flex flex-col bg-white rounded-xl shadow-sm border overflow-hidden animate-fade-in">
            <div className="p-4 border-b bg-amber-50 flex items-center justify-between">
                <h2 className="font-bold text-amber-800 flex items-center gap-2">
                    <Coffee className="w-5 h-5"/> {t('staffRoom')}
                </h2>
                <span className="text-xs text-amber-600 bg-amber-100 px-2 py-1 rounded-full">Discussion commune</span>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-[url('https://www.transparenttextures.com/patterns/notebook.png')]">
                {messages.map(m => {
                    const isMe = m.senderId === user.id;
                    return (
                        <div key={m.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[70%] p-3 rounded-xl shadow-sm ${isMe ? 'bg-amber-600 text-white rounded-br-none' : 'bg-white border text-gray-800 rounded-bl-none'}`}>
                                {!isMe && <div className="text-[10px] font-bold text-amber-600 mb-1">{m.senderName}</div>}
                                <p className="text-sm">{m.content}</p>
                                <div className={`text-[10px] text-right mt-1 ${isMe ? 'text-amber-200' : 'text-gray-400'}`}>
                                    {new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                </div>
                            </div>
                        </div>
                    );
                })}
                <div ref={bottomRef} />
            </div>

            <form onSubmit={handleSend} className="p-4 bg-white border-t flex gap-2">
                <input 
                    className="flex-1 bg-gray-50 border rounded-full px-4 py-2 focus:ring-2 focus:ring-amber-500 outline-none"
                    placeholder="Partager une info avec les collègues..."
                    value={input}
                    onChange={e => setInput(e.target.value)}
                />
                <button type="submit" className="bg-amber-600 text-white p-2 rounded-full hover:bg-amber-700 transition">
                    <Send className="w-5 h-5 rtl:flip"/>
                </button>
            </form>
        </div>
    );
};

